KB.lade("oesterreich",[{"id":"oesterreich-wiener-schnitzel","name":"Wiener Schnitzel","originalname":"Wiener Schnitzel vom Kalb","kueche":"oesterreich","region":"Wien","beliebtheit":97,"hauptkategorie":"fleisch","fleischsorte":"kalb","gang":"hauptgericht","kurz":"Hauchdünnes Kalbsschnitzel in goldener, wellig aufgeplusterter Panade, in reichlich Fett schwimmend ausgebacken – mit Zitrone, lauwarmem Erdäpfelsalat und frittierter Petersilie.","hintergrund":"Das Wiener Schnitzel ist das berühmteste Gericht der österreichischen Küche und in Österreich rechtlich geschützt: Als „Wiener Schnitzel“ darf nur ein paniertes Kalbsschnitzel verkauft werden, alles andere muss etwa „vom Schwein“ oder „Wiener Art“ heißen. Der Name ist seit dem frühen 19. Jahrhundert in Wiener Kochbüchern belegt; die beliebte Geschichte, Feldmarschall Radetzky habe das Rezept 1857 aus Mailand mitgebracht, hält die Sprachforschung für eine Legende. Typisch ist die „soufflierte“ Panade, die sich in heißem Fett vom Fleisch abhebt und Wellen wirft. Gegessen wird es in Wien klassisch mit Zitrone, Petersilkartoffeln, Erdäpfel- oder grünem Salat und Preiselbeeren.","portionen":4,"zeit":{"vorbereitung":40,"garen":12,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Schnitzel","liste":[{"menge":4,"einheit":"Stück","name":"Kalbsschnitzel aus der Oberschale (Kalbsschale oder Nuss), je ca. 150 g","hinweis":"beim Metzger „zum Schnitzeln“ schneiden und eventuell schon klopfen lassen"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":"fein"},{"menge":80,"einheit":"g","name":"glattes Mehl (Type 405)","hinweis":"Weizenmehl"},{"menge":3,"einheit":"Stück","name":"Eier (Größe M)","hinweis":""},{"menge":1,"einheit":"EL","name":"Milch oder Sahne","hinweis":"macht die Eimasse geschmeidiger"},{"menge":150,"einheit":"g","name":"feine Semmelbrösel","hinweis":"am besten selbst aus entrindeten, getrockneten Brötchen gerieben; sonst Paniermehl ohne Gewürze"},{"menge":500,"einheit":"g","name":"Butterschmalz","hinweis":"alternativ Schweineschmalz oder zur Hälfte beides"},{"menge":2,"einheit":"Stück","name":"unbehandelte Zitronen","hinweis":"in Spalten"}]},{"gruppe":"Für den lauwarmen Erdäpfelsalat","liste":[{"menge":800,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"z. B. Sieglinde oder Annabelle"},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel","hinweis":"sehr fein gewürfelt"},{"menge":150,"einheit":"ml","name":"heiße Rindsuppe oder Gemüsebrühe","hinweis":""},{"menge":3,"einheit":"EL","name":"milder Essig","hinweis":"Weißweinessig oder Apfelessig"},{"menge":4,"einheit":"EL","name":"Sonnenblumenöl","hinweis":""},{"menge":1,"einheit":"TL","name":"mittelscharfer Senf","hinweis":""},{"menge":null,"einheit":"","name":"Salz, Pfeffer, Schnittlauch","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Anrichten","liste":[{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"einige Zweige zum Frittieren"},{"menge":null,"einheit":"","name":"Preiselbeeren","hinweis":"nach Belieben, in Österreich oft dazu"}]}],"ausruestung":["Schwere Pfanne oder Sauteuse (ca. 28 cm, mindestens 5 cm hoch)","Plattiereisen oder Nudelholz","Gefrierbeutel oder Backpapier zum Klopfen","3 flache Teller","Bratenthermometer (optional)","Küchenpapier"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Nimm das Fleisch eine halbe Stunde vor dem Klopfen aus dem Kühlschrank, damit es sich weniger verkrampft. Wiege Mehl und Brösel ab, stelle die drei flachen Teller nebeneinander auf und schneide die Zitronen in Spalten. Koche die Kartoffeln für den Salat in der Schale in Salzwasser, sie brauchen je nach Größe 20–25 Minuten. Wasche die Petersilie, tupfe sie sehr gründlich trocken und zupfe die kleinen Zweige ab, denn nasse Kräuter spritzen später im heißen Fett. Alles griffbereit zu haben ist hier wichtig, weil das Ausbacken nur wenige Minuten dauert und du dann keine Hand frei hast.","dauer":25,"tipp":"Kalbfleisch von der Oberschale ist mager und fein faserig – genau richtig. Von der Keule geschnittene, zu dicke Scheiben werden beim Klopfen unregelmäßig."},{"titel":"Fleisch plattieren","aktion":"vorbereiten","text":"Lege jedes Schnitzel zwischen zwei Lagen Frischhaltefolie oder in einen aufgeschnittenen Gefrierbeutel und klopfe es mit der flachen Seite des Plattiereisens von der Mitte nach außen gleichmäßig auf etwa 4 mm. Schlage nicht mit der Spitze und nicht zu fest, sonst zerreißen die feinen Fasern und das Fleisch wird später faserig. Entferne Sehnen und Häutchen, ritze den Rand an vier Stellen leicht ein, damit sich das Schnitzel beim Braten nicht wölbt. Das Fleisch ist fertig geklopft, wenn es überall gleich dünn und fast durchscheinend rosa aussieht. Salze es erst unmittelbar vor dem Panieren leicht von beiden Seiten.","dauer":10,"tipp":"Gleichmäßige Dicke ist wichtiger als die Größe: dünne Stellen trocknen aus, dicke bleiben roh."},{"titel":"Lauwarmen Erdäpfelsalat ansetzen","aktion":"mischen","text":"Pelle die gekochten Kartoffeln noch heiß mit einer Gabel und einem Messer und schneide sie in etwa 3 mm dicke Scheiben direkt in eine Schüssel. Gieße sofort die heiße Brühe, den Essig und die Zwiebelwürfel darüber, gib Salz, Pfeffer und Senf dazu und hebe alles mit einem Löffel behutsam um. Warme Kartoffeln saugen die Flüssigkeit auf und geben Stärke ab – das bindet den Salat zu einer leicht cremigen Marinade. Gib zuletzt das Öl dazu und lass den Salat zugedeckt mindestens 15–20 Minuten ziehen. Er sollte glänzen, nicht schwimmen und lauwarm schmecken; schmecke am Ende nochmals mit Essig und Salz ab und streue Schnittlauch darüber.","dauer":20,"tipp":"Zu trockener Salat? Einen Schuss warme Brühe nachgießen. Wiener Erdäpfelsalat darf ruhig „saftig“ sein."},{"titel":"Panierstraße aufbauen","aktion":"panieren","text":"Gib das Mehl auf den ersten Teller, verquirle auf dem zweiten die Eier mit Milch und einer Prise Salz nur so lange, bis Eigelb und Eiweiß gerade verbunden sind – Schaum sollst du vermeiden. Schütte die Semmelbrösel locker auf den dritten Teller, ohne sie festzudrücken. Der Trick der Wiener Panade liegt darin, dass die Brösel das Fleisch nur berühren und nicht an ihm kleben: Später dehnt sich die Eihülle im Fett aus und hebt die Panade ab. Arbeite mit einer „trockenen“ und einer „nassen“ Hand, damit du dir keine Panadeklumpen an die Finger holst.","dauer":5,"tipp":""},{"titel":"Fett erhitzen","aktion":"vorbereiten","text":"Schmilz das Butterschmalz in einer hohen, schweren Pfanne so, dass es mindestens 2–3 cm hoch steht – das Schnitzel muss darin frei schwimmen können. Erhitze es auf etwa 160–170 °C; wer kein Thermometer hat, taucht einen Holzlöffelstiel ein, an dem sofort feine Bläschen aufsteigen sollen. Ein Semmelbrösel muss beim Hineinwerfen lebhaft zischen, aber darf nicht sofort dunkel werden. Ist das Fett zu kalt, saugt sich die Panade voll und wird schwer, ist es zu heiß, bräunt sie außen, bevor sie sich aufblähen kann. Heize die Teller im Backofen bei 80 °C vor.","dauer":5,"tipp":"Butterschmalz verträgt hohe Hitze, ohne zu verbrennen, und gibt den klassischen nussig-buttrigen Geschmack."},{"titel":"Schnitzel panieren","aktion":"panieren","text":"Wende das gesalzene Schnitzel erst im Mehl und klopfe das überschüssige Mehl sorgfältig ab, sodass nur ein hauchdünner Film bleibt. Ziehe es dann durch die Eimasse, streife sie an der Gabel kurz ab und lege das Fleisch in die Brösel. Wende es darin, ohne zu drücken, und schüttle die losen Brösel leicht ab. Paniere die Schnitzel erst dann, wenn das Fett die Temperatur erreicht hat, sonst weicht die Hülle auf. Die Panade soll rundum gleichmäßig, aber locker sitzen und beim Anheben noch etwas „arbeiten“.","dauer":5,"tipp":"Nicht andrücken – das ist der häufigste Fehler und verhindert die Wellen."},{"titel":"Ausbacken und soufflieren","aktion":"frittieren","text":"Lege zwei Schnitzel gleichzeitig mit Schwung ins heiße Fett – es zischt und schäumt kurz. Schwenke die Pfanne sofort in leichten kreisenden Bewegungen und schöpfe mit einem Löffel immer wieder heißes Fett über die Oberseite; dadurch schiebt der entstehende Dampf die Panade vom Fleisch weg, und sie wirft die typischen Wellen. Backe das Schnitzel etwa 1½ Minuten, bis die Unterseite goldgelb ist, und wende es mit einer Gabel oder Zange. Nach weiteren 1–1½ Minuten ist die zweite Seite fertig. Die Panade soll hellgolden bis goldgelb sein, nicht braun, und das Fett soll beim Backen leise brutzeln, nicht spritzen.","dauer":4,"tipp":"Auch beim Wenden nicht in die Panade stechen, sondern am Rand greifen."},{"titel":"Abtropfen lassen","aktion":"ruhen","text":"Hebe die Schnitzel mit der Zange aus dem Fett, lasse das Fett kurz abtropfen und lege sie auf eine doppelte Lage Küchenpapier. Tupfe die Oberseite nur ganz leicht ab; wenn du sie zu fest drückst, fällt die Panade zusammen. Salze die Schnitzel sofort ganz leicht mit etwas feinem Salz, solange noch Fett an der Oberfläche glänzt, damit es haftet. Gib sie in den vorgeheizten Ofen bei 80 °C, wenn du in Etappen arbeitest, aber lege kein Deckel auf – Dampf macht die Panade weich. Die zweite Runde brät genauso, falls nötig.","dauer":2,"tipp":""},{"titel":"Petersilie frittieren","aktion":"frittieren","text":"Gib die sehr trockenen Petersilienzweige für 10–15 Sekunden in das noch heiße Fett, bis sie grün und knusprig sind und das Zischen nachlässt. Hebe sie mit einer Schaumkelle heraus und lasse sie auf Küchenpapier abtropfen. Sie schmecken salzig-würzig, glasig knusprig und sind in Wien die klassische Garnitur. Bei zu langer Frittierzeit werden sie bitter und braun. Wenn das Fett inzwischen viele Panadereste hat, filtere es vorher durch ein Sieb oder verwende frisches Fett.","dauer":1,"tipp":""},{"titel":"Anrichten und servieren","aktion":"anrichten","text":"Richte die Schnitzel auf vorgewärmten flachen Tellern an – nicht übereinander und nicht zugedeckt. Lege eine Zitronenspalte und einen Hauch frittierte Petersilie dazu, den Erdäpfelsalat gibst du in eine kleine Schale daneben und gibst Preiselbeeren dazu, wenn du magst. Beträufle das Schnitzel erst am Tisch mit Zitrone, damit die Panade nicht aufweicht. Gegessen wird sofort: Innerhalb von fünf Minuten ist die Panade am knusprigsten, das Fleisch saftig und zart. Das Schnitzel sollte so groß sein, dass es über den Tellerrand lappt.","dauer":0,"tipp":""}],"profitipps":["Fett muss reichlich sein und die Schnitzel müssen darin schwimmen – nur so entsteht die aufgeplusterte Panade.","Panade nie andrücken und das Fleisch nur ganz dünn mehlen, sonst klebt alles fest und wellt nicht.","Fett auf 160–170 °C halten; nach dem zweiten Schnitzel gegebenenfalls Panadereste aus dem Fett fischen, damit nichts bitter wird.","Frische, entrindete Semmelbrösel aus Weißbrot geben die leichteste Panade; nicht zu fein mahlen.","Das Schnitzel immer sofort essen und nicht abdecken."],"varianten":["Wiener Schnitzel vom Schwein (muss in Österreich so deklariert werden)","Putenschnitzel „Wiener Art“","Cordon bleu mit Schinken und Käse gefüllt","Backhendl im selben Panadeverfahren"],"beilagen":["Lauwarmer Erdäpfelsalat","Petersilkartoffeln","Grüner Salat mit Kürbiskernöl","Preiselbeeren","Gurkensalat"],"getraenk":"Grüner Veltliner, Gelber Muskateller oder ein kühles Helles","koeche":[{"name":"Toni Mörwald","bezug":"Der niederösterreichische Spitzenkoch ist auf der Rezeptseite eines Flusskreuzfahrt-Anbieters mit einem Wiener-Schnitzel-Rezept vertreten: gleichmäßig plattiertes Kalbfleisch, Ausbacken in einer Mischung aus Butter und Schmalz, ein ständig bewegtes Schwimmen im Fett und Petersilkartoffeln dazu.","quelle":"https://www.vikingrivercruises.co.uk/why-viking/community/viking-recipes/main-courses/wiener-schnitzel.html"}],"quellen":[{"titel":"Wiener Schnitzel – Wikipedia (en)","url":"https://en.wikipedia.org/wiki/Wiener_Schnitzel"},{"titel":"Wiener Schnitzel – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Wiener_Schnitzel"},{"titel":"Wiener Schnitzel von Toni Mörwald – Viking Recipes","url":"https://www.vikingrivercruises.co.uk/why-viking/community/viking-recipes/main-courses/wiener-schnitzel.html"},{"titel":"Plachutta-Rezepte (Erdäpfelsalat, Backhuhn) – news.at","url":"https://www.news.at/news/rezepte-plachutta"}],"bild":"schnitzel","farben":["#d9a441","#f2d27a","#f4efe0"],"schlagworte":["Klassiker","Wien","Kalb","Nationalgericht"],"vegetarisch_moeglich":false},{"id":"oesterreich-kaiserschmarrn","name":"Kaiserschmarrn","originalname":"Kaiserschmarrn","kueche":"oesterreich","region":"Österreich / Alpen","beliebtheit":93,"hauptkategorie":"suess","gang":"dessert","kurz":"Luftig-fluffiger, in Butter gebackener Pfannkuchen, in Stücke gerissen und mit Puderzucker karamellisiert – mit Rumrosinen und Zwetschkenröster.","hintergrund":"Der Kaiserschmarrn gehört zu den bekanntesten Süßspeisen Österreichs und wird mit Kaiser Franz Joseph I. in Verbindung gebracht, der ihn besonders geschätzt haben soll. Zur Herkunft gibt es mehrere Geschichten: eine höfische Version, in der Kaiserin Elisabeth das Dessert verschmähte, und eine Almhütten-Legende, in der ein Senner dem jagenden Kaiser einen „Kaserschmarrn“ servierte. Das klassische Rezept enthält Rumrosinen und wird mit Zwetschkenröster (Pflaumenkompott) serviert; heute ist auch Apfelmus sehr verbreitet. In den Bergen isst man ihn nicht nur als Dessert, sondern auch als Mittagsgericht auf der Hütte.","portionen":4,"zeit":{"vorbereitung":20,"garen":20,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig","liste":[{"menge":250,"einheit":"g","name":"glattes Weizenmehl (Type 405)","hinweis":""},{"menge":400,"einheit":"ml","name":"Milch","hinweis":"Vollmilch, Zimmertemperatur"},{"menge":6,"einheit":"Stück","name":"Eier (Größe M)","hinweis":"getrennt"},{"menge":60,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Pck.","name":"Vanillezucker","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"Stück","name":"unbehandelte Zitrone","hinweis":"nur die abgeriebene Schale"},{"menge":80,"einheit":"g","name":"Rosinen","hinweis":"in Rum eingelegt"},{"menge":3,"einheit":"EL","name":"Rum","hinweis":"alternativ Apfelsaft"}]},{"gruppe":"Zum Backen und Servieren","liste":[{"menge":60,"einheit":"g","name":"Butter","hinweis":"zum Ausbacken, plus etwa 20 g zum Karamellisieren"},{"menge":3,"einheit":"EL","name":"Puderzucker","hinweis":"plus etwas zum Bestäuben"}]},{"gruppe":"Zwetschkenröster","liste":[{"menge":500,"einheit":"g","name":"Zwetschgen","hinweis":"entsteint und geviertelt"},{"menge":80,"einheit":"g","name":"Zucker","hinweis":""},{"menge":100,"einheit":"ml","name":"Rotwein oder Wasser","hinweis":""},{"menge":1,"einheit":"Stange","name":"Zimt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Gewürznelken","hinweis":""}]}],"ausruestung":["Große beschichtete oder gusseiserne Pfanne (28 cm)","Schneebesen oder Handmixer","Zwei Pfannenwender oder Gabeln","Topf für den Röster"],"schritte":[{"titel":"Mise en place und Rosinen einlegen","aktion":"vorbereiten","text":"Gib die Rosinen mit dem Rum in ein kleines Schälchen und lasse sie mindestens 15 Minuten ziehen, bis sie prall und weich sind. Trenne die Eier sorgfältig – schon ein Tropfen Eigelb im Eiweiß verhindert später steifen Schnee. Das Eiweiß kommt in eine fettfreie Schüssel, das Eigelb in eine zweite. Reibe die Zitronenschale ab, wiege Mehl und Zucker ab und stelle die Butter bereit. Wenn alle Zutaten Zimmertemperatur haben, lässt sich der Teig glatter rühren und das Eiweiß schlägt höher auf.","dauer":15,"tipp":"Der Rum kann durch Apfelsaft ersetzt werden, wenn Kinder mitessen."},{"titel":"Zwetschkenröster kochen","aktion":"koecheln","text":"Gib Zwetschgen, Zucker, Wein oder Wasser, Zimtstange und Nelken in einen Topf. Erhitze alles langsam und lasse es bei kleiner Hitze 10–15 Minuten leise köcheln, bis die Früchte weich sind, aber noch Form haben und ein dunkelroter, leicht dickflüssiger Saft entsteht. Rühre nur selten um. Entferne Zimt und Nelken. Der Röster soll fruchtig-säuerlich und warm duften; schmecke ihn mit etwas Zucker oder Zitronensaft ab. Er schmeckt warm oder lauwarm am besten.","dauer":15,"tipp":""},{"titel":"Teig anrühren","aktion":"mischen","text":"Verrühre Eigelb, Milch, Vanillezucker, Zitronenschale und etwa die Hälfte des Zuckers glatt. Siebe das Mehl darüber und rühre es mit einem Schneebesen nur so lange ein, bis ein klümpchenfreier, dickflüssiger Teig entsteht, der in Bändern vom Löffel läuft. Zu langes Rühren aktiviert das Klebereiweiß im Mehl und macht den Schmarrn gummiartig. Lasse den Teig 5–10 Minuten stehen, damit das Mehl quellen kann und die Konsistenz gleichmäßig wird.","dauer":10,"tipp":""},{"titel":"Eischnee schlagen","aktion":"aufschlagen","text":"Schlage das Eiweiß mit dem Salz zunächst langsam an und füge dann den restlichen Zucker nach und nach zu. Schlage es auf höchster Stufe, bis es steif und glänzend ist und beim Umdrehen der Schüssel nicht herausfällt. Ein fest geschlagener Eischnee ist der Grund, warum der Kaiserschmarrn so locker wird: Die Luftblasen dehnen sich in der Hitze aus und heben den Teig. Schlage ihn nicht trocken, sonst wird er bröckelig und lässt sich schlecht einarbeiten.","dauer":5,"tipp":""},{"titel":"Eischnee unterheben","aktion":"mischen","text":"Gib ein Drittel des Eischnees zum Teig und rühre ihn kräftig unter, um den Teig aufzulockern. Hebe dann den Rest in zwei Portionen vorsichtig mit einem Teigschaber unter, indem du von unten nach oben durch die Masse führst. Arbeite zügig und sanft, damit möglichst wenig Luft entweicht. Es dürfen noch kleine Eischneeinseln sichtbar sein. Streue zum Schluss die abgetropften Rosinen locker darüber und hebe sie ein einziges Mal unter.","dauer":3,"tipp":""},{"titel":"Teig anbacken","aktion":"braten","text":"Erhitze die Butter in der großen Pfanne bei mittlerer Hitze, bis sie schäumt und nussig duftet, aber nicht bräunt. Gieße den Teig ein, sodass er etwa 2 cm hoch steht, und streiche ihn glatt. Backe ihn 3–4 Minuten bei mittlerer bis niedriger Hitze, bis die Unterseite goldbraun und die Oberfläche fast gestockt, aber noch leicht feucht ist. Du erkennst das daran, dass der Rand sich leicht löst und die Oberfläche matt wird. Wenn die Pfanne ofenfest ist, kannst du sie für 5 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft) in den Ofen schieben, damit die Mitte gleichmäßig gar wird.","dauer":5,"tipp":""},{"titel":"Wenden und zerreißen","aktion":"braten","text":"Teile den Teigfladen in der Pfanne mit dem Wender in vier Viertel und drehe jedes Viertel um. Backe die zweite Seite 2–3 Minuten, bis sie gold ist. Gib ein paar Butterflöckchen dazu und reiße den Teig mit zwei Gabeln oder Wendern in unregelmäßige Stücke von 3–4 cm. Wende sie ständig, damit alle Seiten Farbe nehmen und das Innere gar wird. Der Schmarrn sollte außen leicht knusprig und innen weich und luftig sein; zu feuchte Stellen brauchen noch einen Moment.","dauer":4,"tipp":""},{"titel":"Karamellisieren","aktion":"braten","text":"Streue den Puderzucker über den Schmarrn und lasse ihn unter häufigem Wenden bei mittlerer Hitze 1–2 Minuten karamellisieren, bis die Stücke goldbraun glänzen und süß duften. Gib die restlichen 20 g Butter dazu, damit alles schön glasiert wird. Achte darauf, dass der Zucker nicht schwarz wird, denn dann schmeckt er bitter. Nimm die Pfanne sofort vom Herd, sobald die Stücke einen leichten Glanz haben.","dauer":2,"tipp":"Ein Spritzer Rum zum Schluss gibt Aroma."},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile den Kaiserschmarrn sofort auf vorgewärmte Teller und stäube Puderzucker darüber. Reiche den warmen Zwetschkenröster extra, damit jeder nach Geschmack dosieren kann. Traditionell wird er direkt aus der Pfanne serviert und gleich gegessen, weil er mit der Zeit zusammenfällt. Wenn du magst, gib noch einen Klecks Schlagsahne oder Vanilleeis dazu. Reste lassen sich am nächsten Tag in der Pfanne kurz aufbraten.","dauer":0,"tipp":""}],"profitipps":["Eischnee richtig steif schlagen und sehr vorsichtig unterheben – er ist der Auftrieb des Schmarrns.","Nicht zu heiß backen: Der Teig soll gleichmäßig stocken, bevor er zerrissen wird.","Teig nicht zu dünn ausgießen, damit er innen fluffig bleibt.","Zum Schluss erst karamellisieren, nicht früher, sonst brennt der Zucker an.","Stücke nicht zu klein zerreißen – rustikale Brocken sind typisch."],"varianten":["Mit Äpfeln oder Kirschen im Teig","Topfenschmarrn mit Quark","Semmelschmarrn aus altbackenen Brötchen","Karamellisierter Schmarrn mit Mandeln und Preiselbeeren"],"beilagen":["Zwetschkenröster","Apfelmus","Preiselbeerkompott","Vanilleeis"],"getraenk":"Heißer Kaffee mit Obers oder ein Glas Beerenauslese","koeche":[],"quellen":[{"titel":"Kaiserschmarrn – Wikipedia (en)","url":"https://en.wikipedia.org/wiki/Kaiserschmarrn"},{"titel":"Kaiserschmarrn – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Kaiserschmarrn"},{"titel":"TasteAtlas – Austrian dishes ranking","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"pfannkuchen","farben":["#d9a24b","#f0d28a","#7b2d3b"],"schlagworte":["Süßspeise","Kaiser Franz Joseph","Hüttenküche"],"vegetarisch_moeglich":true},{"id":"oesterreich-apfelstrudel","name":"Apfelstrudel","originalname":"Wiener Apfelstrudel","kueche":"oesterreich","region":"Wien","beliebtheit":92,"hauptkategorie":"suess","gang":"dessert","kurz":"Hauchdünn gezogener Strudelteig, gefüllt mit saftigen Äpfeln, Zimt, Rosinen und buttergerösteten Bröseln – goldbraun gebacken, warm mit Vanillesauce.","hintergrund":"Der Apfelstrudel gilt als eines der Nationalgerichte Österreichs. Die Kunst des hauchdünn ausgezogenen Teigs kam in der Zeit der Habsburger über Ungarn und den Balkan nach Wien; das älteste bekannte Rezept ist eine handgeschriebene Aufzeichnung aus der Wienbibliothek, die auf Ende des 17. Jahrhunderts datiert wird. Die klassische Füllung besteht aus säuerlichen Äpfeln, in Butter gerösteten Semmelbröseln, Zucker, Zimt und Rosinen. Gegessen wird er lauwarm, mit Staubzucker bestreut, oft mit Vanillesauce oder Schlagobers.","portionen":6,"zeit":{"vorbereitung":60,"garen":40,"ruhen":60},"schwierigkeit":3,"zutaten":[{"gruppe":"Für den Strudelteig","liste":[{"menge":250,"einheit":"g","name":"Mehl (griffig oder Type 550)","hinweis":"kleberstarkes Mehl lässt sich besser ziehen"},{"menge":1,"einheit":"Stück","name":"Ei (Größe M)","hinweis":""},{"menge":125,"einheit":"ml","name":"lauwarmes Wasser","hinweis":""},{"menge":3,"einheit":"EL","name":"Sonnenblumenöl","hinweis":"plus etwas zum Bestreichen"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"Essig","hinweis":"macht den Teig geschmeidiger"}]},{"gruppe":"Für die Füllung","liste":[{"menge":1,"einheit":"kg","name":"säuerliche Äpfel","hinweis":"Boskoop, Elstar oder Topaz; mürbe Sorten wie Boskoop sind ideal"},{"menge":80,"einheit":"g","name":"Butter","hinweis":""},{"menge":80,"einheit":"g","name":"Semmelbrösel","hinweis":""},{"menge":100,"einheit":"g","name":"Zucker","hinweis":""},{"menge":2,"einheit":"TL","name":"Zimt","hinweis":""},{"menge":60,"einheit":"g","name":"Rosinen","hinweis":"in 2 EL Rum eingeweicht"},{"menge":1,"einheit":"Stück","name":"Zitrone","hinweis":"Saft und Schale"},{"menge":40,"einheit":"g","name":"gehackte Walnüsse oder Mandeln","hinweis":"optional"}]},{"gruppe":"Zum Bestreichen und Servieren","liste":[{"menge":50,"einheit":"g","name":"flüssige Butter","hinweis":""},{"menge":null,"einheit":"","name":"Puderzucker","hinweis":"zum Bestäuben"},{"menge":null,"einheit":"","name":"Vanillesauce oder Schlagobers","hinweis":"zum Servieren"}]}],"ausruestung":["Großes sauberes Leinentuch (ca. 80 x 80 cm)","Backblech mit Backpapier","Teigschaber","Pinsel","Rührschüssel","Pfanne"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und heize den Backofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor. Lege die Rosinen in den Rum, damit sie quellen. Stelle eine Schüssel zum Stülpen über den Teig bereit, bestäube das Leinentuch mit Mehl und lege Backpapier aufs Blech. Alles sollte griffbereit sein, denn der Teig soll nach dem Ziehen nicht antrocknen. Wasche die Äpfel und halte Zitronensaft bereit, damit sie nicht braun werden.","dauer":10,"tipp":""},{"titel":"Strudelteig kneten und schlagen","aktion":"kneten","text":"Gib Mehl, Ei, Wasser, Öl, Salz und Essig in eine Schüssel und knete alles 8–10 Minuten kräftig durch, bis ein glatter, weicher Teig entsteht, der nicht mehr klebt. Hebe ihn dann hoch und schlage ihn mehrfach kräftig auf die Arbeitsfläche, bis er seidig glänzt und Blasen wirft. Dieses Schlagen entwickelt das Klebergerüst, das später ein hauchdünnes Ausziehen ermöglicht. Forme den Teig zu einer Kugel, bestreiche ihn dünn mit Öl und lasse ihn unter einer vorgewärmten Schüssel mindestens 30–60 Minuten ruhen.","dauer":15,"tipp":"Der Teig ist richtig, wenn er sich wie ein Ohrläppchen anfühlt: weich, elastisch und nicht klebrig."},{"titel":"Brösel rösten","aktion":"braten","text":"Erhitze die Butter in einer Pfanne bei mittlerer Hitze, bis sie leise schäumt und nach Nuss duftet. Gib die Semmelbrösel hinein und röste sie unter ständigem Rühren 3–4 Minuten, bis sie gleichmäßig goldbraun sind. Die gerösteten Brösel nehmen später den Saft der Äpfel auf und verhindern, dass der Teigboden durchweicht und der Strudel matschig wird. Nimm sie sofort aus der heißen Pfanne und lasse sie auf einem Teller abkühlen; sie rösten sonst nach und werden bitter. Die Farbe sollte der von hellem Karamell entsprechen.","dauer":5,"tipp":""},{"titel":"Äpfel vorbereiten","aktion":"schneiden","text":"Schäle die Äpfel, entferne das Kerngehäuse und schneide sie in dünne Blättchen von etwa 3 mm oder hobele sie grob. Vermische sie sofort mit Zitronensaft und -schale, Zucker, Zimt, Rosinen (abgetropft) und Nüssen. Lasse die Mischung nur kurz stehen, weil das Salz im Zucker den Äpfeln Saft entzieht und sie sonst wässrig werden. Gib den Saft nicht in den Strudel, sondern schöpfe die Äpfel mit einer Schaumkelle heraus.","dauer":15,"tipp":""},{"titel":"Teig ausziehen","aktion":"ausrollen","text":"Rolle den Teig auf einem bemehlten Tuch zunächst mit dem Nudelholz so dünn wie möglich aus. Streiche dann mit den Handrücken unter den Teig und ziehe ihn vorsichtig von der Mitte nach außen auseinander, bis er hauchdünn und fast durchsichtig ist – man soll eine Zeitung durchlesen können. Arbeite mit den Handrücken, nicht mit den Fingerspitzen, damit keine Löcher entstehen. Schneide den dicken Rand ab, falls nötig, und lasse den Teig 2–3 Minuten ruhen.","dauer":10,"tipp":""},{"titel":"Füllen","aktion":"fuellen","text":"Bestreiche den gezogenen Teig mit zerlassener Butter. Verteile die gerösteten Brösel auf der vorderen Hälfte des Teigs und gib die abgetropfte Apfelmasse darauf, sodass etwa zwei Drittel der Fläche gefüllt sind und rundherum ein Rand von 3 cm bleibt. Schlage die Seitenränder nach innen ein, damit nichts ausläuft. Hebe dann das Tuch an der Füllungsseite an und lasse den Strudel mithilfe des Tuchs locker aufrollen, bis die Naht unten liegt. Er darf nicht zu fest gerollt werden, denn der Teig dehnt sich beim Backen und die Äpfel quellen auf.","dauer":5,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Hebe den Strudel mit dem Tuch aufs Backblech, die Naht muss unten liegen, und biege ihn bei Bedarf zu einem Hufeisen. Bestreiche ihn dick mit flüssiger Butter und backe ihn auf der mittleren Schiene 35–40 Minuten bei 200 °C Ober-/Unterhitze (180 °C Umluft). Bestreiche ihn nach etwa 15 Minuten ein zweites Mal mit Butter, damit die Oberfläche knusprig und goldbraun wird. Er ist fertig, wenn die Kruste braun glänzt, Blasen wirft und es intensiv nach Zimt und gebackenen Äpfeln duftet. Achte darauf, dass der Teig nicht zu dunkel wird – im Zweifel mit Alufolie abdecken.","dauer":40,"tipp":""},{"titel":"Ruhen und anrichten","aktion":"anrichten","text":"Lasse den fertigen Strudel 10 Minuten auf dem Blech ruhen, damit sich der austretende Apfelsaft setzt und er sich sauber schneiden lässt. Bestäube ihn großzügig mit Puderzucker und schneide ihn mit einem scharfen Sägemesser in 3–4 cm breite Stücke, ohne zu drücken. Serviere ihn lauwarm mit Vanillesauce oder leicht geschlagenem Obers. Am besten schmeckt er am selben Tag; Reste kannst du zugedeckt aufbewahren und am nächsten Tag bei 150 °C 10 Minuten im Ofen wieder knusprig machen.","dauer":10,"tipp":""}],"profitipps":["Teig lange kneten und schlagen und danach mindestens 30 Minuten ruhen lassen – sonst reißt er beim Ziehen.","Äpfel erst kurz vor dem Füllen mischen, damit sie nicht ausbluten.","Brösel in Butter rösten, sie nehmen überschüssigen Saft auf.","Den Strudel vor dem Schneiden etwas abkühlen lassen, dann bleibt die Füllung drin.","Der Teig darf nicht antrocknen: Immer unter einer Schüssel oder einem feuchten Tuch aufbewahren."],"varianten":["Topfenstrudel mit Quarkfüllung","Mohnstrudel","Milchrahmstrudel mit Eiermilch","Strudel mit Blätterteig als schnelle Variante"],"beilagen":["Vanillesauce","Schlagobers","Vanilleeis"],"getraenk":"Verlängerter oder Melange, alternativ ein Glas Prosecco","koeche":[],"quellen":[{"titel":"Apple strudel – Wikipedia","url":"https://en.wikipedia.org/wiki/Apple_strudel"},{"titel":"Apfelstrudel – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Apfelstrudel"},{"titel":"TasteAtlas – Austrian dishes ranking","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"kuchen","farben":["#c9853b","#e8c07a","#7a4a1f"],"schlagworte":["Klassiker","Wiener Kaffeehaus","Mehlspeise"],"vegetarisch_moeglich":true},{"id":"oesterreich-sachertorte","name":"Sachertorte","originalname":"Sacher-Torte","kueche":"oesterreich","region":"Wien","beliebtheit":90,"hauptkategorie":"suess","gang":"kuchen","kurz":"Saftiger Schokoladenkuchen mit dünner Marillenmarmelade-Schicht und glänzender, dunkler Glasur – mit ungesüßtem Schlagobers serviert.","hintergrund":"Die Sachertorte wird Franz Sacher zugeschrieben, der sie der Überlieferung nach 1832 als junger Lehrling für Fürst Metternich erfand; belegt ist das nur durch spätere Erzählungen, und auch der genaue Ort ist unsicher. Sein Sohn Eduard machte sie im Wiener Hotel Sacher berühmt. Im 20. Jahrhundert stritten sich das Hotel Sacher und die Konditorei Demel jahrelang vor Gericht darum, wer die „Original Sacher-Torte“ verkaufen darf; der Vergleich von 1963 teilte die Rechte auf. Typisch sind der gedämpfte, nicht zu süße Schokoladengeschmack, eine dünne Schicht Marillenmarmelade unter der Glasur und die Begleitung durch ungesüßtes Schlagobers.","portionen":12,"zeit":{"vorbereitung":50,"garen":60,"ruhen":300},"schwierigkeit":3,"zutaten":[{"gruppe":"Für den Teig (Springform 24 cm)","liste":[{"menge":150,"einheit":"g","name":"Zartbitterschokolade (ca. 60 % Kakao)","hinweis":"fein gehackt"},{"menge":150,"einheit":"g","name":"weiche Butter","hinweis":"Zimmertemperatur"},{"menge":120,"einheit":"g","name":"Puderzucker (Staubzucker)","hinweis":""},{"menge":6,"einheit":"Stück","name":"Eier (Größe M)","hinweis":"getrennt, Zimmertemperatur"},{"menge":60,"einheit":"g","name":"Zucker","hinweis":"für den Eischnee"},{"menge":150,"einheit":"g","name":"glattes Weizenmehl (Type 405)","hinweis":"gesiebt"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"Vanillezucker oder Mark einer halben Vanilleschote","hinweis":""}]},{"gruppe":"Zum Bestreichen und für die Glasur","liste":[{"menge":300,"einheit":"g","name":"Marillenmarmelade (Aprikosenkonfitüre)","hinweis":"möglichst feinfruchtig, ohne Stücke"},{"menge":2,"einheit":"EL","name":"Rum oder Wasser","hinweis":"zum Verflüssigen der Marmelade"},{"menge":200,"einheit":"g","name":"Zartbitter-Kuvertüre","hinweis":""},{"menge":120,"einheit":"g","name":"Zucker","hinweis":""},{"menge":100,"einheit":"ml","name":"Wasser","hinweis":""},{"menge":1,"einheit":"EL","name":"Butter","hinweis":"für die Form"},{"menge":250,"einheit":"ml","name":"Schlagobers (Sahne)","hinweis":"ungesüßt, zum Servieren"}]}],"ausruestung":["Springform 24 cm","Handrührgerät","Teigschaber","Kuchengitter","kleiner Topf","Palette oder großes Messer","Backpapier"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Heize den Backofen auf 170 °C Ober-/Unterhitze (150 °C Umluft) vor. Fette den Boden und den Rand der Form mit Butter ein, lege den Boden mit Backpapier aus und staube ihn mit etwas Mehl ein. Trenne die Eier und stelle sie auf Zimmertemperatur, denn kalte Eier und Butter verbinden sich schlechter. Wiege alle Zutaten ab und siebe das Mehl. Hacke die Schokolade für den Teig fein, damit sie gleichmäßig schmilzt.","dauer":15,"tipp":""},{"titel":"Schokolade schmelzen","aktion":"vorbereiten","text":"Schmilz die gehackte Schokolade in einer Schüssel über einem Topf mit knapp siedendem Wasser unter gelegentlichem Rühren. Das Wasser darf die Schüssel nicht berühren, und es darf kein Wasser in die Schokolade gelangen, sonst wird sie körnig. Nimm sie vom Wasserbad, sobald sie glatt und glänzend ist, und lasse sie auf etwa 35 °C abkühlen. Sie soll lauwarm sein, aber noch flüssig; zu heiße Schokolade bringt später die Butter zum Schmelzen.","dauer":8,"tipp":""},{"titel":"Butter-Eigelb-Masse schaumig rühren","aktion":"aufschlagen","text":"Schlage die weiche Butter mit dem Puderzucker und dem Vanillezucker in einer Schüssel mit dem Handrührgerät 5–8 Minuten, bis sie hell, cremig und beinahe weiß aussieht. Gib das Eigelb einzeln dazu und rühre jedes vollständig ein, bevor das nächste folgt. Die Masse soll luftig, glatt und deutlich voluminöser sein als zu Beginn; wirkt sie körnig, war die Butter zu kalt. Dieses lange Aufschlagen baut die feine, saftige Krume der Torte auf, deshalb solltest du nicht abkürzen.","dauer":8,"tipp":""},{"titel":"Schokolade untermischen","aktion":"mischen","text":"Rühre die lauwarme Schokolade in einem dünnen Strahl bei niedriger Geschwindigkeit in die Butter-Eigelb-Masse und rühre, bis alles gleichmäßig braun und glänzend aussieht. Streiche zwischendurch mit dem Teigschaber den Rand der Schüssel sauber ab, damit keine hellen Butternester bleiben. Die Masse ist jetzt schwer, aber geschmeidig und duftet intensiv nach Schokolade. Ist sie zu fest, war die Schokolade zu kalt; ist sie fettig und flüssig, war sie zu heiß – in diesem Fall kurz kalt stellen und erneut aufschlagen.","dauer":3,"tipp":""},{"titel":"Eischnee schlagen und unterheben","aktion":"aufschlagen","text":"Schlage das Eiweiß mit dem Salz in einer fettfreien Schüssel zunächst steif, lasse dabei den Zucker nach und nach einrieseln und schlage weiter, bis ein glänzender, standfester Schnee entsteht. Hebe ein Drittel unter die Schokomasse, damit sie lockerer wird. Siebe das Mehl über den Rest des Schnees und hebe es mit dem Teigschaber behutsam unter, im Wechsel mit der Schokomasse. Arbeite zügig und vorsichtig, ohne viel Luft zu zerstören; es dürfen keine Mehlnester bleiben.","dauer":5,"tipp":"Der Teig ist fertig, wenn er gleichmäßig braun und sehr luftig ist."},{"titel":"Backen","aktion":"backen","text":"Fülle den Teig in die vorbereitete Form, streiche ihn glatt und klopfe die Form einmal kurz auf die Arbeitsplatte, um große Luftblasen zu lösen. Backe den Kuchen auf der mittleren Schiene 55–60 Minuten bei 170 °C Ober-/Unterhitze (150 °C Umluft). Mache die Stäbchenprobe: Ein Holzstäbchen soll mit höchstens feinen, feuchten Krümeln herauskommen. Öffne den Ofen in den ersten 40 Minuten nicht, sonst fällt der Teig zusammen.","dauer":60,"tipp":""},{"titel":"Auskühlen lassen","aktion":"kuehlen","text":"Lasse den Kuchen nach dem Backen 10 Minuten in der Form ruhen, löse den Rand mit einem dünnen Messer und stürze ihn auf ein Kuchengitter. Ziehe das Backpapier ab und lasse ihn vollständig auskühlen, am besten 1–2 Stunden, denn auf einem warmen Kuchen verläuft die Marmelade und schmilzt die Glasur. Die Oberfläche hat sich beim Backen leicht gewölbt; schneide sie bei Bedarf mit einem langen Messer gerade, damit die Glasur später glatt aufliegt. Drehe den Kuchen dann so, dass die ebene Unterseite oben liegt.","dauer":90,"tipp":""},{"titel":"Aprikotieren","aktion":"vorbereiten","text":"Erwärme die Marillenmarmelade mit Rum oder Wasser unter Rühren, bis sie dünnflüssig ist, und streiche sie durch ein Sieb, wenn Fruchtstücke darin sind. Schneide den Kuchen waagerecht durch und bestreiche die untere Hälfte dünn mit Marmelade, wenn du die Variante mit Mittelschicht magst. Setze die obere Hälfte auf und bestreiche Oberfläche und Rand dünn und gleichmäßig mit der restlichen Marmelade. Diese Schicht heißt „Aprikotur“ und isoliert den Kuchen, sodass die Glasur nicht einsinkt. Lasse sie 30 Minuten antrocknen.","dauer":30,"tipp":""},{"titel":"Schokoladenglasur kochen","aktion":"kochen","text":"Koche Zucker und Wasser unter Rühren auf, bis sich der Zucker aufgelöst hat und die Mischung 1–2 Minuten sprudelnd gekocht hat. Nimm den Topf vom Herd und lasse ihn etwas abkühlen. Rühre die gehackte Kuvertüre in den Sirup und rühre langsam, bis sie geschmolzen und die Glasur dickflüssig und glänzend ist. Sie soll so zäh sein, dass sie vom Löffel in Bändern fließt. Wenn sie zu dick wird, wärme sie leicht an; zu heiß lässt sie matte Streifen zurück.","dauer":10,"tipp":"Rühre langsam, damit keine Luftblasen entstehen."},{"titel":"Glasieren","aktion":"anrichten","text":"Stelle den Kuchen auf ein Gitter über einem Blech. Gieße die Glasur in einem Zug in die Mitte und verstreiche sie mit einer Palette von der Mitte aus rasch nach außen und über den Rand, sodass er vollständig bedeckt ist. Streiche nur ein- bis zweimal, sonst wird die Oberfläche matt. Lasse die Glasur bei Zimmertemperatur 2 Stunden fest werden, bis sie matt glänzt und beim Berühren nicht mehr klebt. Stelle den Kuchen nicht in den Kühlschrank, weil die Glasur sonst beschlägt.","dauer":120,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Schneide die Torte mit einem scharfen, in heißes Wasser getauchten und abgetrockneten Messer in Stücke, damit die Glasur nicht splittert. Serviere jedes Stück mit einem Klecks ungesüßtem, nur leicht geschlagenem Schlagobers, das den süßen, dichten Kuchen ausgleicht. Die Sachertorte schmeckt am besten bei Zimmertemperatur und nach einem Tag Durchziehen, wenn Marmelade und Schokolade sich verbunden haben. Zu einem Stück gehört traditionell ein Kaffee, am liebsten eine Wiener Melange.","dauer":0,"tipp":""}],"profitipps":["Alle Zutaten sollten Zimmertemperatur haben – das verhindert, dass die Masse gerinnt.","Schokolade nicht zu heiß unterrühren, sonst schmilzt die Butter und der Kuchen wird dicht.","Marmelade vor dem Glasieren dünn auftragen und trocknen lassen; sie schützt vor einem aufgeweichten Überzug.","Glasur nicht zu oft verstreichen – sonst verliert sie ihren Glanz.","Torte nicht im Kühlschrank lagern, sondern kühl und trocken unter einer Haube."],"varianten":["Original Sacher-Torte (Hotel Sacher) mit Marmelade nur unter der Glasur","Demel-Version mit zusätzlicher Mittelschicht","Sachertorte mit Rum-Orangen-Glasur","Mini-Sacher im Glas"],"beilagen":["Ungesüßtes Schlagobers","Marillenmarmelade","Melange"],"getraenk":"Melange oder ein Glas Eiswein","koeche":[],"quellen":[{"titel":"Sachertorte – Wikipedia (en)","url":"https://en.wikipedia.org/wiki/Sachertorte"},{"titel":"Sachertorte – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Sachertorte"},{"titel":"TasteAtlas – Austrian dishes ranking","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"torte","farben":["#3b1f14","#6b3a22","#c1763a"],"schlagworte":["Wiener Kaffeehaus","Schokolade","Klassiker"],"vegetarisch_moeglich":true},{"id":"oesterreich-wiener-saftgulasch","name":"Wiener Saftgulasch","originalname":"Wiener Saftgulasch","kueche":"oesterreich","region":"Wien","beliebtheit":88,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Zartes Rindfleisch, in sehr viel Zwiebel und Paprika geschmort, bis ein dunkelroter, sämiger Saft ganz ohne Mehl entsteht – mit Semmelknödeln oder frischem Gebäck.","hintergrund":"Das Wiener Gulasch geht auf das ungarische Pörkölt zurück, das sich in der Donaumonarchie in den Wiener Gasthäusern etablierte. Typisch ist die große Menge Zwiebeln, etwa im Verhältnis eins zu eins zum Fleisch, die langsam einkochen und den Saft binden – Mehl braucht es nicht. Das Saftgulasch wird meist aus Rinderwade (Wadschinken) geschmort, die durch ihren Bindegewebsanteil im Fleisch schön gelatinös wird. Gewürzt wird mit edelsüßem Paprika, Kümmel, Majoran, Knoblauch und etwas Essig. Dazu isst man Semmelknödel, Nockerl oder einfach frisches Brot, in Wien auch als Fiakergulasch mit Spiegelei, Frankfurter und Gurkerl.","portionen":4,"zeit":{"vorbereitung":30,"garen":150,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Gulasch","liste":[{"menge":1,"einheit":"kg","name":"Rinderwade (Wadschinken) oder Rinderschulter","hinweis":"in 3 cm große Würfel; Rinderwade ist gelatinös und besonders saftig"},{"menge":1,"einheit":"kg","name":"Zwiebeln","hinweis":"fein in Halbringe oder Würfel geschnitten"},{"menge":80,"einheit":"g","name":"Schweineschmalz oder Öl","hinweis":"Schmalz gibt den klassischen Geschmack"},{"menge":3,"einheit":"EL","name":"edelsüßes Paprikapulver","hinweis":"frisch, nicht zu alt – sonst wird es bitter"},{"menge":2,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":2,"einheit":"EL","name":"Essig","hinweis":"Weinessig"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Kümmel","hinweis":"gemahlen oder zerstoßen"},{"menge":1,"einheit":"TL","name":"getrockneter Majoran","hinweis":""},{"menge":2,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":500,"einheit":"ml","name":"Rindsuppe oder Wasser","hinweis":"heiß, nach Bedarf"},{"menge":null,"einheit":"","name":"Salz, schwarzer Pfeffer, Zitronenschale","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":4,"einheit":"Stück","name":"Semmelknödel","hinweis":"oder frisches Gebäck, Salzstangerl"},{"menge":4,"einheit":"Stück","name":"Essiggurkerl","hinweis":"als Garnitur"}]}],"ausruestung":["Schwerer Schmortopf mit Deckel","Holzlöffel","Scharfes Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide die Zwiebeln in feine Halbringe oder Würfel, denn sie lösen sich beim langen Schmoren fast vollständig auf und bilden die Basis der Sauce. Tupfe die Fleischstücke mit Küchenpapier trocken, schneide sie in etwa 3 cm große Würfel und salze sie leicht. Hacke den Knoblauch, bereite Paprika, Kümmel und Majoran zum Zugreifen vor und halte heiße Rindsuppe bereit. Das Paprikapulver wird später nur kurz erhitzt, und dann muss alles schnell gehen.","dauer":20,"tipp":"Rinderwade gibt viel Gelatine ab; Schulter ist magerer und wird schneller trocken."},{"titel":"Zwiebeln langsam rösten","aktion":"anbraten","text":"Erhitze das Schmalz im Schmortopf bei mittlerer Hitze und gib die Zwiebeln mit einer Prise Salz dazu. Rühre häufig und röste sie 20–25 Minuten, bis sie weich, goldbraun und süßlich duftend sind; das Salz zieht Wasser, sodass sie nicht verbrennen. Sie sind richtig, wenn sie fast breiig zerfallen und eine honigbraune Farbe haben. Diese langsame Röstung ist das Fundament des Gulaschs: Aus den Zwiebeln entsteht später die natürliche Bindung und Süße. Zu hohe Hitze macht sie bitter und gibt dem Saft einen unangenehmen Beigeschmack.","dauer":25,"tipp":""},{"titel":"Paprika und Tomatenmark anrösten","aktion":"anbraten","text":"Ziehe den Topf kurz vom Herd und rühre Paprikapulver, Kümmel und Tomatenmark in die gerösteten Zwiebeln. Gieße sofort den Essig dazu, bevor der Paprika Farbe nimmt, und rühre 20–30 Sekunden, bis eine glänzende, dunkelrote Paste entsteht. Paprika verbrennt schon bei mäßiger Hitze und wird dann bitter, deshalb darf er nur ganz kurz in das heiße Fett. Der Essig stoppt das Anbrennen und bringt eine feine Säure, die später die Schwere des Fleisches ausgleicht.","dauer":2,"tipp":""},{"titel":"Fleisch anbraten","aktion":"anbraten","text":"Gib die Fleischwürfel in den Topf, rühre sie gut mit der Zwiebel-Paprika-Paste um und lasse sie bei mittlerer Hitze etwa 5 Minuten unter Rühren anziehen, bis sie an der Oberfläche grau und von der Paste überzogen sind. Gib Knoblauch, Majoran und Lorbeer dazu. Das Fleisch gibt nun Saft ab, der den Boden anlöst und den Geschmack vertieft. Setzt etwas am Topfboden an, löse es mit einem Schuss heißer Suppe und rühre es wieder unter; der Bratensatz ist wertvoll.","dauer":7,"tipp":""},{"titel":"Schmoren","aktion":"schmoren","text":"Gieße so viel heiße Suppe an, dass das Fleisch knapp bedeckt ist, und bringe alles zum Kochen. Schließe den Deckel einen Spalt weit und schmore das Gulasch bei kleinster Hitze 2–2½ Stunden. Rühre alle 20 Minuten um und gieße nur nach, wenn der Saft sehr dick wird. Das Fleisch ist fertig, wenn es mit einer Gabel zerfällt und der Saft dunkelrot und sämig ist. Die Zwiebeln müssen sich weitgehend aufgelöst haben.","dauer":150,"tipp":"Das Gulasch am besten am Vortag kochen – es schmeckt aufgewärmt noch besser."},{"titel":"Saft einkochen und abschmecken","aktion":"reduzieren","text":"Nimm den Deckel ab und lasse das Gulasch 10–15 Minuten bei mittlerer Hitze offen einkochen, bis der Saft die Konsistenz einer dicken, glänzenden Sauce hat und am Rand das rote Paprikafett schimmert. Schmecke mit Salz, frisch gemahlenem Pfeffer und etwas abgeriebener Zitronenschale ab; ein Schuss Essig hilft, wenn die Sauce zu süß geraten ist. Entferne die Lorbeerblätter. Das Fleisch soll jetzt so zart sein, dass es beim Rühren zerfällt, und die Sauce dunkelrot und sämig.","dauer":15,"tipp":""},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse das Gulasch zugedeckt mindestens 10 Minuten ruhen. In dieser Zeit verbinden sich Saft und Fleisch, die Aromen runden sich ab, und die Sauce wird noch etwas dicker. Rühre vor dem Anrichten noch einmal durch. Wenn du das Gulasch schon am Vortag zubereitest, kühle es rasch ab, stelle es kalt und erwärme es am nächsten Tag bei kleinster Hitze unter gelegentlichem Rühren mit einem kleinen Schuss Wasser – so schmeckt es noch kräftiger.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte das Gulasch in vorgewärmten tiefen Tellern an und serviere es mit Semmelknödeln, Butternockerln oder frischem, knusprigem Gebäck zum Auftunken des Safts. Garniere mit einem Essiggurkerl in Scheiben. Für ein Fiakergulasch legst du ein Spiegelei, ein gebratenes Frankfurter Würstchen und ein aufgefächertes Gurkerl dazu. Der Saft soll kräftig rot, glänzend und leicht gebunden sein; reicht er nicht aus, gib einen Schuss heiße Suppe hinzu. Ein Klecks Sauerrahm ist in manchen Wirtshäusern üblich, gehört aber nicht zum klassischen Rezept.","dauer":0,"tipp":""}],"profitipps":["Das Zwiebel-Fleisch-Verhältnis von etwa 1:1 ist das Geheimnis des sämigen Safts – nicht sparen.","Zwiebeln lange und langsam rösten, sonst fehlen Süße und Bindung.","Paprika erst nach dem Zwiebelrösten und nur kurz erhitzen, damit er nicht bitter wird.","Ohne Mehl arbeiten – die Zwiebeln binden den Saft von selbst.","Das Gulasch am Vortag zu kochen verbessert den Geschmack deutlich."],"varianten":["Fiakergulasch mit Spiegelei, Frankfurter und Gurkerl","Szegediner Gulasch mit Sauerkraut","Erdäpfelgulasch mit Kartoffeln und Wurst","Kalbsgulasch mit Rahm"],"beilagen":["Semmelknödel","Butternockerl","Frisches Gebäck","Essiggurkerl"],"getraenk":"Blaufränkisch, Zweigelt oder ein kräftiges Märzenbier","koeche":[],"quellen":[{"titel":"Wiener Gulasch – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Wiener_Gulasch"},{"titel":"Goulash – Wikipedia (en)","url":"https://en.wikipedia.org/wiki/Goulash"},{"titel":"TasteAtlas – Austrian dishes ranking","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"eintopf","farben":["#9c2f1c","#c4562a","#e8c39e"],"schlagworte":["Wirtshausklassiker","Schmorgericht","Wien"],"vegetarisch_moeglich":false},{"id":"oesterreich-tafelspitz","name":"Tafelspitz mit Apfelkren und Schnittlauchsauce","originalname":"Wiener Tafelspitz","kueche":"oesterreich","region":"Wien","beliebtheit":87,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Zartes, in kräftiger Rindsuppe sanft gegartes Rindfleisch – mit Apfelkren, Schnittlauchsauce, Röstkartoffeln und der klaren Suppe vorweg.","hintergrund":"Tafelspitz, ein Teil der Rinderhüfte, ist das Paradegericht der Wiener Rindfleischküche und wird mit Kaiser Franz Joseph I. in Verbindung gebracht, der es besonders geschätzt haben soll. Das Fleisch wird in einer kräftigen Brühe aus Knochen, Wurzelgemüse und gerösteter Zwiebel langsam gegart. Klassisch gibt es zuerst die klare Suppe mit Einlage, danach das Fleisch mit Apfelkren (Meerrettich mit Apfel), Schnittlauchsauce und Röstkartoffeln. Ewald Plachutta gilt als der Koch, der die traditionelle Wiener Rindfleischküche mit dem Tafelspitz wiederbelebt hat.","portionen":6,"zeit":{"vorbereitung":45,"garen":180,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Für Fleisch und Brühe","liste":[{"menge":1.5,"einheit":"kg","name":"Tafelspitz vom Rind","hinweis":"ersatzweise Hüftdeckel oder Schulterscherzel; beim Metzger vorbestellen"},{"menge":500,"einheit":"g","name":"Rinderknochen mit etwas Fleisch","hinweis":"Markknochen oder Beinscheibe"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"halbiert, mit Schale"},{"menge":300,"einheit":"g","name":"Wurzelgemüse","hinweis":"Karotten, Sellerie, Petersilienwurzel, Pastinake"},{"menge":1,"einheit":"Stange","name":"Lauch","hinweis":"halbiert und gewaschen"},{"menge":12,"einheit":"Stück","name":"Pfefferkörner","hinweis":""},{"menge":2,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":1,"einheit":"Zweig","name":"Liebstöckel","hinweis":"optional"},{"menge":3.5,"einheit":"l","name":"kaltes Wasser","hinweis":""},{"menge":null,"einheit":"","name":"Salz, grobes Salz zum Servieren, Schnittlauch","hinweis":"nach Geschmack"}]},{"gruppe":"Apfelkren","liste":[{"menge":3,"einheit":"Stück","name":"säuerliche Äpfel","hinweis":"z. B. Boskoop"},{"menge":80,"einheit":"g","name":"frischer Meerrettich","hinweis":"geschält, fein gerieben; ersatzweise 4 EL aus dem Glas"},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":1,"einheit":"Prise","name":"Zucker","hinweis":""}]},{"gruppe":"Schnittlauchsauce","liste":[{"menge":100,"einheit":"g","name":"Toastbrot ohne Rinde","hinweis":"in 200 ml Milch eingeweicht"},{"menge":2,"einheit":"Stück","name":"rohe Eigelb","hinweis":""},{"menge":2,"einheit":"Stück","name":"hartgekochte Eigelb","hinweis":""},{"menge":400,"einheit":"ml","name":"neutrales Pflanzenöl","hinweis":""},{"menge":2,"einheit":"EL","name":"Schnittlauch","hinweis":"fein geschnitten"},{"menge":1,"einheit":"TL","name":"Estragonsenf oder milder Senf","hinweis":""},{"menge":null,"einheit":"","name":"Salz, Essig, weißer Pfeffer, Prise Zucker","hinweis":"nach Geschmack"}]},{"gruppe":"Röstkartoffeln","liste":[{"menge":800,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"gekocht und ausgekühlt"},{"menge":60,"einheit":"g","name":"Butterschmalz","hinweis":""}]}],"ausruestung":["Großer Topf (mind. 5 l)","Schaumkelle","Feines Sieb und Passiertuch","Pfanne","Reibe","Mixer oder Passiersieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Nimm das Fleisch eine halbe Stunde vor dem Kochen aus dem Kühlschrank und spüle es kurz lauwarm ab, damit Knochensplitter und Oberflächenreste verschwinden. Schäle das Wurzelgemüse, wasche den Lauch gründlich und halbiere die Zwiebeln samt Schale. Bereite Pfefferkörner, Lorbeer und Liebstöckel vor und stelle den größten Topf bereit. Koche die Kartoffeln für die Röstkartoffeln schon jetzt, damit sie vor dem Anbraten vollständig auskühlen können.","dauer":15,"tipp":""},{"titel":"Zwiebeln rösten","aktion":"anbraten","text":"Lege die Zwiebelhälften mit der Schnittseite nach unten in eine trockene Pfanne ohne Fett und röste sie bei mittlerer Hitze 8–10 Minuten, bis die Schnittflächen fast schwarz sind. Das gibt der Brühe ihre goldbraune Farbe und ein leicht rauchig-süßliches Aroma. Wende die Zwiebeln nicht zu früh, damit die Schnittfläche gleichmäßig durchröstet. Sie dürfen kohlschwarz werden, aber nicht ganz verbrennen, sonst wird die Brühe bitter. Die Schale bleibt dran und färbt zusätzlich.","dauer":10,"tipp":""},{"titel":"Knochen blanchieren","aktion":"blanchieren","text":"Gib die Knochen in einen Topf mit kaltem Wasser, bringe es zum Kochen und lasse sie 5 Minuten sprudelnd aufwallen. Dabei steigt grauer Schaum auf, der aus Blut und gelösten Eiweißen besteht und die Brühe trüben würde. Gieße alles in ein Sieb, spüle die Knochen kalt ab und wasche den Topf aus, bevor du die eigentliche Brühe ansetzt. Dieser Schritt ist die Grundlage für eine klare, goldene Suppe, wie man sie in Wiener Gasthäusern erwartet.","dauer":10,"tipp":""},{"titel":"Brühe ansetzen und Fleisch einlegen","aktion":"kochen","text":"Bringe 3,5 l Wasser mit den blanchierten Knochen, den gerösteten Zwiebeln, Pfefferkörnern, Lorbeer und Liebstöckel zum Kochen. Lege das Fleisch hinein; es muss vollständig bedeckt sein, gieße bei Bedarf heißes Wasser nach. Reduziere die Hitze sofort auf ein ganz leichtes Köcheln, bei dem sich die Oberfläche kaum bewegt, und schöpfe den grauen Schaum in den ersten 15 Minuten regelmäßig mit der Schaumkelle ab. Salze zu Beginn nur leicht – gesalzen wird zum Schluss nach Geschmack.","dauer":10,"tipp":""},{"titel":"Sanft garen","aktion":"koecheln","text":"Lasse das Fleisch bei kleinster Hitze 2–2½ Stunden ziehen. Die Brühe darf nie sprudelnd kochen, denn sonst wird das Fleisch trocken und faserig und die Brühe trüb. Gib das Wurzelgemüse und den Lauch erst für die letzten 45 Minuten dazu, damit die Suppe nicht süßlich wird. Das Fleisch ist gar, wenn ein Spieß oder eine Gabel ohne Widerstand hineingleitet und beim Herausziehen nicht hängen bleibt. Es sollte zart, aber noch in Form sein; zu langes Kochen lässt es zerfallen und auslaugen.","dauer":150,"tipp":"Das Fleisch nicht aus der Brühe nehmen, bevor es richtig zart ist."},{"titel":"Apfelkren zubereiten","aktion":"mischen","text":"Schäle die Äpfel, entferne das Kerngehäuse und reibe sie fein. Vermische sie sofort mit Zitronensaft, damit sie nicht braun werden. Rühre den geriebenen Meerrettich, eine Prise Zucker und Salz unter. Der Kren soll fruchtig, scharf und frisch schmecken und beim Riechen in der Nase kribbeln. Stelle ihn kalt; er verliert nach einigen Stunden an Schärfe.","dauer":10,"tipp":""},{"titel":"Schnittlauchsauce rühren","aktion":"mischen","text":"Drücke das eingeweichte Brot gut aus und streiche es zusammen mit den gekochten Eigelben durch ein Sieb. Rühre die rohen Eigelbe, Senf, Salz, Essig, Pfeffer und etwas Zucker dazu. Gib das Öl in einem dünnen Strahl unter ständigem Rühren dazu, bis die Sauce cremig und fest ist. Hebe zum Schluss den Schnittlauch unter. Die Sauce soll mild und cremig schmecken und eine blassgelbe Farbe haben.","dauer":15,"tipp":""},{"titel":"Röstkartoffeln braten","aktion":"braten","text":"Schäle die ausgekühlten Pellkartoffeln und schneide sie in etwa 5 mm dicke Scheiben. Erhitze das Butterschmalz in einer großen Pfanne bei mittlerer Hitze und gib die Kartoffeln in einer Schicht hinein. Brate sie 8–10 Minuten und wende sie nur gelegentlich, bis sie goldbraun, knusprig und aromatisch nach Butter duften. Würze erst am Ende mit Salz, damit sie nicht wässern. Halte sie im 80 °C warmen Ofen warm, bis das Fleisch angerichtet wird.","dauer":10,"tipp":""},{"titel":"Fleisch schneiden und Brühe abseihen","aktion":"schneiden","text":"Hebe das Fleisch aus der Brühe und lasse es 5 Minuten ruhen, damit sich der Saft verteilt. Seihe die Brühe durch ein feines Sieb oder ein Tuch und schmecke sie mit Salz ab; sie soll klar, goldgelb und kräftig nach Rind und Wurzelgemüse schmecken. Schneide das Fleisch quer zur Faser in 1–2 cm dicke Scheiben, denn so bleibt es zart. Lege die Scheiben fächerförmig auf eine vorgewärmte Platte und beträufle sie mit etwas heißer Brühe, damit sie nicht austrocknen.","dauer":10,"tipp":""},{"titel":"Anrichten und servieren","aktion":"anrichten","text":"Serviere zuerst die klare Rindsuppe in Tassen oder Tellern mit etwas Gemüse und geschnittenem Schnittlauch, wie es nach Wiener Brauch üblich ist. Richte danach das Fleisch mit grobem Salz und Schnittlauch an und reiche Apfelkren, Schnittlauchsauce und Röstkartoffeln dazu. Das gekochte Gemüse aus der Brühe kannst du als Beilage dazulegen. Das Fleisch soll saftig, rosig-grau und butterzart sein, der Kren scharf und frisch. Reste kannst du am nächsten Tag in der Brühe als Rindfleischsalat oder Rindfleischsulz verwerten.","dauer":0,"tipp":""}],"profitipps":["Das Fleisch in kochende Brühe legen und nur leise köcheln lassen – kein starkes Sprudeln.","Gemüse erst spät zugeben, sonst wird die Brühe zu süß.","Fleisch quer zur Faser schneiden, damit es zart bleibt.","Am Vortag kochen: Das Fett lässt sich leichter abschöpfen und das Fleisch lässt sich besser schneiden.","Brühe zweimal passieren (Sieb und Tuch) für klare Optik."],"varianten":["Tafelspitz mit Cremespinat und Röstkartoffeln","Dillsauce statt Schnittlauchsauce","Kaltes Tafelspitz-Sulzerl","Gekochtes Rindfleisch mit Semmelkren"],"beilagen":["Apfelkren","Schnittlauchsauce","Röstkartoffeln","Cremespinat","Bouillongemüse"],"getraenk":"Grüner Veltliner Smaragd oder Zweigelt","koeche":[{"name":"Ewald Plachutta","bezug":"Gilt laut deutscher Wikipedia als der Koch, der eine Renaissance der traditionellen Wiener Rindfleischküche mit dem Tafelspitz auslöste; seine Wiener Gasthäuser sind auf gekochtes Rindfleisch spezialisiert.","quelle":"https://de.wikipedia.org/wiki/Ewald_Plachutta"},{"name":"Ewald Plachutta","bezug":"Die klassische Schnittlauchsauce („nach Plachutta“) wird auf einem Rezeptportal mit Brot, Milch, rohem und gekochtem Eigelb, Öl und Schnittlauch beschrieben.","quelle":"https://www.salzkammergut.at/erleben/essen-trinken/rezepte/artikel/detail/3763/alt-wiener-tafelspitz.html"}],"quellen":[{"titel":"Tafelspitz Schritt für Schritt – Vienna Sunday Kitchen","url":"https://www.vienna-sunday.kitchen/tafelspitz-schritt-fuer-schritt"},{"titel":"Alt-Wiener Tafelspitz – salzkammergut.at","url":"https://www.salzkammergut.at/erleben/essen-trinken/rezepte/artikel/detail/3763/alt-wiener-tafelspitz.html"},{"titel":"Austrian classic Tafelspitz – Falstaff","url":"https://www.falstaff.com/rd/r/austrian-classic-tafelspitz-boiled-beef/"},{"titel":"Ewald Plachutta – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Ewald_Plachutta"},{"titel":"Tafelspitz – Wikipedia (en)","url":"https://en.wikipedia.org/wiki/Tafelspitz"}],"bild":"braten-scheiben","farben":["#a8703c","#d9b48a","#6b8f3a"],"schlagworte":["Kaiserliche Küche","Wiener Rindfleisch","Festessen"],"vegetarisch_moeglich":false},{"id":"oesterreich-palatschinken-marillenmarmelade","name":"Palatschinken mit Marillenmarmelade","kueche":"oesterreich","region":"Wien und Ostösterreich","beliebtheit":86,"kurz":"Hauchdünne, zarte Pfannkuchen, mit Marillenmarmelade bestrichen, eingerollt und mit Staubzucker bestäubt – Wiener Klassiker für Groß und Klein.","hintergrund":"Palatschinken stammen aus der Donaumonarchie und kamen über die tschechische Küche nach Österreich; das Wort geht auf das lateinische „placenta“ zurück. Anders als deutsche Pfannkuchen sind sie hauchdünn, ähnlich französischen Crêpes, und werden meist mit Marillenmarmelade (Aprikosenkonfitüre) gefüllt, eingerollt und mit Staubzucker bestreut. Ostösterreich liebt sie gefüllt mit Topfen und Rosinen, mit Schokolade oder mit Obers und Früchten. Man isst mehrere pro Portion, und auch als Hauptspeise an einem „Mehlspeistag“ sind sie beliebt.","portionen":4,"zeit":{"vorbereitung":15,"garen":30,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Teig (ca. 10–12 Palatschinken)","liste":[{"menge":200,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"oder glattes Mehl (Österreich)"},{"menge":350,"einheit":"ml","name":"Milch","hinweis":"zimmerwarm"},{"menge":100,"einheit":"ml","name":"Mineralwasser mit Kohlensäure","hinweis":"macht den Teig besonders zart"},{"menge":3,"einheit":"Stück","name":"Eier (Größe M)","hinweis":"zimmerwarm"},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Butter","hinweis":"zerlassen, für den Teig"}]},{"gruppe":"Zum Backen und Füllen","liste":[{"menge":30,"einheit":"g","name":"Butter oder Butterschmalz","hinweis":"zum Ausbacken"},{"menge":250,"einheit":"g","name":"Marillenmarmelade","hinweis":"glatt gerührt, ersatzweise Aprikosenkonfitüre"},{"menge":2,"einheit":"EL","name":"Staubzucker","hinweis":"Puderzucker zum Bestäuben"}]}],"ausruestung":["Beschichtete Pfanne (22–24 cm)","Schneebesen","Schöpfkelle","Backblech und Alufolie zum Warmhalten"],"schritte":[{"titel":"Zutaten abwiegen","aktion":"vorbereiten","text":"Wiege das Mehl ab und stelle Milch, Eier und Mineralwasser rechtzeitig aus dem Kühlschrank, damit alles ähnlich temperiert ist. Zerlasse einen Esslöffel Butter in der Pfanne oder Mikrowelle und lass sie etwas abkühlen. Rühre die Marillenmarmelade in einem Schälchen glatt, damit sie sich später dünn und gleichmäßig aufstreichen lässt. Heize den Backofen auf 80 °C Ober-/Unterhitze (70 °C Umluft) vor, damit du die fertigen Palatschinken warm halten kannst.","dauer":10,"tipp":""},{"titel":"Teig anrühren","aktion":"mischen","text":"Verrühre Mehl, Zucker und Salz in einer Schüssel. Gib die Milch und die Eier dazu und schlage mit dem Schneebesen von der Mitte aus alles zu einem glatten Teig, ohne Klümpchen. Rühre zum Schluss das Mineralwasser und die zerlassene Butter ein. Der Teig soll flüssig wie Sahne sein und dünn vom Löffel laufen; ist er zu dick, geben die Palatschinken dicke, gummiartige Fladen, deshalb im Zweifel einen Schluck Milch nachgießen.","dauer":5,"tipp":""},{"titel":"Teig quellen lassen","aktion":"ruhen","text":"Lass den Teig mindestens 30 Minuten abgedeckt bei Raumtemperatur ruhen. In dieser Zeit quillt das Mehl, das Gluten entspannt sich, und die Palatschinken werden zart und reißen beim Wenden nicht. Rühre den Teig vor dem Backen noch einmal durch, weil sich das Mehl gern am Boden absetzt. Du erkennst den richtigen Zustand daran, dass er glatt glänzt und beim Eingießen sofort in der Pfanne verläuft.","dauer":30,"tipp":""},{"titel":"Pfanne vorbereiten und erste Palatschinke backen","aktion":"braten","text":"Erhitze die Pfanne bei mittlerer bis mittelstarker Hitze und gib ein kleines Stück Butter hinein, bis sie leicht schäumt, aber nicht bräunt. Gieße eine kleine Kelle Teig (etwa 70–80 ml) in die Mitte, hebe die Pfanne an und schwenke sie kreisförmig, damit der Teig hauchdünn den Boden bedeckt. Nach etwa einer Minute ist die Unterseite goldgelb und die Oberfläche matt. Die erste Palatschinke gerät meist noch nicht ideal; sie dient dazu, die Hitze einzustellen.","dauer":3,"tipp":"Wird sie sofort braun und fest, ist die Pfanne zu heiß; zerläuft der Teig langsam, ist sie zu kalt."},{"titel":"Wenden und stapeln","aktion":"braten","text":"Löse den Rand mit einem flachen Pfannenwender und wende die Palatschinke mit einem schnellen Schwung oder mit dem Wender. Die zweite Seite braucht nur etwa 20 bis 30 Sekunden, bis sie hellgoldene Flecken zeigt. Lege die fertigen Palatschinken übereinander auf einen Teller und halte ihn im 80 °C warmen Ofen warm. Gib vor jeder weiteren Palatschinke nur noch einen Hauch Butter in die Pfanne, sonst werden sie fettig.","dauer":15,"tipp":""},{"titel":"Füllen und aufrollen","aktion":"fuellen","text":"Lege eine Palatschinke auf ein Brett und bestreiche die gesamte Fläche dünn mit der glatt gerührten Marillenmarmelade. Klappe den unteren Rand etwa zwei Zentimeter ein und rolle die Palatschinke fest auf, oder falte sie zu einem Dreieck, wie es in Wien üblich ist. Arbeite zügig, solange die Palatschinken noch warm sind, denn dann haftet die Marmelade besser und die Rolle bleibt zusammen.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Schneide die Rollen eventuell schräg in Hälften oder lass sie ganz. Richte je drei Stück pro Teller an und siebe großzügig Staubzucker darüber, sodass sie wie leicht verschneit aussehen. Serviere sie sofort warm; Palatschinken schmecken am besten, wenn sie noch weich und die Marmelade leicht angewärmt ist. Zur Not kannst du sie kurz bei 120 °C Ober-/Unterhitze (100 °C Umluft) im Ofen aufwärmen.","dauer":2,"tipp":""}],"profitipps":["Mineralwasser lockert den Teig: Die Kohlensäure macht die Palatschinken besonders zart.","Teig immer ruhen lassen – ohne Ruhezeit werden sie zäh und reißen.","Backe in einer kleinen, gut beschichteten Pfanne mit sehr wenig Fett, dann gelingt das Wenden leichter.","Die Marmelade vor dem Aufstreichen glatt rühren oder kurz erwärmen, sie lässt sich dann viel gleichmäßiger verteilen.","Fertige Palatschinken lassen sich mit Backpapier dazwischen einfrieren."],"varianten":["Topfenpalatschinken mit Topfen, Rosinen und Vanillezucker, im Ofen überbacken","Mit Nutella und Banane","Gebackene Palatschinken als Frittatensuppe-Einlage (ungezuckert, in Streifen geschnitten)","Mit Schlagobers und Beeren"],"beilagen":["Staubzucker","Vanilleeis","frische Beeren"],"getraenk":"Kaffee mit Obers oder ein Glas kalte Milch","koeche":[{"name":"Katharina Prato","bezug":"Die Autorin wird auf Wikipedia unter den historischen Kochbuchautoren genannt, die Palatschinken in ihren Werken beschreiben.","quelle":"https://de.wikipedia.org/wiki/Palatschinke"}],"quellen":[{"titel":"Palatschinke – Wikipedia","url":"https://de.wikipedia.org/wiki/Palatschinke"}],"bild":"pfannkuchen","farben":["#e8b86a","#c4572a","#f7ecd8"],"schlagworte":["Mehlspeise","Wien","Pfannkuchen","Klassiker"],"originalname":"","fleischsorte":"","hauptkategorie":"suess","gang":"dessert","vegetarisch_moeglich":true},{"id":"oesterreich-marillenknoedel","name":"Marillenknödel aus Topfenteig","originalname":"Wachauer Marillenknödel","kueche":"oesterreich","region":"Wachau (Niederösterreich)","beliebtheit":84,"hauptkategorie":"suess","gang":"dessert","kurz":"Zarte Topfenteig-Knödel mit einer ganzen, saftigen Marille und einem Würfelzucker im Kern, in butterglänzenden Bröseln gewälzt.","hintergrund":"Marillenknödel sind eine klassische Mehlspeise der böhmisch-österreichischen Küche und vor allem in den Marillenregionen wie der Wachau und im Vinschgau zu Hause. Im Sommer, wenn die Wachauer Marillen reif sind, stehen sie auf den Speisekarten der Heurigen und Gasthäuser. Der Teig kann aus Topfen (Quark), Kartoffeln oder Brandteig bestehen; hier folgt er der beliebten Topfenvariante. Gekocht werden die Knödel in sanft siedendem Wasser und anschließend in gerösteten Bröseln gewälzt, mit Staubzucker bestreut und oft mit Zimtzucker serviert.","portionen":4,"zeit":{"vorbereitung":40,"garen":20,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig","liste":[{"menge":250,"einheit":"g","name":"Topfen (Quark, 20 % Fett)","hinweis":"gut abgetropft oder trocken gepresst; ein trockener Quark ist entscheidend"},{"menge":40,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ei (Größe M)","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":150,"einheit":"g","name":"griffiges Mehl (Type 550)","hinweis":"oder glattes Mehl, plus Mehl zum Arbeiten"},{"menge":30,"einheit":"g","name":"Hartweizengrieß","hinweis":"macht den Teig stabil"},{"menge":1,"einheit":"TL","name":"abgeriebene Zitronenschale","hinweis":"von unbehandelten Zitronen"}]},{"gruppe":"Für die Füllung","liste":[{"menge":8,"einheit":"Stück","name":"reife, aber feste Marillen (Aprikosen)","hinweis":"etwa 40–50 g pro Frucht"},{"menge":8,"einheit":"Stück","name":"Würfelzucker","hinweis":""}]},{"gruppe":"Zum Kochen und Wälzen","liste":[{"menge":null,"einheit":"","name":"Salz fürs Kochwasser","hinweis":""},{"menge":80,"einheit":"g","name":"Butter","hinweis":""},{"menge":100,"einheit":"g","name":"Semmelbrösel","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Zimt","hinweis":""},{"menge":null,"einheit":"","name":"Puderzucker zum Bestäuben","hinweis":""}]}],"ausruestung":["Großer, weiter Topf","Schaumkelle","Pfanne","Frischhaltefolie oder feuchtes Tuch","Kleines Messer oder Kochlöffelstiel zum Entkernen"],"schritte":[{"titel":"Mise en place und Topfen vorbereiten","aktion":"vorbereiten","text":"Lege den Topfen in ein sauberes Küchentuch oder feines Sieb und presse ihn aus, bis er fast krümelig trocken ist, sonst wird der Teig zu weich und die Knödel zerfallen im Wasser. Wiege alle Zutaten ab und lasse Butter und Ei Zimmertemperatur annehmen. Wasche die Marillen und tupfe sie trocken. Stelle einen großen Topf mit reichlich Wasser bereit, denn die Knödel brauchen Platz. Reibe die Zitronenschale ab.","dauer":10,"tipp":"Zu feuchter Topfen ist der häufigste Grund für zerfallende Knödel."},{"titel":"Teig kneten","aktion":"kneten","text":"Verrühre die weiche Butter mit Salz und Zitronenschale cremig, gib das Ei und den ausgepressten Topfen dazu und rühre alles glatt. Mische Mehl und Grieß dazu und verknete alles mit den Händen schnell zu einem weichen, leicht klebrigen Teig. Knete nur so lange, bis keine Mehlnester mehr sichtbar sind, denn zu langes Kneten macht den Teig zäh. Der Teig soll weich, aber formbar sein; klebt er zu stark, gib esslöffelweise Mehl dazu.","dauer":5,"tipp":""},{"titel":"Teig rasten lassen","aktion":"ruhen","text":"Wickle den Teig in Frischhaltefolie oder decke die Schüssel ab und lasse ihn mindestens 30 Minuten im Kühlschrank rasten. In dieser Zeit quellen Mehl und Grieß und binden die Feuchtigkeit des Topfens, sodass der Teig fester und besser formbar wird. Kalter Teig lässt sich außerdem leichter um die Frucht legen und klebt weniger an den Händen. Du merkst den Unterschied, wenn er sich nach der Rast glatt anfühlt.","dauer":30,"tipp":""},{"titel":"Marillen entkernen und füllen","aktion":"fuellen","text":"Drücke den Kern jeder Marille vorsichtig mit dem Finger oder einem Kochlöffelstiel von der Seite aus der Frucht, ohne sie ganz aufzureißen, oder schneide sie an der Naht auf und entferne den Kern. Stecke in jede Frucht einen Würfelzucker; er löst sich beim Kochen auf und bildet im Inneren einen Sirup, der die Säure ausgleicht. Drücke die Frucht wieder zusammen. Ist die Marille sehr groß oder sehr reif, kannst du auch nur einen halben Würfel verwenden.","dauer":10,"tipp":"Reife Marillen sind weich und süß, unreife bleiben hart und sauer – eine Frage der Saison."},{"titel":"Knödel formen","aktion":"formen","text":"Rolle den Teig auf einer bemehlten Fläche zu einer Rolle und teile sie in 8 gleich große Stücke. Drücke jedes Stück mit bemehlten Händen zu einer Platte, lege eine gefüllte Marille in die Mitte und schließe den Teig vollständig um die Frucht. Rolle den Knödel zwischen den Handflächen zu einer glatten Kugel, die Naht muss ganz dicht sein. Der Teigmantel sollte rundum gleich dick, etwa 3–4 mm, sein; dünne Stellen reißen beim Kochen.","dauer":10,"tipp":""},{"titel":"Knödel kochen","aktion":"koecheln","text":"Bringe reichlich Salzwasser zum Kochen und reduziere die Hitze, sodass es nur noch leise siedet. Lasse die Knödel vorsichtig hineingleiten und rühre einmal behutsam um, damit sie nicht am Boden festkleben. Lasse sie 12–15 Minuten bei geschlossenem Deckel, aber leicht geöffnetem Spalt, sanft ziehen; sie steigen nach etwa 5 Minuten nach oben. Sie sind fertig, wenn sie glänzen, fest sind und ein Holzstäbchen ohne Teigreste herauskommt. Zu starkes Kochen lässt sie aufreißen.","dauer":15,"tipp":""},{"titel":"Butterbrösel rösten","aktion":"braten","text":"Zerlasse die Butter in einer Pfanne, gib die Semmelbrösel dazu und röste sie bei mittlerer Hitze unter ständigem Rühren etwa 4 Minuten, bis sie goldbraun, locker und nussig-buttrig duften. Mische Zucker und Zimt unter und nimm die Pfanne vom Herd. Die Brösel müssen trocken und knusprig sein, nicht fettig. Wenn sie zu dunkel werden, schmecken sie bitter, also lieber früher vom Herd nehmen.","dauer":5,"tipp":""},{"titel":"Wälzen und servieren","aktion":"anrichten","text":"Hebe die Knödel mit einer Schaumkelle aus dem Wasser, lasse sie kurz abtropfen und wälze sie sofort in den warmen Bröseln, bis sie rundum bedeckt sind. Richte sie auf vorgewärmten Tellern an und bestäube sie mit Puderzucker. Serviere sie unverzüglich, damit der Teig weich bleibt und die Marille im Inneren heiß und saftig ist. Beim Aufschneiden duftet es intensiv nach warmem Aprikosenkompott. Reste kann man am nächsten Tag in Butter anbraten.","dauer":0,"tipp":""}],"profitipps":["Topfen gut abtropfen lassen – feuchter Quark macht den Teig klebrig und die Knödel instabil.","Nur mit gut reifen Marillen arbeiten, am besten aus der Wachau in der Saison (Juli).","Wasser nur sanft sieden, nie sprudelnd kochen.","Butterbrösel erst kurz vor dem Servieren rösten, damit sie knusprig bleiben.","Nach dem Kochen sofort wälzen, solange die Oberfläche noch feucht ist."],"varianten":["Marillenknödel aus Kartoffelteig","Marillenknödel aus Brandteig","Zwetschkenknödel","Mit Mohn oder zerstoßenem Lebkuchen statt Bröseln"],"beilagen":["Zimtzucker","Vanillesauce","Marillenröster"],"getraenk":"Wachauer Marillenbrand oder ein Gläschen Prädikatswein (Riesling Spätlese)","koeche":[],"quellen":[{"titel":"Marillenknödel – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Marillenkn%C3%B6del"},{"titel":"TasteAtlas – Austrian dishes ranking","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"knoedel","farben":["#e4a43b","#f1c97a","#8a5a2a"],"schlagworte":["Wachau","Mehlspeise","Sommer"],"vegetarisch_moeglich":true},{"id":"oesterreich-kaiserbroetchen-kaisersemmeln","name":"Kaiserbrötchen (Kaisersemmeln)","kueche":"oesterreich","region":"Wien / Süddeutschland","beliebtheit":84,"hauptkategorie":"vegetarisch","kurz":"Die knusprige Semmel mit dem fünfarmigen Stern oben drauf: außen kracht die Kruste, innen ist die Krume zart und watteweich. Mit etwas Übung formst du den Kaiserschnitt von Hand – ganz ohne Stempel.","hintergrund":"Die Kaisersemmel stammt aus Österreich und ist dort bis heute das Standardgebäck zum Frühstück, zur Jause und für die Semmelknödel am Mittag. Wer ihr den Namen gab, ist nicht geklärt: Genannt werden Kaiser Friedrich III., ein Wiener Bäcker namens Kayser, Joseph II. oder schlicht der Kaisertitel als Steigerung für „besonders fein“. Belegt ist sie am Hof Maria Theresias, und 1867 machte sie die Pariser Weltausstellung international bekannt. Das Besondere ist der Stern aus fünf eingeschlagenen Falten (den „Laugen“): Sie vergrößern die Kruste und sorgen für das typische Knacken beim Aufbrechen. In Bayern und Süddeutschland heißt sie ebenfalls Kaiser- oder Semmelbrötchen und gehört zur Brotzeit.","portionen":8,"zeit":{"vorbereitung":45,"garen":22,"ruhen":150},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig (8 Semmeln à ca. 75 g)","liste":[{"menge":500,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"in Österreich: Wiener Griffig oder Mehl Type W 700 / Type 550"},{"menge":285,"einheit":"g","name":"Wasser","hinweis":"ca. 18–20 °C, damit der Teig nach dem Kneten bei etwa 24 °C landet"},{"menge":10,"einheit":"g","name":"frische Hefe","hinweis":"entspricht 3 g Trockenhefe"},{"menge":10,"einheit":"g","name":"Salz","hinweis":""},{"menge":20,"einheit":"g","name":"weiche Butter","hinweis":"für eine feine, zarte Krume"},{"menge":1,"einheit":"TL","name":"Gerstenmalzextrakt oder Zucker","hinweis":"Backmalz gibt Bräunung und Aroma; Zucker geht auch"}]},{"gruppe":"Zum Formen und Backen","liste":[{"menge":2,"einheit":"EL","name":"helles Roggenmehl","hinweis":"zum Bestäuben; es hilft, dass die Falten schön aufreißen"},{"menge":null,"einheit":"","name":"Wasser zum Bestreichen","hinweis":""},{"menge":2,"einheit":"EL","name":"Mohn oder Sesam","hinweis":"optional zum Bestreuen"}]}],"ausruestung":["Küchenmaschine oder große Schüssel für Handknetung","Backblech oder Pizzastein","Leinentuch (Couche) oder bemehltes Geschirrtuch","Sprühflasche und eine feuerfeste Schale für Dampf","Küchenwaage mit Gramm-Anzeige","Abkühlgitter"],"schritte":[{"titel":"Mise en place und Teigtemperatur","aktion":"vorbereiten","text":"Wiege alle Zutaten genau ab, denn Brötchenteig verzeiht Ungenauigkeiten bei Wasser und Salz kaum. Die Butter sollte weich, aber nicht flüssig sein, das Wasser etwa 18–20 °C haben (lauwarm wäre bei dem kurzen Kneten zu warm). Dein Ziel ist eine Teigtemperatur von 24–25 °C: Ist deine Küche kühl, nimm das Wasser etwas wärmer, im Hochsommer eiskalt. Rühre die Hefe im Wasser an und lass das Mehl bereits in der Knetschüssel liegen. Heize den Ofen noch nicht vor, dafür ist später genug Zeit.","dauer":15,"tipp":"Miss die Teigtemperatur direkt nach dem Kneten mit einem Einstichthermometer – so lernst du schnell, wie dein Wasser zu temperieren ist."},{"titel":"Kneten bis zur Fensterprobe","aktion":"kneten","text":"Gib Mehl, Hefewasser und Malz in die Maschine und knete 4 Minuten auf kleiner Stufe, bis kein trockenes Mehl mehr zu sehen ist. Dann Salz und Butter zugeben und weitere 6–8 Minuten auf mittlerer Stufe kneten. Der Teig ist fest und soll sich als glatte Kugel vom Schüsselrand lösen. Mach die Fensterprobe: Reiße ein walnussgroßes Stück ab und ziehe es mit den Fingern vorsichtig auseinander – es muss sich zu einer dünnen, fast durchsichtigen Haut dehnen lassen, ohne sofort zu reißen. Reißt es, knete 2 Minuten weiter. Von Hand dauert das gut 15 Minuten auf der Arbeitsfläche.","dauer":12,"tipp":"Der Teig soll straffer sein als Brotteig: Kaiserschnitt und Form halten nur, wenn er sich nicht klebrig verläuft."},{"titel":"Stockgare mit Dehnen und Falten","aktion":"gehen","text":"Forme den Teig zu einer Kugel, lege ihn in eine leicht geölte Schüssel und decke ihn ab. Lass ihn bei 22–24 °C etwa 60 Minuten gehen. Nach 20 und nach 40 Minuten nimmst du den Teig kurz heraus, ziehst ihn an den vier Seiten lang und schlägst ihn wie einen Brief zusammen – das stärkt das Klebergerüst und entlüftet ihn sanft. Am Ende ist das Volumen um rund die Hälfte gewachsen, der Teig fühlt sich luftig-elastisch an und hat eine glatte, leicht matte Oberfläche. Er muss nicht verdoppelt sein.","dauer":60,"tipp":"Fingerprobe: Drückst du einen bemehlten Finger 1 cm tief hinein, soll die Delle langsam zurückfedern."},{"titel":"Teilen und rundwirken","aktion":"formen","text":"Stürze den Teig auf die unbemehlte Arbeitsfläche und teile ihn mit der Teigkarte in 8 Stücke zu je etwa 75 g – wiege jedes Stück, damit alle gleichzeitig fertig sind. Forme jedes Stück zu einer straffen Kugel: Ziehe die Oberfläche rundum nach unten und drehe die Kugel mit der hohlen Hand auf der Fläche, bis die Oberseite glatt gespannt ist und der Schluss unten sitzt. Lege die Kugeln auf ein leicht bemehltes Tuch, decke sie ab und lass sie 15 Minuten entspannen. Ohne diese Pause würden die Teiglinge beim Ausformen zurückspringen.","dauer":20,"tipp":""},{"titel":"Den Kaiserschnitt von Hand schlagen","aktion":"formen","text":"Drücke eine Kugel mit dem Handballen zu einem runden Fladen von etwa 9 cm Durchmesser und bestäube ihn hauchdünn mit Roggenmehl. Greife dann den Rand an einer Stelle, ziehe eine kleine Ecke nach innen zur Mitte und drücke sie mit dem Daumenballen fest an. Wiederhole das im Kreis herum fünfmal, bis ein Fünfeck mit fünf Falten entsteht; die letzte Falte schiebst du unter die erste. Drücke zum Schluss die Mitte mit dem Daumen noch einmal kräftig ein, damit die Falten verkleben. Mit etwas Mehl auf den Fingern geht es leichter, doch zu viel Mehl verhindert das Verkleben.","dauer":15,"tipp":"Die ersten drei Semmeln werden selten schön – das ist normal. Der Stern entsteht über das Gefühl für den richtigen Druck."},{"titel":"Stückgare mit Fingerprobe","aktion":"gehen","text":"Lege die geformten Semmeln mit der Sternseite nach unten auf ein bemehltes Leinentuch oder auf ein Blech mit Backpapier, decke sie locker ab und lass sie 30–40 Minuten bei Zimmertemperatur gehen. Die Gare ist erreicht, wenn die Teiglinge sichtbar größer und weich sind und eine Fingerkuppe nur eine flache Delle hinterlässt, die sich langsam zur Hälfte zurückbildet. Springt die Delle sofort zurück, braucht der Teig noch Zeit; bleibt sie ganz stehen, ist er überreif. Während der Gare heizt du den Ofen mit Blech oder Backstein auf der mittleren Schiene auf 250 °C Ober-/Unterhitze (Umluft nicht empfohlen, sie trocknet die Oberfläche aus).","dauer":35,"tipp":"Nimm unbedingt ein Backblech oder einen Stein auf die Mitte: Die Speicherhitze gibt den Semmeln den Anschub nach oben."},{"titel":"Wenden, befeuchten, bestreuen","aktion":"vorbereiten","text":"Drehe die Semmeln kurz vor dem Backen vorsichtig um, sodass der Stern oben liegt. Bestreiche die Oberfläche hauchdünn mit Wasser oder sprühe sie ein; so haften Mohn oder Sesam, und die Kruste wird glänzend und knackig. Streue die Körner nur auf, wenn du magst – die klassische Kaisersemmel ist oft naturbelassen. Setze die Teiglinge mit etwas Abstand auf Backpapier, am besten auf das heiße Blech oder auf den Backstein, ziehe sie mit dem Papier hinein. Bereite eine feuerfeste Schale mit 100 ml heißem Wasser vor, die du in den Ofen stellen kannst.","dauer":5,"tipp":""},{"titel":"Backen mit Schwaden","aktion":"backen","text":"Schiebe die Semmeln in den 250 °C heißen Ofen und gieße sofort das heiße Wasser auf ein heißes Blech am Ofenboden (oder besprühe die Ofenwände kräftig) – es entsteht Dampf. Schließe die Tür zügig und schalte nach 3 Minuten auf 220 °C Ober-/Unterhitze zurück. Nach 10 Minuten öffnest du kurz die Tür und lässt den Dampf ab, damit die Kruste trocknet und knusprig wird. Insgesamt backst du 20–22 Minuten, bis die Semmeln goldbraun sind, die Sternfalten hell aufgeplatzt sind und die Unterseite beim Klopfen hohl klingt. Dein Ofen duftet dann nach frischem Weißbrot und leicht nach Malz.","dauer":22,"tipp":"Zu wenig Dampf ergibt eine dicke, matte Kruste; zu viel Dampf bis zum Schluss macht sie lederig. Dampf nur am Anfang."},{"titel":"Auskühlen und Servieren","aktion":"ruhen","text":"Hole die Semmeln aus dem Ofen und lege sie auf ein Gitter, nicht in eine Tüte. Du hörst jetzt leises Knistern, wenn die Kruste beim Abkühlen feine Risse bekommt – ein gutes Zeichen. Lass sie mindestens 15 Minuten ruhen, denn die Krume gart nach und ist heiß noch klebrig. Am besten isst du sie am selben Tag, aufgeschnitten und mit Butter, Marmelade oder Aufschnitt; am nächsten Tag lassen sie sich für 5 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft) wieder aufbacken. Zum Einfrieren packst du die ausgekühlten Semmeln luftdicht ein.","dauer":15,"tipp":""}],"profitipps":["Die Teigtemperatur von 24–25 °C bestimmt, wie lange die Gare dauert – ein kalter Teig braucht deutlich länger, ein warmer überfährt dich.","Roggenmehl beim Falten des Sterns hilft, dass die Laugen im Ofen schön aufreißen, statt wieder zusammenzukleben.","Wer die Semmeln über Nacht im Kühlschrank reifen lässt (nach dem Formen, abgedeckt, 8–12 Stunden), bekommt mehr Aroma und eine knusprigere Kruste; vor dem Backen 30 Minuten temperieren.","Ohne Backstein oder Blech als Wärmespeicher fehlt der Ofentrieb, und die Semmeln bleiben flach.","Dampf nur in den ersten 10 Minuten: Er hält die Oberfläche geschmeidig, damit das Brötchen aufgehen kann.","Eine Kaisersemmel gilt als „fertig“, wenn sie sich leicht anfühlt und beim Anklopfen auf dem Boden hohl klingt."],"varianten":["Mohn- oder Sesamsemmel: nach dem Wasserbestreichen mit den Körnern bestreuen.","Kaisersemmel mit Dinkelmehl: 200 g des Mehls durch Dinkelmehl Type 630 ersetzen (etwas weniger Wasser).","Wiener Handsemmel: mit Vorteig und längerer Teigführung (mindestens 2 Stunden) für noch saftigere Krume.","Als Semmelbrösel-Quelle: trockene Semmeln reiben und für Wiener Schnitzel panieren."],"beilagen":["Butter und Marmelade","Aufschnitt, Käse und Leberkäse","Als Frühstück mit weich gekochtem Ei","Zum Beispiel für Semmelknödel am Folgetag"],"getraenk":"Milchkaffee oder Melange; zur Brotzeit ein Weißbier.","koeche":[{"name":"Lutz Geißler","bezug":"Hat dem Brötchenbacken zu Hause ein eigenes Buch gewidmet („Brötchen backen – einfach perfekt“, 2021) und steht für naturbelassene Zutaten und gründliche Teigführung.","quelle":"https://de.wikipedia.org/wiki/Lutz_Gei%C3%9Fler"}],"quellen":[{"titel":"Kaisersemmel – Wikipedia","url":"https://de.wikipedia.org/wiki/Kaisersemmel"},{"titel":"Brötchen – Wikipedia","url":"https://de.wikipedia.org/wiki/Br%C3%B6tchen"},{"titel":"Lutz Geißler – Wikipedia","url":"https://de.wikipedia.org/wiki/Lutz_Gei%C3%9Fler"}],"bild":"brot","farben":["#c98a3b","#e8b86a","#f3dfb4"],"schlagworte":["Frühstück","Österreich","Brötchen","Klassiker"],"vegetarisch_moeglich":true,"originalname":"","fleischsorte":"","gang":"brot"},{"id":"oesterreich-leberknoedelsuppe","name":"Leberknödelsuppe","originalname":"","kueche":"oesterreich","region":"Österreich und Bayern","beliebtheit":84,"hauptkategorie":"fleisch","fleischsorte":"innereien","gang":"suppe","kurz":"Kräftige Rindsuppe mit einem zarten, würzigen Leberknödel, der nach Majoran, Zwiebel und frischer Petersilie duftet – Wirtshausklassiker und Sonntagsvorspeise.","hintergrund":"Leberknödel gehören zur traditionellen Küche in Österreich, Bayern, Schwaben, der Pfalz und Tschechien und werden in Bayern und Österreich besonders gern als Einlage in klarer Rindsuppe gegessen. Die Masse besteht aus durch den Fleischwolf gedrehter Rinderleber, eingeweichten altbackenen Semmeln, Ei und Petersilie; die bayerische Version enthält oft etwas Rückenspeck, die Wiener Art wird mit Rindernierenfett locker gehalten. Aus derselben Masse macht man auch Leberspätzle für die Suppe. Wichtig ist, dass der Knödel nur in heißer, aber nicht sprudelnder Flüssigkeit gart, damit er luftig bleibt und nicht zerfällt. Gekochte Leberknödel sollte man sofort essen, denn sie werden beim Stehen fest.","portionen":4,"zeit":{"vorbereitung":40,"garen":170,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Rindsuppe","liste":[{"menge":600,"einheit":"g","name":"Rinderbeinscheibe oder Suppenfleisch (Hochrippe, Wadschinken)","hinweis":"mit Knochen und Sehnen, das ergibt kräftigen Geschmack und Körper"},{"menge":1,"einheit":"Stück","name":"Rindermarkknochen","hinweis":"beim Metzger geschnitten; ersatzweise weglassen"},{"menge":2,"einheit":"l","name":"kaltes Wasser","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"ungeschält halbiert"},{"menge":2,"einheit":"Stück","name":"Möhren","hinweis":"geschält"},{"menge":100,"einheit":"g","name":"Knollensellerie","hinweis":"geschält"},{"menge":1,"einheit":"Stange","name":"Lauch","hinweis":""},{"menge":1,"einheit":"Blatt","name":"Lorbeerblatt","hinweis":""},{"menge":6,"einheit":"Stück","name":"schwarze Pfefferkörner","hinweis":""},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":"erst gegen Ende nachsalzen"}]},{"gruppe":"Für die Leberknödel","liste":[{"menge":250,"einheit":"g","name":"frische Rinderleber","hinweis":"vom Metzger, Haut und Sehnen entfernen lassen; ersatzweise Kalbsleber"},{"menge":2,"einheit":"Stück","name":"Brötchen oder Semmeln vom Vortag","hinweis":"ca. 120 g, in 1 cm kleine Würfel geschnitten"},{"menge":100,"einheit":"ml","name":"lauwarme Milch","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel","hinweis":"ca. 50 g, fein gewürfelt"},{"menge":20,"einheit":"g","name":"Butter","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"Größe M"},{"menge":2,"einheit":"EL","name":"gehackte glatte Petersilie","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Majoran","hinweis":"zwischen den Fingern zerrieben"},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":"sehr fein gehackt"},{"menge":1,"einheit":"Prise","name":"frisch geriebene Muskatnuss","hinweis":""},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":null,"einheit":"","name":"frisch gemahlener Pfeffer","hinweis":"nach Geschmack"},{"menge":30,"einheit":"g","name":"Semmelbrösel","hinweis":"nur zum Nachbinden, falls die Masse zu weich ist"}]},{"gruppe":"Zum Servieren","liste":[{"menge":2,"einheit":"EL","name":"Schnittlauchröllchen","hinweis":""},{"menge":1,"einheit":"Stück","name":"gekochte Möhre aus der Suppe","hinweis":"in feine Streifen geschnitten, optional"}]}],"ausruestung":["großer Suppentopf (mind. 4 l)","Schaumkelle","feines Sieb","Fleischwolf oder Stabmixer","zwei Esslöffel","mittelgroßer Topf zum Garen der Knödel","Schaumlöffel"],"schritte":[{"titel":"Mise en place: Gemüse, Semmeln und Kräuter vorbereiten","aktion":"vorbereiten","text":"Wiege alle Zutaten ab, bevor du anfängst, denn die Knödelmasse verarbeitest du später zügig. Spüle die Rinderbeinscheibe kurz unter kaltem Wasser ab, schäle Möhren und Sellerie und schneide beides mit dem Lauch in grobe, etwa 4 cm große Stücke. Halbiere die Zwiebel samt Schale. Schneide die altbackenen Brötchen in Würfel mit 1 cm Kantenlänge und gib sie in eine große Schüssel. Hacke die Petersilie fein und schneide den Schnittlauch in dünne Röllchen; stelle beides abgedeckt kühl. Die Leber bleibt bis zum Verarbeiten im Kühlschrank, weil sie kalt viel leichter zu pürieren ist.","dauer":0,"tipp":"Die Leber nie zu früh aus dem Kühlschrank nehmen. Je kälter sie bleibt, desto glatter lässt sie sich verarbeiten und desto weniger riecht der Knödel später streng."},{"titel":"Rindsuppe kalt ansetzen und abschäumen","aktion":"kochen","text":"Gib Fleisch, Markknochen und die halbierte Zwiebel in den großen Topf und gieße 2 Liter kaltes Wasser dazu, sodass alles gut bedeckt ist. Kaltes Wasser ist wichtig, weil sich so Eiweiß und Geschmacksstoffe langsam lösen. Erhitze bei mittlerer Hitze und bringe das Wasser bis kurz vor den Siedepunkt. Nach etwa 15 Minuten steigt grauer Eiweißschaum auf, den du mit der Schaumkelle abhebst. Wiederhole das, bis die Oberfläche fast sauber ist, sonst wird die Suppe trüb und schmeckt etwas bitter.","dauer":20,"tipp":"Nicht sprudelnd kochen lassen. Die Suppe soll nur ganz leicht ‚zittern‘, sonst verbinden sich Fett und Eiweiß mit der Brühe und sie wird trüb."},{"titel":"Suppe leise ziehen lassen","aktion":"koecheln","text":"Gib Möhren, Sellerie, Lauch, Lorbeer und Pfefferkörner in den Topf und senke die Hitze, bis nur alle paar Sekunden ein Bläschen aufsteigt. Lege den Deckel schräg auf und lass die Suppe 2 bis 2,5 Stunden ziehen. Das Fleisch ist fertig, wenn du mit einer Gabel ohne Widerstand hineinstechen kannst und die Sehnen weich sind. Die Brühe duftet dann kräftig nach Rind und süßlich nach Gemüse und hat eine goldbraune Farbe. Das Fleisch kannst du später in Streifen als zusätzliche Einlage oder am nächsten Tag mit Meerrettich essen.","dauer":140,"tipp":"Salze erst in der letzten halben Stunde. Wenn die Brühe stark einkocht, wird sie sonst schnell zu salzig."},{"titel":"Semmeln einweichen und Zwiebel anschwitzen","aktion":"vorbereiten","text":"Erwärme die Milch nur lauwarm und gieße sie über die Semmelwürfel, mische vorsichtig und lass alles 15 Minuten durchziehen, bis die Würfel weich sind, aber nicht zu Brei zerfallen. Schmilz die Butter in einer kleinen Pfanne bei mittlerer Hitze und schwitze die fein gewürfelte Zwiebel mit dem Knoblauch etwa 3 Minuten glasig, ohne dass sie Farbe nimmt. Stelle die Pfanne beiseite, damit alles abkühlt; warm würde die Zwiebel die Leber später antrocknen. Drücke die eingeweichten Semmeln mit den Händen kräftig aus, damit die Masse nicht zu nass wird.","dauer":15,"tipp":"Die Semmeln sollen gut ausgedrückt sein, aber noch feucht. Zu viel Milch macht die Knödel weich und bröselig, zu wenig macht sie hart."},{"titel":"Leber vorbereiten und fein pürieren","aktion":"hacken","text":"Löse alle Häute, Sehnen und die groben Gallengänge aus der Leber; sie sind zäh und schmecken bitter. Schneide die Leber in Streifen und drehe sie durch die feine Scheibe des Fleischwolfs, oder püriere sie mit dem Stabmixer in kleinen Portionen zu einer glatten, hellbraunen Masse. Die Leber darf sich dabei nicht erwärmen, arbeite daher mit kurzen Impulsen. Die fertige Masse sieht aus wie grobe Paste und riecht mild-eisenhaltig, aber nicht scharf. Alles, was nach Gallenflüssigkeit riecht oder grünlich schimmert, schneidest du großzügig weg.","dauer":0,"tipp":"Eine Prise Zucker und etwas Muskat in der Masse nehmen den leicht metallischen Leberton, ohne dass man sie schmeckt."},{"titel":"Knödelmasse mischen und ruhen lassen","aktion":"mischen","text":"Gib die pürierte Leber, die ausgedrückten Semmeln, die abgekühlte Zwiebel, das Ei, Petersilie, Majoran, Muskat, Salz und reichlich Pfeffer in die Schüssel und knete alles mit angefeuchteten Händen etwa 2 Minuten durch, bis eine gleichmäßige, leicht klebrige Masse entsteht. Decke sie ab und lass sie 20 Minuten im Kühlschrank ruhen, damit die Semmeln die Feuchtigkeit gleichmäßig aufnehmen. Danach muss die Masse formbar sein und leicht an den Löffeln haften. Ist sie zu weich, arbeite esslöffelweise Semmelbrösel ein, bis sie sich halten lässt.","dauer":20,"tipp":"Die Masse ruhig kräftig würzen. Beim Garen in der Suppe verliert der Knödel Würze an die Brühe."},{"titel":"Probeknödel garen und nachwürzen","aktion":"kochen","text":"Bringe 1 Liter der fertigen Suppe oder gesalzenes Wasser in einem mittelgroßen Topf zum Sieden und senke die Hitze, bis nichts mehr sprudelt. Forme mit zwei angefeuchteten Esslöffeln einen kleinen Probeknödel und lege ihn hinein. Er soll nach etwa 5 Minuten oben schwimmen, nicht zerfallen und im Kern graubraun, nicht mehr rosa sein. Zerfällt er, gib noch 1 bis 2 Esslöffel Semmelbrösel in die Masse; ist er zu fest, rühre einen Schuss Milch ein. Probiere ihn und würze die Masse bei Bedarf mit Salz, Pfeffer oder Majoran nach.","dauer":6,"tipp":"Dieser kleine Test spart dir den Ärger, wenn später alle Knödel im Topf zerfallen. Mache ihn immer."},{"titel":"Knödel formen und gar ziehen lassen","aktion":"formen","text":"Forme aus der Masse mit den angefeuchteten Händen 8 Knödel von etwa 4 bis 5 cm Durchmesser und lasse sie vorsichtig in die leise siedende Flüssigkeit gleiten. Die Temperatur sollte um die 90 °C liegen, also kleine Perlen am Topfboden, aber kein Blubbern. Gare die Knödel 15 bis 18 Minuten mit schräg aufgelegtem Deckel. Sie sind fertig, wenn sie größer geworden sind, oben schwimmen und sich beim Anstechen fest und gleichmäßig graubraun zeigen. Hebe sie mit dem Schaumlöffel heraus und lass sie kurz abtropfen.","dauer":17,"tipp":"Sprudelndes Wasser reißt die Knödel auseinander. Wenn du unsicher bist, lieber etwas länger bei kleiner Hitze garen."},{"titel":"Suppe klären, abschmecken und anrichten","aktion":"anrichten","text":"Gieße die Rindsuppe durch ein feines Sieb in einen sauberen Topf, schmecke sie mit Salz und Pfeffer ab und erhitze sie noch einmal, ohne sie kochen zu lassen. Schneide eine gekochte Möhre in feine Streifen als Einlage. Lege in jeden vorgewärmten Suppenteller 2 Leberknödel und schöpfe die kochend heiße Suppe darüber, sodass die Knödel etwa zur Hälfte eintauchen. Streue Schnittlauch darüber; die Suppe duftet jetzt nach Rind, Majoran und frischen Kräutern. Serviere sofort, denn Leberknödel werden beim Stehen fest.","dauer":0,"tipp":"Ein paar Tropfen Suppe aus dem Teller auf der Zunge zeigen dir, ob noch Salz fehlt. Die Knödel nehmen beim Essen noch Würze auf."}],"profitipps":["Frische, helle Leber verwenden: Sie sollte feucht glänzen, gleichmäßig rötlich-braun sein und mild riechen. Streng riechende oder grünliche Leber nicht kaufen.","Leber immer eiskalt verarbeiten und die Zwiebel abgekühlt dazugeben; so bleibt die Masse locker und die Knödel schmecken nicht nach ‚Innereien‘.","Knödel nie in sprudelndem Wasser garen. Bei etwa 90 °C ziehen sie und werden locker, bei zu starker Hitze zerfallen sie.","Immer einen Probeknödel machen und die Masse notfalls mit Semmelbröseln oder Milch korrigieren.","Die Suppe getrennt von den Knödeln klar halten: Knödel am besten in einem eigenen Topf garen, damit sich keine Bröckchen in der Brühe lösen.","Überzählige Knödel schmecken am nächsten Tag in Scheiben in Butter angebraten mit Sauerkraut oder Zwiebelschmelze."],"varianten":["Bayerische Art: 40 g fein gewürfelter Rückenspeck oder Speck wird mit der Zwiebel ausgelassen und in die Masse gegeben.","Leberspätzlesuppe: Die Masse mit etwas Milch glatter rühren und durch ein Spätzlebrett oder einen Spätzlehobel in die siedende Brühe schaben.","Pfälzer Läwwerknepp: Die Knödel kommen größer geformt mit Sauerkraut und Kartoffelbrei auf den Teller statt in die Suppe.","Gebacken: Die Knödel in heißem Butterschmalz ausbacken und als kräftige Beilage zu Sauerkraut reichen."],"beilagen":["Schwarzbrot oder Bauernbrot mit Butter","frischer Schnittlauch","Meerrettich zum Suppenfleisch"],"getraenk":"Helles Bier (Märzen oder Zwickl) oder ein trockener Grüner Veltliner","koeche":[],"quellen":[{"titel":"Leberknödel (Wikipedia)","url":"https://de.wikipedia.org/wiki/Leberkn%C3%B6del"}],"bild":"suppe","farben":["#a9774a","#d9b27c","#6b8e3e"],"schlagworte":["Wirtshausklassiker","Rindsuppe","Innereien","Bayern","Österreich","Vorspeise"],"vegetarisch_moeglich":false},{"id":"oesterreich-kasspatzln","name":"Kasspatzln","originalname":"Tiroler Kasspatzln","kueche":"oesterreich","region":"Tirol / Vorarlberg","beliebtheit":83,"hauptkategorie":"vegetarisch","gang":"hauptgericht","kurz":"Frisch geschabte Spätzle, mit würzigem Bergkäse geschichtet und mit goldbraunen Röstzwiebeln gekrönt – Hüttenküche vom Feinsten.","hintergrund":"Kasspatzln, in Vorarlberg „Käsknöpfle“ und in der Schweiz „Chäschnöpfli“, sind ein Klassiker der alpinen Küche. Heiße Spätzle werden abwechselnd mit geriebenem Käse geschichtet und mit gerösteten Zwiebeln bestreut. In Tirol und Vorarlberg verwendet man kräftigen Bergkäse, in Schwaben Emmentaler oder Bergkäse, in manchen Gegenden auch Räßkäse. Dazu isst man grünen Salat oder Kartoffelsalat, im Vorarlberger Oberland auch Apfelmus. Der Teig wird nicht geknetet, sondern kräftig geschlagen, bis er Blasen wirft.","portionen":4,"zeit":{"vorbereitung":30,"garen":30,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Spätzleteig","liste":[{"menge":400,"einheit":"g","name":"Mehl (griffig oder Type 550)","hinweis":""},{"menge":4,"einheit":"Stück","name":"Eier (Größe M)","hinweis":""},{"menge":200,"einheit":"ml","name":"Wasser","hinweis":"kalt oder zur Hälfte Milch"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"Prise","name":"frisch geriebene Muskatnuss","hinweis":""}]},{"gruppe":"Für die Käsesauce","liste":[{"menge":300,"einheit":"g","name":"kräftiger Bergkäse","hinweis":"z. B. Vorarlberger Bergkäse, Tiroler Almkäse oder Gruyère; grob gerieben"},{"menge":100,"einheit":"g","name":"Räßkäse oder Emmentaler","hinweis":"optional, für mehr Würze und Schmelz"}]},{"gruppe":"Für die Röstzwiebeln","liste":[{"menge":3,"einheit":"Stück","name":"große Zwiebeln","hinweis":"in dünne Ringe geschnitten"},{"menge":40,"einheit":"g","name":"Butterschmalz oder Butter","hinweis":""},{"menge":null,"einheit":"","name":"Schnittlauch, Pfeffer","hinweis":"zum Servieren"}]}],"ausruestung":["Spätzlebrett und Schaber oder Spätzlehobel","Großer Topf","Backofenfeste Pfanne oder Auflaufform","Schaumkelle","Pfanne für die Zwiebeln"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Reibe den Käse grob und vermische die Sorten in einer Schüssel. Schneide die Zwiebeln in dünne Ringe, denn so werden sie gleichmäßig knusprig. Bringe einen großen Topf mit reichlich Salzwasser zum Kochen, denn die Spätzle brauchen Platz zum Schwimmen. Heize den Backofen auf 100 °C vor und stelle die Pfanne oder Form zum Vorwärmen hinein. Schnittlauch kannst du jetzt schon schneiden.","dauer":10,"tipp":""},{"titel":"Spätzleteig schlagen","aktion":"kneten","text":"Gib Mehl, Eier, Wasser, Salz und Muskat in eine große Schüssel und schlage den Teig mit einem Holzlöffel kräftig, 5–8 Minuten lang, bis er glänzt, zäh vom Löffel reißt und deutlich Blasen wirft. Durch das Schlagen entwickelt sich das Klebergerüst und die Spätzle werden locker und bissfest. Der Teig soll zähflüssig sein, etwa wie dicker Pfannkuchenteig; ist er zu fest, gib einen Schluck Wasser dazu, ist er zu flüssig, ein wenig Mehl.","dauer":8,"tipp":""},{"titel":"Teig ruhen lassen","aktion":"ruhen","text":"Decke die Schüssel mit einem Teller oder Tuch ab und lasse den Teig 20 Minuten bei Zimmertemperatur ruhen. In dieser Zeit entspannt sich der Kleber im Mehl, und der Teig wird geschmeidiger und lässt sich leichter vom Brett schaben, ohne zu reißen oder zu kleben. Nach der Ruhe wirkt die Oberfläche glatter und glänzender, und der Teig fließt etwas zäher vom Löffel. Rühre ihn vor dem Schaben nicht noch einmal kräftig durch, damit die Luftblasen erhalten bleiben und die Spätzle locker werden.","dauer":20,"tipp":""},{"titel":"Röstzwiebeln braten","aktion":"braten","text":"Erhitze das Butterschmalz in einer großen Pfanne bei mittlerer Hitze und gib die Zwiebelringe hinein. Brate sie unter häufigem Rühren 15–20 Minuten, bis sie goldbraun und an den Rändern knusprig sind und süßlich duften. Salze sie erst gegen Ende. Zu viel Hitze lässt sie dunkel und bitter werden; wenn sie zu schnell bräunen, reduziere die Hitze. Stelle sie im Ofen warm.","dauer":20,"tipp":"Mit etwas Mehl bestäubt werden die Zwiebeln besonders knusprig."},{"titel":"Spätzle schaben","aktion":"kochen","text":"Gib eine Portion Teig auf ein nasses Spätzlebrett, streiche ihn dünn aus und schabe mit dem nassen Schaber schmale Streifen in das siedende Salzwasser. Alternativ drückst du den Teig durch einen Spätzlehobel oder eine Presse. Sobald die Spätzle an die Oberfläche steigen, sind sie nach etwa 1–2 Minuten gar. Fische sie mit der Schaumkelle heraus, lasse sie abtropfen und gib sie sofort in die vorgewärmte Pfanne. Arbeite in Portionen, damit das Wasser nicht abkühlt.","dauer":15,"tipp":""},{"titel":"Mit Käse schichten","aktion":"schichten","text":"Gib eine Lage heiße Spätzle in die Pfanne, bestreue sie reichlich mit Käse und wiederhole das, bis alles aufgebraucht ist; die oberste Lage ist Käse. Die Hitze der Spätzle lässt den Käse schmelzen. Wenn du magst, stelle die Pfanne 5 Minuten bei 120 °C in den Ofen, damit der Käse vollständig verläuft. Der Käse soll glänzen und Fäden ziehen, aber nicht bräunen.","dauer":8,"tipp":""},{"titel":"Zwiebeln darübergeben","aktion":"garnieren","text":"Verteile die goldbraunen Röstzwiebeln großzügig über die Kasspatzln und streue frisch gemahlenen Pfeffer und fein geschnittenen Schnittlauch darüber. Die Röstzwiebeln bringen Süße, Röstaroma und Knusprigkeit, die den schweren, salzigen Käse schön ausgleichen. Rühre alles am Tisch kurz mit einer Gabel um, sodass sich Käse, Spätzle und Zwiebeln verbinden und lange Käsefäden entstehen. Serviere sofort, solange der Käse noch flüssig ist, denn aufgewärmt werden die Spätzle zäh und der Käse klumpt.","dauer":0,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Serviere die Kasspatzln am besten direkt in der Pfanne auf einem Holzbrett in der Tischmitte, damit sie warm bleiben und sich jeder selbst bedienen kann. Dazu gehört ein knackiger grüner Salat mit Essig-Öl-Marinade oder ein Kartoffelsalat, dessen Säure den reichhaltigen Käse ausgleicht. In Vorarlberg isst man oft Apfelmus dazu, das mit seiner Süße einen schönen Kontrast bildet. Reste lassen sich am nächsten Tag in einer Pfanne mit etwas Butter knusprig anbraten.","dauer":0,"tipp":""}],"profitipps":["Teig schlagen statt rühren: Die Blasen im Teig machen die Spätzle locker.","Käse nicht zu fein reiben und mit mehreren Sorten mischen für Aroma und Schmelz.","Spätzle ganz heiß mit dem Käse schichten, sonst schmilzt er nicht.","Zwiebeln langsam und lange rösten, nicht verbrennen lassen.","Pfanne und Teller vorwärmen – kalter Käse stoppt das Schmelzen."],"varianten":["Kasnocken (Salzburg/Steiermark)","Käsespätzle aus Schwaben mit Emmentaler","Montafoner Sauerkäse-Variante","Mit Speck und Pilzen"],"beilagen":["Grüner Salat","Kartoffelsalat","Apfelmus"],"getraenk":"Helles Bier oder ein Glas Grüner Veltliner","koeche":[],"quellen":[{"titel":"Käsespätzle – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/K%C3%A4sesp%C3%A4tzle"},{"titel":"TasteAtlas – Austrian dishes ranking","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"nudeln","farben":["#e5b24b","#f4d98a","#8a5a2b"],"schlagworte":["Hüttenküche","Käse","Tirol","Vorarlberg"],"vegetarisch_moeglich":true},{"id":"oesterreich-griessnockerlsuppe","name":"Grießnockerlsuppe","originalname":"","kueche":"oesterreich","region":"Wien und Bayern","beliebtheit":82,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"suppe","kurz":"Klare, goldbraune Rindsuppe mit zarten, luftigen Grießnockerln und frischem Schnittlauch – schlicht, wärmend und das Aushängeschild der Wiener Suppenküche.","hintergrund":"Die Grießnockerlsuppe gilt als Klassiker der Wiener Küche und gehört genauso in die bayerische Küche. Grießeinlagen in klaren Suppen sind im süddeutschen Raum seit langem üblich. Der Teig wird aus schaumig gerührter Butter, Ei und Grieß bereitet, ruht kurz zum Quellen und wird zu ovalen Nockerln geformt, die in Salzwasser garen und erst im Teller mit der Rindsuppe vereint werden. In Österreich wurde die Suppe im Zuge der Rückbesinnung auf die heimische Küche wiederentdeckt. Eine historische Spielart sind die dreifarbigen Sezessionsnockerl aus der ‚Wiener Bürger-Küche‘ von 1902.","portionen":4,"zeit":{"vorbereitung":25,"garen":190,"ruhen":45},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Rindsuppe","liste":[{"menge":700,"einheit":"g","name":"Rindfleisch mit Knochen (Beinscheibe, Tafelspitz oder Schulterscherzel)","hinweis":"Beinscheibe gibt mehr Körper, Tafelspitz mehr Fleisch"},{"menge":2.5,"einheit":"l","name":"kaltes Wasser","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"ungeschält halbiert"},{"menge":2,"einheit":"Stück","name":"Möhren","hinweis":""},{"menge":1,"einheit":"Stück","name":"Petersilienwurzel","hinweis":"ersatzweise Pastinake"},{"menge":100,"einheit":"g","name":"Knollensellerie","hinweis":""},{"menge":1,"einheit":"Stück","name":"Lauchstange","hinweis":""},{"menge":1,"einheit":"Blatt","name":"Lorbeerblatt","hinweis":""},{"menge":8,"einheit":"Stück","name":"Pfefferkörner","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":"zum Schluss abschmecken"}]},{"gruppe":"Für die Grießnockerl","liste":[{"menge":60,"einheit":"g","name":"weiche Butter","hinweis":"Zimmertemperatur"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"Größe M, Zimmertemperatur"},{"menge":110,"einheit":"g","name":"Weizengrieß","hinweis":"mittelfein, sogenannter Hartweizengrieß; kein Instantgrieß"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"Prise","name":"frisch geriebene Muskatnuss","hinweis":""},{"menge":null,"einheit":"","name":"Zitronenschale","hinweis":"fein abgerieben, ein paar Striche, optional"}]},{"gruppe":"Zum Servieren","liste":[{"menge":3,"einheit":"EL","name":"Schnittlauchröllchen","hinweis":""},{"menge":1,"einheit":"Stück","name":"gekochte Möhre aus der Suppe","hinweis":"fein gewürfelt, optional"}]}],"ausruestung":["großer Suppentopf (mind. 5 l)","Schaumkelle","feines Sieb","Rührschüssel und Handrührgerät oder Holzlöffel","zwei Esslöffel","weiter Topf für das Nockerlwasser"],"schritte":[{"titel":"Mise en place: Fleisch und Wurzelgemüse vorbereiten","aktion":"vorbereiten","text":"Lege alle Zutaten bereit und nimm die Butter für die Nockerl schon jetzt aus dem Kühlschrank, damit sie in einer Stunde schön weich ist. Spüle das Rindfleisch kalt ab und tupfe es trocken. Schäle Möhren, Petersilienwurzel und Sellerie und schneide alles in grobe Stücke von etwa 4 cm. Putze den Lauch und wasche ihn zwischen den Blättern gründlich aus. Halbiere die Zwiebel samt Schale; die Schale bringt später die schöne goldbraune Farbe in die Suppe.","dauer":0,"tipp":"Die gesamte Mise en place für die Suppe kannst du schon am Vortag erledigen. Die Rindsuppe schmeckt am nächsten Tag sogar noch runder."},{"titel":"Zwiebel anrösten","aktion":"anbraten","text":"Erhitze eine trockene Pfanne bei mittlerer bis hoher Hitze und lege die beiden Zwiebelhälften mit der Schnittfläche nach unten hinein. Röste sie etwa 5 Minuten, bis die Schnittflächen tiefbraun, an einzelnen Stellen fast schwarz sind und es nussig-karamellig duftet. Das ist der alte Wiener Trick für die gold-bernsteinfarbene Suppe, ohne dass du Farbe nachhelfen musst. Verbrannte, bittere Ränder solltest du abschaben. Die Zwiebel wandert später mit Schale in den Topf.","dauer":5,"tipp":"Wer keine trockene Pfanne verwenden will, kann die Zwiebelhälften auch direkt auf der Herdplatte rösten, wie früher in Wiener Küchen."},{"titel":"Fleisch kalt ansetzen und abschäumen","aktion":"kochen","text":"Lege das Rindfleisch in den Topf, gib die geröstete Zwiebel dazu und gieße 2,5 Liter kaltes Wasser auf. Erhitze langsam und beobachte den Topf: Nach etwa 15 bis 20 Minuten steigt grauer, schaumiger Eiweißrand auf, den du mit der Schaumkelle abhebst. Lass die Suppe niemals sprudeln, sondern nur kurz vor dem Siedepunkt stehen, bis der Schaum zum Stillstand kommt. Je gründlicher du abschäumst, desto klarer und reiner schmeckt die Suppe.","dauer":20,"tipp":"Kaltes Wasser holt das Eiweiß langsam aus dem Fleisch. Bei heißem Wasser gerinnt es sofort, die Suppe schmeckt dann dünner."},{"titel":"Gemüse zugeben und lange ziehen lassen","aktion":"koecheln","text":"Gib Möhren, Petersilienwurzel, Sellerie, Lauch, Lorbeer und Pfeffer in den Topf und drehe die Hitze zurück, bis die Oberfläche nur noch an einer Stelle leicht zittert. Lege den Deckel schräg auf und lass alles 2,5 bis 3 Stunden ziehen. Das Fleisch ist gar, wenn sich eine Gabel ohne Widerstand hineinschieben lässt. Die Suppe riecht intensiv nach Rind und leicht süßlich und hat die Farbe von dunklem Bernstein. Nach etwa zwei Stunden kannst du vorsichtig mit Salz abschmecken.","dauer":150,"tipp":"Das Gemüse kann im Topf bleiben, bis es weich ist. Wenn du eine feine Einlage willst, koche eine extra Möhre separat bissfest."},{"titel":"Suppe abseihen und entfetten","aktion":"abseihen","text":"Nimm das Fleisch und das Gemüse mit der Schaumkelle heraus und gieße die Suppe durch ein feines Sieb, am besten mit einem sauberen Tuch ausgelegt, in einen frischen Topf. Lass sie kurz stehen, damit sich das Fett oben sammelt, und schöpfe es mit einem Löffel ab; ein Rest bleibt als Geschmacksträger. Schmecke die Suppe mit Salz und frisch gemahlenem Pfeffer ab. Sie soll klar, goldfarben und kräftig im Geschmack sein; ist sie zu schwach, lass sie bei geöffnetem Deckel etwas einkochen.","dauer":0,"tipp":"Das herausgenommene Rindfleisch ist am nächsten Tag mit Kren und Schnittlauchsauce ein eigenes Gericht."},{"titel":"Nockerlteig rühren","aktion":"aufschlagen","text":"Rühre die weiche Butter mit dem Handrührgerät oder Holzlöffel etwa 2 Minuten schaumig-cremig, bis sie heller und luftig aussieht. Gib das Ei dazu und rühre weiter, bis die Masse glatt gebunden ist und nicht gerinnt. Mische Grieß, Salz, Muskat und ein paar Striche Zitronenschale unter, bis ein gleichmäßig weicher, noch leicht klebriger Teig entsteht. Der Teig sieht jetzt etwas flüssig aus, das ist richtig, denn der Grieß quillt gleich noch auf.","dauer":0,"tipp":"Zimmerwarme Butter und Eier sind entscheidend. Ist die Butter kalt, entsteht keine schaumige Masse und die Nockerl werden dicht."},{"titel":"Teig ruhen lassen","aktion":"ruhen","text":"Decke die Schüssel ab und stelle den Teig für mindestens 30 Minuten, besser 45 Minuten, in den Kühlschrank. In dieser Zeit saugt der Grieß Feuchtigkeit aus Ei und Butter und quillt, der Teig wird fester und lässt sich formen. Wenn du zu früh formst, zerfallen die Nockerl im Wasser, nach zu langer Ruhe wird der Teig dagegen sehr fest, was sich kurz mit einem Teelöffel Wasser beheben lässt. Er sollte wie ein weicher, zusammenhaltender Brei aussehen.","dauer":45,"tipp":"Halte zwei Esslöffel und eine Tasse heißes Wasser bereit. Mit heißen Löffeln gleiten die Nockerl leichter vom Löffel."},{"titel":"Nockerl formen und gar ziehen","aktion":"formen","text":"Bringe in einem weiten Topf reichlich Salzwasser zum Kochen und senke die Hitze, sodass es nur noch leicht siedet. Tauche zwei Esslöffel in heißes Wasser, steche mit einem Löffel eine Portion Teig ab und forme mit dem zweiten Löffel ein ovales Nockerl, das du in das Wasser gleiten lässt. Mache so 12 bis 16 Nockerl und lege den Deckel auf. Lass sie etwa 10 Minuten ziehen, danach drehst du sie um und gibst sie noch 5 Minuten zu, bis sie aufgegangen sind und fest, aber luftig wirken.","dauer":15,"tipp":"Eine Kontrolle: Schneide ein Nockerl auf. Es soll gleichmäßig hell, locker und ohne nassen, dunklen Kern sein."},{"titel":"Anrichten","aktion":"anrichten","text":"Erhitze die Rindsuppe, ohne sie kochen zu lassen. Hebe die Nockerl mit dem Schaumlöffel aus dem Wasser, lass sie kurz abtropfen und lege je 3 bis 4 Stück in vorgewärmte Teller. Schöpfe die heiße Suppe darüber und streue reichlich Schnittlauch darauf. Dass die Nockerl getrennt gegart werden, ist wichtig, weil sie die Suppe sonst trüben. Serviere sofort, denn Nockerl saugen Flüssigkeit auf und werden beim Stehen weich.","dauer":0,"tipp":"Für Gäste: Nockerl schon am Vortag garen, kalt stellen und in der heißen Suppe 3 Minuten durchziehen lassen."}],"profitipps":["Beim Wasser für die Nockerl auf leises Sieden achten: Sprudelndes Wasser lässt sie zerfallen, lauwarmes Wasser macht sie schwer.","Die Ruhezeit des Teigs ist kein Luxus: Ohne Quellzeit des Grießes werden die Nockerl weich und bröselig.","Ein Probenockerl bestätigt Teigkonsistenz und Salzmenge, bevor alle im Topf landen. Zu weich: 1 EL Grieß einarbeiten, zu fest: 1 TL Wasser.","Nockerl nie in der Suppe garen: Sie trüben sie und nehmen zu viel Flüssigkeit auf.","Wer die Suppe besonders klar will, hängt ein Stück Küchenpapier kurz auf die Oberfläche und tupft Fettaugen ab."],"varianten":["Sezessionsnockerl: Der Teig wird gedrittelt und eines davon mit Spinatpüree grün, eines mit Tomatenmark rot gefärbt, das letzte bleibt gelb.","Mit feinen Karottenstreifen, die in der Suppe mitgegart werden, für mehr Farbe und Süße.","Gewürzvariante: Zitronenschale, ein Hauch Ingwer oder Chili im Teig.","Kräuter-Nockerl: 1 EL fein gehackte Petersilie oder Schnittlauch direkt unter den Teig gerührt."],"beilagen":["Schwarzbrot oder Semmel","Schnittlauch","Kren zum gekochten Rindfleisch"],"getraenk":"Leichter Grüner Veltliner oder ein Glas Mineralwasser","koeche":[{"name":"J. M. Heitz","bezug":"Der Wiener Kochschulleiter beschrieb in seiner ‚Wiener Bürger-Küche‘ von 1902 die dreifarbigen Sezessionsnockerl – eine Spielart der Grießnockerl mit grünem, rotem und gelbem Teigdrittel.","quelle":"https://de.wikipedia.org/wiki/Grie%C3%9Fnockerlsuppe"}],"quellen":[{"titel":"Grießnockerlsuppe (Wikipedia)","url":"https://de.wikipedia.org/wiki/Grie%C3%9Fnockerlsuppe"}],"bild":"suppe","farben":["#d9a443","#f3d98a","#6b8e3e"],"schlagworte":["Wiener Küche","Klassiker","Rindsuppe","Vorspeise","Sonntagsessen"],"vegetarisch_moeglich":false},{"id":"oesterreich-germknoedel","name":"Germknödel mit Powidl und Mohnzucker","originalname":"Germknödel","kueche":"oesterreich","region":"Österreich / Skigebiete","beliebtheit":80,"hauptkategorie":"suess","gang":"dessert","kurz":"Fluffiger, gedämpfter Hefeknödel mit Powidl-Füllung, Mohnzucker und flüssiger Butter, dazu warme Vanillesauce.","hintergrund":"Der Germknödel (Hefeknödel) ist eine Süßspeise der österreichischen und bayerischen Küche und ein Klassiker der Skihütten. Der Teig aus Hefe, Milch, Butter und Zucker wird um eine Füllung aus Powidl, dem eingekochten Pflaumenmus, geformt, gedämpft und mit Mohnzucker und zerlassener Butter bestreut. Er ist verwandt mit der Dampfnudel. Typisch ist die Kombination aus luftigem Teig, würziger Pflaumenfüllung und dem leicht knackigen Mohn.","portionen":6,"zeit":{"vorbereitung":40,"garen":20,"ruhen":90},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Hefeteig","liste":[{"menge":500,"einheit":"g","name":"Mehl (Type 550)","hinweis":"plus Mehl zum Arbeiten"},{"menge":21,"einheit":"g","name":"frische Hefe","hinweis":"oder 1 Pck. Trockenhefe"},{"menge":250,"einheit":"ml","name":"lauwarme Milch","hinweis":""},{"menge":60,"einheit":"g","name":"Zucker","hinweis":""},{"menge":60,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ei (Größe M)","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"abgeriebene Zitronenschale","hinweis":""}]},{"gruppe":"Füllung und Topping","liste":[{"menge":180,"einheit":"g","name":"Powidl (Pflaumenmus)","hinweis":"ersatzweise dickes Pflaumenmus; Gewürzmischung mit Zimt und Nelke ist üblich"},{"menge":100,"einheit":"g","name":"gemahlener Mohn","hinweis":"frisch gemahlen"},{"menge":60,"einheit":"g","name":"Puderzucker","hinweis":""},{"menge":100,"einheit":"g","name":"Butter","hinweis":"zerlassen"}]},{"gruppe":"Vanillesauce","liste":[{"menge":500,"einheit":"ml","name":"Milch","hinweis":""},{"menge":1,"einheit":"Stück","name":"Vanilleschote","hinweis":""},{"menge":3,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":50,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Speisestärke","hinweis":""}]}],"ausruestung":["Dampfgarer, Dämpfeinsatz oder großer Topf mit Siebeinsatz","Rührschüssel","Teigschaber","Mohnmühle oder Mixer","Kleiner Topf"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und nimm Butter, Ei und Milch rechtzeitig aus dem Kühlschrank. Wärme die Milch auf etwa 30 °C an, also so, dass sie sich am Finger nur eben lauwarm anfühlt; ist sie zu heiß, stirbt die Hefe ab, ist sie zu kalt, geht der Teig kaum auf. Mahle den Mohn frisch in der Mohnmühle oder im Mixer, falls er nicht schon gemahlen ist. Bereite den Dampfeinsatz vor und fette ihn leicht mit Butter ein, damit nichts anklebt. Reibe außerdem die Zitronenschale ab.","dauer":10,"tipp":""},{"titel":"Vorteig ansetzen","aktion":"gehen","text":"Bröckle die frische Hefe in die lauwarme Milch, rühre einen Teelöffel Zucker und zwei Esslöffel Mehl ein, sodass ein dünner Brei entsteht, und lasse ihn 10 Minuten zugedeckt an einem warmen Ort stehen. Er ist bereit, wenn die Oberfläche Blasen wirft, der Brei sich sichtbar aufbläht und es angenehm nach Hefe duftet. Wirft er keine Blasen, war die Hefe zu alt oder die Milch zu kalt beziehungsweise zu heiß; in diesem Fall beginne lieber mit frischen Zutaten neu.","dauer":10,"tipp":""},{"titel":"Hefeteig kneten","aktion":"kneten","text":"Gib Mehl, Zucker, Salz, Zitronenschale, Ei, weiche Butter und den Vorteig in eine Schüssel und knete alles 8–10 Minuten kräftig durch, bis ein glatter, geschmeidiger Teig entsteht, der sich vom Schüsselrand löst. Er soll weich, aber nicht klebrig sein. Der Fensterscheibentest: Ziehe ein kleines Stück Teig auseinander – es soll sich dünn dehnen lassen, ohne zu reißen.","dauer":10,"tipp":""},{"titel":"Teig gehen lassen","aktion":"gehen","text":"Forme den Teig zu einer Kugel, lege ihn in eine leicht gefettete Schüssel, decke ihn mit einem feuchten Tuch ab und lasse ihn an einem warmen Ort (etwa 28–30 °C) 45–60 Minuten gehen, bis er sein Volumen verdoppelt hat. Du erkennst es daran, dass eine Fingerkuhle langsam zurückfedert. Zu kalte Umgebung verlängert die Zeit, Zugluft lässt eine Haut entstehen.","dauer":60,"tipp":""},{"titel":"Knödel füllen und formen","aktion":"fuellen","text":"Knete den Teig kurz durch und teile ihn in 6 gleich große Stücke (je etwa 140 g). Drücke jedes zu einer Platte, gib in die Mitte einen Esslöffel Powidl und schließe den Teig fest darüber. Rolle die Teigstücke zu glatten Kugeln, die Naht muss dicht sein, damit die Füllung nicht ausläuft. Lege sie mit der Naht nach unten auf eine bemehlte Fläche, decke sie ab und lasse sie 15–20 Minuten ruhen, bis sie wieder aufgegangen sind.","dauer":25,"tipp":""},{"titel":"Dämpfen","aktion":"daempfen","text":"Bringe Wasser im Dampftopf zum Kochen und lege die Knödel mit etwas Abstand in den gefetteten Siebeinsatz. Schließe den Deckel fest und dämpfe sie 15–18 Minuten bei mittlerer Hitze, ohne den Deckel zu öffnen. Die Knödel sind fertig, wenn sie aufgegangen sind, glänzend und fest sind und ein Holzstäbchen sauber herauskommt. Steche sie sofort nach dem Dämpfen mit einer Nadel an, damit der Dampf entweichen kann und sie nicht zusammenfallen.","dauer":18,"tipp":""},{"titel":"Vanillesauce kochen","aktion":"koecheln","text":"Erhitze die Milch mit der aufgeschlitzten Vanilleschote. Verrühre Eigelb, Zucker und Stärke in einer Schüssel cremig, gieße die heiße Milch unter Rühren dazu, gib alles zurück in den Topf und erhitze unter Rühren auf 80 °C, bis die Sauce den Löffel überzieht. Koche sie nicht auf, sonst gerinnt das Eigelb. Seihe sie durch ein Sieb und halte sie warm.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Mische den frisch gemahlenen Mohn mit dem Puderzucker. Lege die noch heißen Knödel auf vorgewärmte tiefe Teller, übergieße sie großzügig mit zerlassener Butter und bestreue sie mit dem Mohnzucker, sodass sie dick bedeckt sind. Serviere sofort mit der warmen Vanillesauce, die extra gereicht wird, denn so bleibt der Teig weich und die Butter flüssig. Beim Aufschneiden dampft die Füllung, und der Teig ist fluffig-weich, fast wie Brot, während der Mohn leicht knackt und nussig schmeckt.","dauer":0,"tipp":""}],"profitipps":["Milch nur lauwarm verwenden – zu heiß zerstört die Hefe, zu kalt bremst sie.","Teig gut gehen lassen, bis er sein Volumen verdoppelt hat; nur dann werden die Knödel locker.","Naht sorgfältig verschließen, sonst läuft der Powidl aus.","Knödel sofort nach dem Dämpfen anstechen, damit sie nicht zusammenfallen.","Mohn frisch mahlen – er duftet intensiver als fertig gemahlener."],"varianten":["Mit Marmelade statt Powidl","Mit Topfen im Teig","In der Skihütte mit Vanillesauce und Mohn serviert","Salzwasser-Variante: Knödel statt Dämpfen kochen"],"beilagen":["Vanillesauce","Zimtzucker","Pflaumenröster"],"getraenk":"Heißer Tee mit Rum (Jagatee) oder ein Glas Prädikatswein","koeche":[],"quellen":[{"titel":"Germknödel – Wikipedia","url":"https://en.wikipedia.org/wiki/Germkn%C3%B6del"},{"titel":"Germknödel – Küchenlatein","url":"https://kuechenlatein.com/waiter-theres-something-in-my-germknoedel-yeast-dumpling/"},{"titel":"Kochbuch Germknödel – Tannheimer Tal","url":"https://www.tannheimertal.com/pdfs/rezepte/kochbuch_germknodel.pdf"},{"titel":"TasteAtlas – Austrian dishes ranking","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"knoedel","farben":["#e8d3b0","#4a2c4f","#c9a77a"],"schlagworte":["Skihütte","Hefeteig","Winter","Mehlspeise"],"vegetarisch_moeglich":true},{"id":"oesterreich-zwetschgenknoedel-butterbroesel","name":"Zwetschgenknödel mit Butterbröseln","kueche":"oesterreich","region":"Österreich, Böhmen, Süddeutschland","beliebtheit":80,"kurz":"Zarter Kartoffelteig um eine saftige, mit Zucker gefüllte Zwetschge, gekocht und in goldenen Butterbröseln gewälzt.","hintergrund":"Zwetschgenknödel sind Spätsommer-Küche pur: Wenn die Hauszwetschgen reif sind, werden sie in Österreich, Böhmen und Süddeutschland in Kartoffelteig (oder Topfenteig) gehüllt und in Salzwasser gegart. Das Würfelzuckerstück im Inneren schmilzt zu einem Sirup, der den Fruchtsaft bindet. Gewälzt wird in Butterbröseln mit Zimt und Zucker, bestäubt mit Staubzucker. Als süßes Hauptgericht gehören sie zu den Mehlspeisen der Alpenländer.","portionen":4,"zeit":{"vorbereitung":45,"garen":20,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig (ca. 12 Knödel)","liste":[{"menge":600,"einheit":"g","name":"mehlig kochende Kartoffeln","hinweis":"am Vortag in der Schale gekocht und abgekühlt"},{"menge":150,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"plus Mehl zum Arbeiten"},{"menge":40,"einheit":"g","name":"Weichweizengrieß","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ei (Größe M)","hinweis":""},{"menge":30,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""}]},{"gruppe":"Für die Füllung","liste":[{"menge":12,"einheit":"Stück","name":"kleine Zwetschgen","hinweis":"reif, aber fest, entsteint"},{"menge":12,"einheit":"Stück","name":"Würfelzucker","hinweis":"oder 12 TL Zucker mit Zimt"},{"menge":1,"einheit":"Msp.","name":"Zimt","hinweis":""}]},{"gruppe":"Für die Butterbrösel","liste":[{"menge":80,"einheit":"g","name":"Butter","hinweis":""},{"menge":100,"einheit":"g","name":"Semmelbrösel","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Zimt","hinweis":""},{"menge":2,"einheit":"EL","name":"Staubzucker","hinweis":"zum Bestäuben"}]}],"ausruestung":["Kartoffelpresse","großer Topf","Schaumlöffel","Pfanne"],"schritte":[{"titel":"Kartoffeln vorbereiten","aktion":"vorbereiten","text":"Koche die Kartoffeln am Vortag in der Schale gar, lass sie abkühlen und stelle sie kalt. Am nächsten Tag pellst du sie und drückst sie durch die Kartoffelpresse auf ein Brett, damit eine lockere, trockene Masse entsteht. Kalte, gut ausgedampfte Kartoffeln nehmen weniger Mehl auf und der Teig wird zarter. Wiege Mehl und Grieß ab und halte Butter, Ei und Salz bereit.","dauer":15,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib Mehl, Grieß, Ei, Butter und Salz zu den Kartoffeln und knete alles rasch mit den Händen, bis ein glatter, geschmeidiger Teig entsteht, der kaum noch klebt. Arbeite nicht zu lange, denn je länger du knetest, desto zäher und klebriger wird die Kartoffelstärke. Ist der Teig noch zu feucht, gib löffelweise Mehl dazu, bis er sich ausrollen lässt. Lass ihn zugedeckt 20 Minuten ruhen.","dauer":20,"tipp":""},{"titel":"Zwetschgen füllen","aktion":"fuellen","text":"Schneide die Zwetschgen entlang der Naht auf und entferne den Stein, ohne sie zu teilen. Steck in jede Frucht ein Stück Würfelzucker mit einer Prise Zimt und drücke sie sanft wieder zu. Der Zucker löst sich beim Garen und verhindert, dass die Frucht wässrig oder zu sauer wird. Bei sehr süßen Früchten reicht ein halber Würfel.","dauer":10,"tipp":""},{"titel":"Knödel formen","aktion":"formen","text":"Rolle den Teig auf einer bemehlten Fläche zu einer Rolle und teile sie in zwölf gleich große Stücke. Drücke jedes Stück flach, setze eine gefüllte Zwetschge in die Mitte und umhülle sie komplett mit Teig. Presse die Nahtstellen gut zusammen und rolle den Knödel zwischen feuchten Händen rund. Er muss vollkommen geschlossen sein, sonst platzt er beim Kochen auf.","dauer":15,"tipp":"Hände leicht mit Mehl oder Wasser benetzen, dann klebt der Teig weniger."},{"titel":"Knödel garen","aktion":"kochen","text":"Bringe in einem großen Topf reichlich Salzwasser zum Kochen und reduziere die Hitze, bis es nur noch leise siedet. Lege die Knödel hinein, ohne sie zu stapeln, und lass sie 12 bis 15 Minuten ziehen. Sie sinken zuerst ab und steigen nach einigen Minuten nach oben; ab da noch etwa fünf Minuten weiter garen. Sprudelndes Wasser reißt die Knödel auseinander.","dauer":15,"tipp":""},{"titel":"Butterbrösel rösten","aktion":"braten","text":"Schmelze die Butter in der Pfanne bei mittlerer Hitze, gib die Semmelbrösel dazu und rühre ständig, bis sie goldbraun sind und nussig duften, etwa vier bis fünf Minuten. Mische Zucker und Zimt unter und nimm die Pfanne vom Herd, bevor der Zucker dunkel wird. Die Brösel sollen knusprig und locker sein, nicht fettig.","dauer":6,"tipp":""},{"titel":"Wälzen und anrichten","aktion":"anrichten","text":"Hebe die Knödel mit dem Schaumlöffel aus dem Wasser, lass sie kurz abtropfen und wälze sie in der Bröselmischung, bis sie rundum bedeckt sind. Setze je drei Knödel auf einen Teller, bestäube sie mit Staubzucker und serviere sofort. Beim Anschneiden fließt der heiße Zwetschgensaft heraus – ein Zeichen, dass alles richtig gelaufen ist. Dazu passt Vanillesoße oder Zimtsahne.","dauer":3,"tipp":""}],"profitipps":["Kartoffeln am Vortag kochen – frische, feuchte Kartoffeln brauchen zu viel Mehl.","Einen Probeknödel kochen: Zerfällt er, noch etwas Mehl oder Grieß einarbeiten.","Das Wasser nur siedend halten, nie sprudelnd.","Kleine, feste Zwetschgen verwenden; große machen den Teig zu dünn.","Fertig geformte Knödel lassen sich roh einfrieren und direkt aus dem Froster kochen."],"varianten":["Aus Topfenteig statt Kartoffelteig","Mit Marille statt Zwetschge","Mit Nougatstückchen in der Füllung","Mit Mohn-Butterbröseln"],"beilagen":["Vanillesoße","Zimtsahne","Staubzucker"],"getraenk":"Ein Glas Zwetschgenbrand oder Milchkaffee","koeche":[],"quellen":[{"titel":"Omas Zwetschgenknödel aus Kartoffelteig – lecker.de","url":"https://www.lecker.de/zwetschgenknoedel-der-klassiker-aus-kartoffelteig-84150.html"},{"titel":"Zwetschgenknödel nach Omas Rezept – Gault&Millau","url":"https://gaultmillau.ch/rezepte/zwetschgenknodel-nach-omas-rezept-304479"}],"bild":"knoedel","farben":["#5d3a6b","#e6c68a","#8c5a2a"],"schlagworte":["Spätsommer","Mehlspeise","Zwetschgen","süßes Hauptgericht"],"originalname":"","fleischsorte":"","hauptkategorie":"suess","gang":"dessert","vegetarisch_moeglich":true},{"id":"oesterreich-linzer-torte","name":"Linzer Torte","originalname":"Linzer Torte","kueche":"oesterreich","region":"Oberösterreich (Linz)","beliebtheit":79,"hauptkategorie":"suess","gang":"kuchen","kurz":"Mürber, würziger Mandelteig mit Ribiselmarmelade und dem typischen Gitter – je länger sie durchzieht, desto besser.","hintergrund":"Die Linzer Torte gilt als eine der ältesten Torten der Welt. Das älteste überlieferte Rezept mit „Linz“ im Titel steht in einer Handschrift von 1653 aus dem Stiftsarchiv Admont. Typisch sind der braune, mürbteigartige Teig aus Mehl, Butter, Zucker, Ei und Mandeln oder Haselnüssen, gewürzt mit Zimt, Nelken und Zitrone, die Füllung aus Ribiselmarmelade (rote Johannisbeere) und das Gitter obenauf. Das Gitter verhindert, dass die Füllung beim Backen aufreißt. Die Torte schmeckt am besten, wenn sie einige Tage durchgezogen ist.","portionen":12,"zeit":{"vorbereitung":40,"garen":45,"ruhen":180},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Linzer Teig (Springform 24 cm)","liste":[{"menge":250,"einheit":"g","name":"Mehl (glatt, Type 405)","hinweis":""},{"menge":200,"einheit":"g","name":"kalte Butter","hinweis":"in Würfeln"},{"menge":200,"einheit":"g","name":"gemahlene ungeschälte Mandeln","hinweis":"oder Haselnüsse"},{"menge":150,"einheit":"g","name":"Puderzucker","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ei (Größe M)","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":1,"einheit":"TL","name":"Zimt","hinweis":""},{"menge":1,"einheit":"Msp.","name":"gemahlene Gewürznelken","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"Stück","name":"unbehandelte Zitrone","hinweis":"abgeriebene Schale"},{"menge":1,"einheit":"EL","name":"Rum oder Kirschwasser","hinweis":""}]},{"gruppe":"Füllung und Garnitur","liste":[{"menge":300,"einheit":"g","name":"Ribiselmarmelade (rote Johannisbeere)","hinweis":"ersatzweise Johannisbeergelee oder Himbeermarmelade"},{"menge":1,"einheit":"Stück","name":"Eigelb","hinweis":"zum Bestreichen"},{"menge":30,"einheit":"g","name":"Mandelblättchen","hinweis":""}]}],"ausruestung":["Springform 24 cm","Nudelholz","Teigrad oder Messer","Backpapier","Pinsel","Teigschaber"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und halte die Butter kalt, denn nur kalte Butter ergibt einen mürben Teig, der beim Backen nicht zerläuft und die Mandeln gut bindet. Reibe die Zitronenschale ab und mische Zimt, Nelken und Salz mit dem Mehl, damit sich die Gewürze gleichmäßig verteilen. Fette die Springform leicht ein und lege den Boden mit Backpapier aus. Den Ofen heizt du erst nach der Teigruhe vor, damit er nicht unnötig läuft.","dauer":10,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib Mehl, Mandeln, Puderzucker, Gewürze und Zitronenschale in eine Schüssel, vermische alles und gib die kalten Butterwürfel, Ei, Eigelb und Rum dazu. Verknete alles mit kühlen Händen oder der Küchenmaschine rasch zu einem glatten Teig. Knete nicht zu lange, damit die Butter nicht schmilzt und der Teig nicht zäh wird. Er soll weich und leicht klebrig, aber formbar sein.","dauer":8,"tipp":""},{"titel":"Teig kühlen","aktion":"kuehlen","text":"Teile den Teig in zwei Portionen, eine größere (etwa zwei Drittel) für Boden und Rand und eine kleinere für das Gitter. Wickle beide in Folie, drücke sie flach und kühle sie mindestens 1–2 Stunden im Kühlschrank. In der Kälte wird die Butter fest, der Teig lässt sich nachher besser ausrollen und die Mandeln können quellen. Du merkst, dass er bereit ist, wenn er sich fest und kühl anfühlt, aber nicht bröselt.","dauer":90,"tipp":""},{"titel":"Boden und Rand formen","aktion":"ausrollen","text":"Rolle den größeren Teigteil zwischen zwei Bögen Backpapier auf etwa 5 mm Dicke aus und lege ihn mit dem Papier in die Springform. Drücke den Teig am Boden und am Rand etwa 2–3 cm hoch fest an, achte auf gleichmäßige Dicke und prüfe, dass keine Risse bleiben. Steche den Boden mit einer Gabel mehrfach ein, damit er beim Backen keine Blasen wirft. Reißt der Teig, flicke ihn einfach mit kleinen Teigstücken zusammen – der Mürbteig verzeiht das und die Naht verschwindet beim Backen.","dauer":10,"tipp":""},{"titel":"Füllen und Gitter legen","aktion":"schichten","text":"Verrühre die Marmelade glatt und streiche sie gleichmäßig auf dem Teigboden aus. Rolle den restlichen Teig aus, schneide ihn mit dem Teigrad in etwa 1 cm breite Streifen und lege sie gitterförmig über die Marmelade, sodass Rauten entstehen. Drücke die Enden fest an den Rand. Das Gitter ist nicht nur Zierde, sondern lässt Dampf entweichen, damit die Füllung nicht aufreißt.","dauer":10,"tipp":"Zu weicher Teig lässt sich im Kühlschrank 10 Minuten nachfestigen."},{"titel":"Backen","aktion":"backen","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor. Bestreiche das Gitter und den Rand mit Eigelb und streue Mandelblättchen auf den Rand. Backe die Torte auf der unteren Schiene etwa 40–45 Minuten, bis der Teig goldbraun ist und die Marmelade leicht Blasen wirft. Dabei duftet es nach Zimt, Nelken und gerösteten Mandeln. Ist der Rand zu dunkel, decke ihn mit Alufolie ab.","dauer":45,"tipp":""},{"titel":"Auskühlen und durchziehen lassen","aktion":"kuehlen","text":"Lasse die Torte in der Form auskühlen und löse sie erst dann, damit sie nicht bricht. Bewahre sie in einer Dose bei Zimmertemperatur 2–3 Tage auf; erst dann haben Marmelade und Teig ihr volles Aroma entwickelt und der Teig wird mürbe-weich. Schneide sie mit einem scharfen, großen Messer in Stücke. Serviere sie mit Schlagobers oder einfach zu Kaffee.","dauer":60,"tipp":""}],"profitipps":["Butter kalt halten und den Teig nicht zu lange kneten, sonst wird er hart.","Teig vor dem Ausrollen kühlen – lauwarmer Teig klebt und reißt.","Marmelade nicht zu dünn auftragen und nicht zu süß wählen: Ribisel (Johannisbeere) bringt Säure.","Torte 2–3 Tage durchziehen lassen – sie schmeckt dann viel besser.","Gitter locker legen, sonst bricht es beim Backen auf."],"varianten":["Mit Haselnüssen statt Mandeln","Weißer Linzer Teig mit Zitronenabrieb und Eigelb","Linzer Augen (Plätzchen)","Mit Himbeer- oder Marillenmarmelade"],"beilagen":["Schlagobers","Kaffee"],"getraenk":"Kaffee oder ein Glas Portwein","koeche":[],"quellen":[{"titel":"Linzer Torte – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Linzer_Torte"},{"titel":"Linzer torte – Wikipedia (en)","url":"https://en.wikipedia.org/wiki/Linzer_torte"}],"bild":"torte","farben":["#8a4a24","#b3262e","#e0b57a"],"schlagworte":["Alte Torte mit Geschichte","Mürbteig","Weihnachtsgebäck","Linz"],"vegetarisch_moeglich":true},{"id":"oesterreich-backhendl","name":"Backhendl","originalname":"Wiener Backhendl","kueche":"oesterreich","region":"Wien / Steiermark","beliebtheit":78,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Hendlviertel in knuspriger Brösel-Panade, in reichlich Fett goldbraun ausgebacken – mit Erdäpfelsalat, Zitrone und frittierter Petersilie.","hintergrund":"Das Backhendl ist ein Klassiker der Wiener Küche und wird seit dem 18. Jahrhundert zubereitet. Früher wurde das Huhn vollständig entbeint und flachgeklopft, in der Biedermeierzeit galt es als Inbegriff der feinen Wiener Küche. Heute zerteilt man ein junges Hendl in Viertel, paniert es wie ein Wiener Schnitzel und backt es in reichlich Fett aus. Typisch sind die frittierten Petersilienbüschel, Zitronenspalten und ein lauwarmer Erdäpfelsalat oder grüner Salat. Das Fleisch bleibt saftig, die Haut knusprig.","portionen":4,"zeit":{"vorbereitung":35,"garen":25,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Backhendl","liste":[{"menge":2,"einheit":"Stück","name":"junge Hendl (Hähnchen, je 1,2–1,4 kg)","hinweis":"in Viertel geteilt (Brust mit Flügelansatz, Keule); alternativ 4 Hähnchenschenkel und 4 Brüste mit Knochen"},{"menge":2,"einheit":"TL","name":"Salz","hinweis":"kräftig"},{"menge":100,"einheit":"g","name":"glattes Mehl (Type 405)","hinweis":""},{"menge":3,"einheit":"Stück","name":"Eier (Größe M)","hinweis":""},{"menge":1,"einheit":"EL","name":"Öl","hinweis":"zum Verquirlen mit den Eiern"},{"menge":200,"einheit":"g","name":"Semmelbrösel","hinweis":"fein, aus Weißbrot"},{"menge":1,"einheit":"kg","name":"Butterschmalz oder Frittieröl","hinweis":"für eine Fetthöhe von 3–4 cm"}]},{"gruppe":"Zum Servieren","liste":[{"menge":2,"einheit":"Stück","name":"Zitronen","hinweis":"in Spalten"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"einige Zweige zum Frittieren"},{"menge":600,"einheit":"g","name":"festkochende Kartoffeln für Erdäpfelsalat","hinweis":"oder grüner Blattsalat"}]}],"ausruestung":["Hohe, schwere Pfanne oder Fritteuse","Fett-/Bratenthermometer","Schaumkelle oder Zange","3 flache Teller","Küchenpapier","Backofen zum Warmhalten"],"schritte":[{"titel":"Mise en place und Hendl zerteilen","aktion":"vorbereiten","text":"Teile die Hendl mit einer Geflügelschere oder einem schweren Messer in Viertel, schneide die Schenkel am Gelenk leicht ein, damit sie gleichmäßig garen, und entferne überstehende Fettstücke. Die Haut bleibt dran, denn sie wird später knusprig. Tupfe die Stücke gründlich mit Küchenpapier trocken, denn Feuchtigkeit lässt die Panade nicht haften. Stelle Mehl, Eier und Brösel in drei flachen Tellern bereit und wasche die Petersilie.","dauer":15,"tipp":"Geflügel aus Bio- oder Freilandhaltung hat festeres Fleisch und mehr Geschmack."},{"titel":"Würzen und ruhen","aktion":"marinieren","text":"Salze die Hendlstücke von allen Seiten kräftig und reibe das Salz leicht ein, denn die Panade ist selbst fast ungewürzt. Lege die Stücke 20–30 Minuten abgedeckt in den Kühlschrank, damit das Salz einziehen und das Fleisch würzen kann. Nimm sie 15 Minuten vor dem Panieren heraus, damit sie nicht eiskalt ins Fett kommen, denn sonst kühlt es zu stark ab. Wer mag, gibt etwas Pfeffer oder einen Spritzer Zitronensaft dazu.","dauer":30,"tipp":""},{"titel":"Panieren","aktion":"panieren","text":"Wende jedes Hendlviertel zuerst in Mehl, klopfe das überschüssige Mehl ab und ziehe es dann durch die mit Öl verquirlten Eier. Lasse das überschüssige Ei abtropfen und wälze das Fleisch locker in den Semmelbröseln. Drücke die Brösel nicht an, damit die Panade sich später aufbläht und knusprig bleibt. Lege die panierten Stücke nebeneinander auf einen Teller und paniere erst kurz vor dem Backen, damit die Panade nicht aufweicht.","dauer":10,"tipp":""},{"titel":"Fett erhitzen","aktion":"vorbereiten","text":"Erhitze das Butterschmalz in einer hohen Pfanne oder in der Fritteuse, bis es 150 °C erreicht, und fülle so viel Fett ein, dass die Stücke zur Hälfte bis ganz darin schwimmen können, also 3–4 cm. Die Temperatur ist wichtig: Ist das Fett zu heiß, wird die Panade außen dunkel, bevor das Fleisch gar ist; ist es zu kalt, saugt die Panade Fett. Ein Thermometer hilft, sonst taucht ein Holzlöffelstiel hinein, an dem sofort kleine Bläschen aufsteigen sollen. Heize den Ofen auf 80 °C zum Warmhalten vor.","dauer":8,"tipp":""},{"titel":"Backhendl ausbacken – erste Seite","aktion":"frittieren","text":"Lege zuerst die Keulen und dann die Brüste mit der Hautseite nach unten vorsichtig ins Fett, ohne die Pfanne zu überfüllen – höchstens 3–4 Stücke gleichzeitig, denn sonst sinkt die Fetttemperatur. Backe sie 6 Minuten, während du die Pfanne sanft schwenkst und das Fett über die Oberseite schöpfst. Die Panade bläht sich auf, wird hellgolden und knistert. Halte die Temperatur zwischen 140 und 150 °C und reguliere die Hitze entsprechend.","dauer":6,"tipp":""},{"titel":"Wenden und fertigbacken","aktion":"frittieren","text":"Wende die Stücke vorsichtig mit einer Zange und backe sie weitere 6–8 Minuten, bis die Panade rundum goldbraun ist. Der Saft muss klar austreten, wenn du die dickste Stelle einsticht, und ein Thermometer sollte in der Brust mindestens 75 °C und in der Keule 80–82 °C anzeigen. Das Fleisch darf nicht mehr rosa sein. Dicke Keulen brauchen oft 2–3 Minuten länger als Brüste, nimm diese dann zuerst heraus.","dauer":8,"tipp":""},{"titel":"Abtropfen lassen","aktion":"ruhen","text":"Hebe die fertigen Stücke mit der Schaumkelle aus dem Fett, lasse sie kurz abtropfen und lege sie auf Küchenpapier. Tupfe nur leicht ab und salze sie sofort mit feinem Salz. Stelle sie im vorgeheizten Ofen bei 80 °C warm, ohne sie abzudecken, damit die Panade knusprig bleibt. Wenn du in Etappen arbeitest, filtere zwischendurch Panadereste aus dem Fett, damit es nicht bitter wird.","dauer":3,"tipp":""},{"titel":"Petersilie frittieren","aktion":"frittieren","text":"Gib die trockenen Petersilienzweige 10–15 Sekunden in das heiße Fett, bis sie grün und knusprig sind und das Zischen nachlässt. Hebe sie mit der Schaumkelle heraus und lasse sie abtropfen. Sie schmecken salzig und leicht nussig und sind in Wien die klassische Garnitur. Zu lange frittiert werden sie braun und bitter. Achte darauf, dass die Zweige wirklich trocken sind, sonst spritzt das Fett heftig.","dauer":1,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte die Backhendlstücke auf vorgewärmten Tellern mit Zitronenspalten, den frittierten Petersilienbüscheln und einem Häufchen lauwarmem Erdäpfelsalat oder grünem Salat an. Beträufle das Fleisch erst am Tisch mit Zitrone, damit die Panade knusprig bleibt und nicht aufweicht. Serviere sofort, denn innerhalb weniger Minuten ist die Panade am knusprigsten: Beim Anschneiden soll sie hörbar knacken und das Fleisch saftig dampfen. In Wien isst man das Backhendl traditionell mit den Fingern, ein Finger-Schälchen mit Zitronenwasser steht dann bereit.","dauer":0,"tipp":""}],"profitipps":["Fetttemperatur bei 140–150 °C halten, damit das Fleisch gar wird, bevor die Panade zu dunkel wird.","Hendl viertel statt ganz backen – das verkürzt die Garzeit und macht sie gleichmäßiger.","Brösel nicht festdrücken, dann bläht sich die Panade wie beim Schnitzel auf.","Nicht zu viele Stücke gleichzeitig ins Fett geben.","Immer mit Thermometer prüfen: Brust 75 °C, Keule 80–82 °C."],"varianten":["Backhendl mit entbeinter Brust (Hendlschnitzel)","Gebackene Hühnerleber","Backhuhn mit Sesam-Panade","Wiener Backfisch im selben Verfahren"],"beilagen":["Lauwarmer Erdäpfelsalat","Grüner Salat mit Kernöl","Zitronenspalten","Preiselbeeren"],"getraenk":"Grüner Veltliner, Welschriesling oder ein kühles Bier","koeche":[{"name":"Ewald Plachutta","bezug":"Ein Rezept für Backhuhn (zerteiltes Huhn, Ausbacken in 3–4 cm Fett bei 140–150 °C, Wenden nach etwa 6 Minuten) wird mit dem Wiener Gastronomen Plachutta und seinem Buch „Meine Wiener Küche“ in Verbindung gebracht.","quelle":"https://www.news.at/news/rezepte-plachutta"}],"quellen":[{"titel":"Backhendl – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Backhendl"},{"titel":"Plachutta-Rezepte (Backhuhn, Erdäpfelsalat, Frittaten) – news.at","url":"https://www.news.at/news/rezepte-plachutta"},{"titel":"Plachutta: Meine Wiener Küche – news.at","url":"https://www.news.at/a/rezepte-gourmetkochs-plachutta-die-wiener-kueche-223999"},{"titel":"TasteAtlas – Austrian dishes ranking","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"haehnchen","farben":["#d9a03f","#f0cf84","#e8d9b6"],"schlagworte":["Wiener Küche","Frittiert","Klassiker"],"vegetarisch_moeglich":false},{"id":"oesterreich-salzburger-nockerl","name":"Salzburger Nockerl","originalname":"Salzburger Nockerl","kueche":"oesterreich","region":"Salzburg","beliebtheit":76,"hauptkategorie":"suess","gang":"dessert","kurz":"Luftig-süßes Soufflé aus Eischnee in drei Bergen – außen leicht goldbraun, innen cremig und locker.","hintergrund":"Die Salzburger Nockerl sind eine Spezialität der Stadt Salzburg. Der Legende nach soll der Fürsterzbischof Wolf Dietrich von Raitenau sie von seiner Geliebten Salome Alt gekostet haben; Kulturhistoriker bezweifeln diese Herkunft, da der nötige Ofen erst im frühen 19. Jahrhundert verbreitet war. Traditionell werden drei Nockerl geformt, die an die schneebedeckten Salzburger Berge erinnern sollen. Sie werden in einer heißen, mit Butter und Obers vorbereiteten Form gebacken, sind innen cremig und müssen sofort serviert werden. Wegen ihres Volumens teilen sich meist mehrere Personen eine Portion nach einem Menü.","portionen":4,"zeit":{"vorbereitung":20,"garen":12,"ruhen":0},"schwierigkeit":3,"zutaten":[{"gruppe":"Für die Nockerl","liste":[{"menge":6,"einheit":"Stück","name":"Eiweiß (Größe M)","hinweis":"Zimmertemperatur, ohne jede Spur Eigelb"},{"menge":4,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":80,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Vanillezucker","hinweis":""},{"menge":1,"einheit":"EL","name":"Rum","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":60,"einheit":"g","name":"griffiges Mehl (Type 550)","hinweis":"gesiebt"}]},{"gruppe":"Für die Form","liste":[{"menge":30,"einheit":"g","name":"Butter","hinweis":""},{"menge":50,"einheit":"ml","name":"Obers (Sahne)","hinweis":""},{"menge":null,"einheit":"","name":"Puderzucker zum Bestäuben","hinweis":""}]}],"ausruestung":["Ovale, ofenfeste Form (ca. 28 cm)","Sauberer, fettfreier Rührkessel und Mixer","Teigschaber oder Palette","Sieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Heize den Backofen auf 190 °C Ober-/Unterhitze (170 °C Umluft) vor und schiebe das Rost in die Mitte. Trenne die Eier sehr sorgfältig: Auch ein Tropfen Eigelb im Eiweiß verhindert, dass es steif wird. Wiege Zucker und Mehl ab und siebe das Mehl. Alle Zutaten sollen Zimmertemperatur haben, damit das Eiweiß besser aufschäumt. Stelle die Form bereit, denn sobald der Teig fertig ist, muss alles schnell gehen.","dauer":10,"tipp":""},{"titel":"Form vorbereiten","aktion":"vorbereiten","text":"Fette die ovale, ofenfeste Form großzügig mit Butter ein, gieße den Obers hinein und erwärme die Form kurz auf dem Herd bei mittlerer Hitze, bis die Butter geschmolzen und der Obers heiß ist und leise brutzelt. Die Form muss heiß sein, wenn der Teig hineinkommt, damit die Nockerl sofort Hitze von unten bekommen, aufgehen und nicht festkleben. Der Obers bildet unter den Nockerl eine cremige Sauce, die sich später mit dem Soufflé verbindet. Stelle die Form bereit, bis der Teig fertig ist.","dauer":3,"tipp":""},{"titel":"Eischnee schlagen","aktion":"aufschlagen","text":"Schlage das Eiweiß mit der Prise Salz in einer absolut fettfreien Schüssel zunächst langsam an und steigere die Geschwindigkeit, bis es Spitzen bildet. Lasse dann den Zucker nach und nach einrieseln und schlage so lange weiter, bis der Schnee steif, glänzend und standfest ist. Er soll nicht trocken oder körnig aussehen; wenn er beginnt, sich zu verlieren, ist er überschlagen. Die Schüssel kannst du umdrehen, ohne dass etwas herausfällt.","dauer":5,"tipp":""},{"titel":"Eigelb und Aromen unterheben","aktion":"mischen","text":"Verrühre das Eigelb mit Vanillezucker und Rum in einer kleinen Schüssel kurz glatt. Hebe es mit einem Teigschaber rasch und sanft unter den Eischnee, mit nur wenigen Zügen von unten nach oben, damit möglichst wenig Luft verloren geht. Es dürfen noch einige weiße Eischneeinseln sichtbar sein, denn sie verschwinden beim Unterheben des Mehls. Die Masse soll cremig-hellgelb, sehr luftig und leicht glänzend sein und stark nach Vanille und Rum duften.","dauer":2,"tipp":""},{"titel":"Mehl unterziehen und Nockerl formen","aktion":"formen","text":"Siebe das Mehl über die Eischnee-Masse und ziehe es mit dem Schneebesen kurz und behutsam unter, nur bis kein Mehl mehr sichtbar ist. Forme mit einem Teigschaber oder einer Palette in der heißen Form drei große Berge, die oben spitz zulaufen und sich in der Form berühren. Arbeite zügig und verdichte die Masse nicht. Die Nockerl sollen hoch und luftig stehen und wirken wie Schneeberge.","dauer":3,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Schiebe die Form sofort in den Ofen und backe die Nockerl 10–12 Minuten, bis sie leicht goldbraun sind, aber innen noch cremig-feucht bleiben. Öffne den Ofen während der ersten 8 Minuten nicht, denn sonst fallen sie zusammen. Sie sind fertig, wenn die Spitzen eine zarte, goldgelbe Farbe haben und die Oberfläche fest, aber noch weich federnd ist. Zu langes Backen macht sie trocken wie ein Biskuit.","dauer":12,"tipp":""},{"titel":"Bestäuben und servieren","aktion":"anrichten","text":"Nimm die Form vorsichtig aus dem Ofen und bestäube die Nockerl leicht mit Puderzucker; nicht zu viel, damit das Gold der Kruste sichtbar bleibt. Trage die Form sofort zu Tisch, denn die Nockerl fallen innerhalb weniger Minuten zusammen. Stich mit einem Löffel hinein: Innen sind sie luftig-cremig wie ein warmes Soufflé, außen leicht knusprig. Die Portion reicht für mehrere Personen als Abschluss eines Menüs.","dauer":0,"tipp":""}],"profitipps":["Eiweiß fettfrei und bei Zimmertemperatur schlagen, niemals überschlagen.","Mehl nur ganz kurz unterheben, sonst verliert der Eischnee Luft.","Form vorheizen, damit die Nockerl sofort aufgehen.","Nach dem Backen nicht warten – Salzburger Nockerl sind ein Gericht, das sofort serviert werden muss.","Ofentür in den ersten 8 Minuten geschlossen halten."],"varianten":["Mit Preiselbeeren am Boden der Form","Mit Vanillesauce","Mit Marillenröster","Kleine Einzelportionen in Förmchen"],"beilagen":["Preiselbeeren","Vanillesauce","Beerenkompott"],"getraenk":"Prädikatswein (Beerenauslese) oder Kaffee","koeche":[],"quellen":[{"titel":"Salzburger Nockerln – bmluk.gv.at (Traditionelle Lebensmittel)","url":"https://www.bmluk.gv.at/themen/lebensmittel/trad-lebensmittel/speisen/salzburger_nockerln.html"},{"titel":"Austrian cuisine – Wikipedia","url":"https://en.wikipedia.org/wiki/Austrian_cuisine"}],"bild":"auflauf","farben":["#e2b564","#f3dca0","#fbf6e6"],"schlagworte":["Salzburg","Soufflé","Eischnee","Dessert"],"vegetarisch_moeglich":true},{"id":"oesterreich-buchteln-vanillesosse","name":"Buchteln mit Powidl und Vanillesoße","kueche":"oesterreich","region":"Wien, Böhmen","beliebtheit":74,"kurz":"Fluffige Hefeteigbällchen mit Powidlfüllung, in Butter getaucht, goldbraun gebacken und in warmer Vanillesoße serviert.","hintergrund":"Buchteln gelten als böhmische Mehlspeise, die in Wien, Bayern und ganz Österreich heimisch wurde. Gefüllt werden sie mit Powidl (Zwetschgenmus), Mohn, Topfen oder Marillenmarmelade; gebacken werden sie dicht an dicht in einer Form, sodass sie beim Aufgehen zusammenwachsen und man sie „abzupft“. Ein berühmter Ort ist das Wiener Café Hawelka, wo Josefine Hawelka die Buchteln bis zu ihrem Tod 2005 selbst gebacken haben soll. Dazu serviert man warme Vanillesoße.","portionen":6,"zeit":{"vorbereitung":30,"garen":35,"ruhen":100},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Hefeteig (ca. 14 Buchteln)","liste":[{"menge":500,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"oder glattes Mehl"},{"menge":1,"einheit":"Stück","name":"frische Hefe (1 Würfel, 42 g)","hinweis":"oder 1 Pck. Trockenhefe"},{"menge":250,"einheit":"ml","name":"Milch","hinweis":"lauwarm"},{"menge":60,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ei (Größe M)","hinweis":""},{"menge":1,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":80,"einheit":"g","name":"Butter","hinweis":"weich"},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"Schale abgerieben"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Füllung und Backform","liste":[{"menge":200,"einheit":"g","name":"Powidl (Zwetschgenmus)","hinweis":"ersatzweise Pflaumenmus"},{"menge":60,"einheit":"g","name":"Butter","hinweis":"zerlassen, zum Eintauchen und für die Form"},{"menge":2,"einheit":"EL","name":"Staubzucker","hinweis":"zum Bestäuben"}]},{"gruppe":"Für die Vanillesoße","liste":[{"menge":400,"einheit":"ml","name":"Milch","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":""},{"menge":1,"einheit":"EL","name":"Speisestärke","hinweis":""},{"menge":40,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Stück","name":"Vanilleschote","hinweis":""}]}],"ausruestung":["Eckige Auflaufform (ca. 24 x 30 cm)","Küchenmaschine oder Handrührgerät mit Knethaken","Pinsel","Geschirrtuch"],"schritte":[{"titel":"Vorteig ansetzen","aktion":"gehen","text":"Zerbröckle die Hefe in eine Schüssel, gib einen Teelöffel Zucker, die lauwarme Milch und drei Esslöffel Mehl dazu und verrühre alles. Lass die Mischung zugedeckt an einem warmen Ort etwa 15 Minuten stehen, bis sich Bläschen und eine schaumige Oberfläche bilden. Die Milch soll höchstens 35 °C haben, sonst wird die Hefe geschädigt.","dauer":15,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib restliches Mehl, Zucker, Ei, Eigelb, Salz, Zitronenschale und die weiche Butter zum Vorteig. Knete mit der Küchenmaschine zehn Minuten, bis ein glatter, geschmeidiger Teig entsteht, der sich vom Schüsselrand löst und nur noch leicht klebt. Er soll weich sein; wird er zu fest, kommt ein Schuss Milch dazu. Ist er zu nass, nimm etwas Mehl.","dauer":10,"tipp":"Fingerprobe: Eine kleine Teigkugel bildet beim Dehnen ein dünnes, durchscheinendes Häutchen."},{"titel":"Teig gehen lassen","aktion":"gehen","text":"Forme den Teig zu einer Kugel, lege ihn in eine geölte Schüssel und decke ihn mit einem Tuch ab. Lass ihn an einem warmen Ort (ca. 28 °C) 60 bis 75 Minuten gehen, bis er sein Volumen verdoppelt hat. Das erkennst du daran, dass eine in den Teig gedrückte Fingerkuppe langsam wieder zurückfedert. Bei kühler Küche kannst du die Schüssel in den auf 30 °C vorgewärmten, wieder ausgeschalteten Ofen stellen, dann geht der Teig zuverlässig.","dauer":70,"tipp":""},{"titel":"Buchteln formen und füllen","aktion":"formen","text":"Fette die Form mit Butter. Teile den Teig in etwa 14 gleich große Stücke und drücke jedes zu einem flachen Kreis. Gib einen Teelöffel Powidl in die Mitte, schlage den Teig darüber zusammen und verschließe die Naht fest. Tauche jedes Stück kurz in die zerlassene Butter und setze die Buchteln mit der Naht nach unten dicht nebeneinander in die Form.","dauer":20,"tipp":""},{"titel":"Zweite Gare","aktion":"gehen","text":"Decke die Form ab und lass die Buchteln noch 30 Minuten gehen, bis sie sich sichtbar aneinander schmiegen und um etwa die Hälfte aufgegangen sind. Heize währenddessen den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor. Die Gare ist gut, wenn die Oberfläche glatt und leicht gewölbt ist. Mit der Fingerprobe prüfst du: Drückst du leicht auf den Rand eines Buchtelstücks, bleibt eine Delle, die nur langsam wieder verschwindet.","dauer":30,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Schiebe die Form auf die untere Schiene und backe 30 bis 35 Minuten, bis die Oberfläche goldbraun glänzt und die Buchteln beim Anklopfen hohl klingen. Bestreiche sie nach der Hälfte der Zeit mit der restlichen Butter, damit sie eine glänzende, saftige Kruste bekommen. Wird die Oberfläche zu dunkel, decke sie locker mit Backpapier ab.","dauer":35,"tipp":""},{"titel":"Vanillesoße kochen","aktion":"binden","text":"Erhitze die Milch mit dem Mark und der Schote der Vanille. Verrühre Eigelb, Zucker und Stärke, gieße die heiße Milch langsam dazu und erhitze alles unter Rühren bei kleiner Hitze, bis die Soße dicklich wird und den Löffelrücken überzieht. Kurz vor dem Kochen vom Herd nehmen und durch ein Sieb gießen.","dauer":10,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Lass die Buchteln fünf Minuten abkühlen, stäube sie mit Staubzucker ein und löse sie einzeln aus der Form. Serviere sie warm mit reichlich Vanillesoße, die in die weichen Stellen zieht. Am nächsten Tag lassen sie sich kurz aufwärmen, schmecken aber frisch am besten. Dazu passt ein Häferl Milchkaffee, wie es im Wiener Kaffeehaus üblich ist, und wer mag, streut zusätzlich Zimt auf die Soße.","dauer":3,"tipp":""}],"profitipps":["Hefeteig braucht Zeit: lieber länger gehen lassen als zu heiß.","Butter zum Eintauchen macht die Seitenwände weich und saftig.","Powidl nicht zu flüssig – ggf. mit etwas Semmelbrösel andicken.","Nicht zu eng in die Form drücken, sie gehen noch auf.","Fertige Buchteln eingefroren lassen sich im Ofen frisch aufbacken."],"varianten":["Mit Mohn- oder Topfenfüllung","Mit Marillenmarmelade","Mit Nuss-Nougat","Dukatenbuchteln ohne Füllung"],"beilagen":["Vanillesoße","Staubzucker","Zwetschgenröster"],"getraenk":"Wiener Melange oder warme Milch","koeche":[{"name":"Josefine Hawelka","bezug":"Backte die berühmten Buchteln im Wiener Café Hawelka bis zu ihrem Tod 2005 selbst.","quelle":"https://de.wikipedia.org/wiki/Buchteln"}],"quellen":[{"titel":"Buchteln – Wikipedia","url":"https://de.wikipedia.org/wiki/Buchteln"}],"bild":"gebaeck","farben":["#cf9a4a","#6b3a4e","#f4e3c0"],"schlagworte":["Mehlspeise","Hefeteig","Wien","Café Hawelka"],"originalname":"","fleischsorte":"","hauptkategorie":"suess","gang":"dessert","vegetarisch_moeglich":true},{"id":"oesterreich-frittatensuppe","name":"Frittatensuppe","originalname":"Frittatensuppe","kueche":"oesterreich","region":"Österreich","beliebtheit":72,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"suppe","kurz":"Klare, goldene Rindsuppe mit hauchdünnen Pfannkuchenstreifen und frischem Schnittlauch – die Wiener Suppenklassikerin.","hintergrund":"Die Frittatensuppe ist eine klare Rindsuppe mit Streifen aus dünnem Pfannkuchen (Palatschinken) und Schnittlauch. In Österreich, vor allem in Wien, ist sie eine der beliebtesten Suppeneinlagen, in Schwaben heißt sie Flädlesuppe, in der Deutschschweiz Flädlisuppe. Der Name Frittaten leitet sich vom italienischen „frittata“ ab, was gebraten bedeutet. Die Streifen werden erst kurz vor dem Servieren in die heiße Brühe gegeben, damit sie nicht aufweichen. Die Qualität der Suppe entscheidet über das Gericht: Sie soll klar, goldgelb und kräftig sein.","portionen":4,"zeit":{"vorbereitung":30,"garen":150,"ruhen":30},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Rindsuppe","liste":[{"menge":500,"einheit":"g","name":"Rindfleisch zum Kochen (Siedefleisch, z. B. Tafelspitz oder Schulterscherzel)","hinweis":""},{"menge":500,"einheit":"g","name":"Rinderknochen mit etwas Fleisch","hinweis":""},{"menge":250,"einheit":"g","name":"Wurzelgemüse","hinweis":"Karotte, Sellerie, Petersilienwurzel"},{"menge":0.5,"einheit":"Stange","name":"Lauch","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"halbiert, mit Schale geröstet"},{"menge":10,"einheit":"Stück","name":"Pfefferkörner","hinweis":""},{"menge":3,"einheit":"l","name":"kaltes Wasser","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Für die Frittaten","liste":[{"menge":100,"einheit":"g","name":"glattes Mehl (Type 405)","hinweis":""},{"menge":250,"einheit":"ml","name":"Milch","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eier (Größe M)","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"fein gehackte Petersilie","hinweis":"optional"},{"menge":20,"einheit":"g","name":"Butter oder Öl","hinweis":"zum Ausbacken"}]},{"gruppe":"Zum Servieren","liste":[{"menge":1,"einheit":"Bund","name":"Schnittlauch","hinweis":"fein geschnitten"}]}],"ausruestung":["Großer Topf","Feines Sieb und Passiertuch","Beschichtete Pfanne (24 cm)","Schaumkelle","Schneebesen"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Spüle das Fleisch kurz ab, schäle das Wurzelgemüse und wasche den Lauch. Halbiere die Zwiebel mit Schale und röste sie mit der Schnittseite nach unten in einer trockenen Pfanne 8–10 Minuten, bis sie fast schwarz ist; das färbt die Suppe goldbraun und gibt Röstaroma. Wiege Mehl und Milch ab und stelle die Eier bereit. Der Teig soll später 30 Minuten rasten, du kannst ihn also schon während des Kochens vorbereiten.","dauer":15,"tipp":""},{"titel":"Knochen blanchieren und Suppe ansetzen","aktion":"kochen","text":"Gib die Knochen in einen Topf mit kaltem Wasser, bringe es zum Kochen und lasse es 5 Minuten sprudelnd aufwallen. Dabei steigt grauer Schaum aus Blut und Eiweiß auf, der die Suppe später trüben würde. Gieße das Wasser ab, spüle die Knochen kalt ab und setze die Suppe mit 3 l frischem kaltem Wasser, den Knochen, den Pfefferkörnern und der gerösteten Zwiebel neu an. Bringe sie zum Kochen und reduziere die Hitze, bis sie nur noch leise wallt. Schöpfe den Schaum regelmäßig ab.","dauer":10,"tipp":""},{"titel":"Fleisch einlegen und sanft garen","aktion":"koecheln","text":"Lege das Rindfleisch in die kochende Brühe und lasse alles 2–2½ Stunden bei kleinster Hitze ziehen, ohne dass sie sprudelt; so bleibt die Suppe klar und das Fleisch zart. Das Wurzelgemüse und der Lauch kommen erst für die letzten 30–45 Minuten dazu, damit die Suppe nicht zu süß wird. Das Fleisch ist fertig, wenn es sich mit einer Gabel leicht zerteilen lässt. Salze erst zum Schluss nach Geschmack, weil die Suppe beim Ziehen noch an Intensität gewinnt.","dauer":150,"tipp":"Das Fleisch kannst du als Tafelspitz oder für Rindfleischsalat weiterverwenden."},{"titel":"Frittaten-Teig anrühren","aktion":"mischen","text":"Verrühre Mehl, Milch, Eier und Salz mit dem Schneebesen zu einem glatten, dünnflüssigen Teig ohne Klümpchen; arbeite zuerst mit der Hälfte der Milch zu einem glatten Brei und füge den Rest zu. Gib die Petersilie dazu, wenn du magst. Der Teig soll wie flüssige Sahne vom Löffel laufen. Lasse ihn mindestens 20–30 Minuten bei Zimmertemperatur rasten, damit das Mehl quellen kann und die Frittaten zart, gleichmäßig und ohne Gummi-Biss werden.","dauer":30,"tipp":""},{"titel":"Frittaten backen","aktion":"braten","text":"Erhitze etwas Butter oder Öl in der beschichteten Pfanne bei mittlerer Hitze, gieße eine kleine Kelle Teig hinein und schwenke die Pfanne, sodass sich ein hauchdünner Pfannkuchen bildet. Backe ihn 1 Minute, bis die Unterseite hellbraun und die Oberfläche gestockt ist, wende ihn kurz und backe ihn weitere 20 Sekunden. Lege ihn auf einen Teller und wiederhole das mit dem restlichen Teig. Es ergibt etwa 6–8 Pfannkuchen.","dauer":10,"tipp":""},{"titel":"Frittaten schneiden","aktion":"schneiden","text":"Lasse die Pfannkuchen auf einem Teller etwas abkühlen, bis sie nicht mehr dampfen, rolle sie dann fest auf und schneide die Rolle mit einem scharfen Messer in etwa 3–4 mm breite Streifen. Lockere die Streifen mit den Fingern auf, damit sie nicht verkleben. Sie sollen fein und gleichmäßig sein, damit sie gut im Teller verteilt werden. Decke sie mit einem Tuch ab, damit sie nicht austrocknen, und halte sie bis zum Servieren bereit.","dauer":5,"tipp":""},{"titel":"Suppe abseihen","aktion":"abseihen","text":"Nimm Fleisch, Knochen und Gemüse mit einer Schaumkelle aus der Suppe und seihe sie durch ein feines Sieb, am besten zusätzlich durch ein sauberes, feuchtes Tuch. Dadurch wird sie glasklar und goldgelb. Schmecke mit Salz ab und probiere, ob sie kräftig genug ist; wenn nicht, lass sie 10 Minuten leise einkochen. Erhitze die Suppe vor dem Servieren noch einmal kräftig, aber koche sie nicht auf, damit sie klar bleibt und keine Trübung entsteht.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Gib eine kleine Handvoll Frittaten in vorgewärmte Suppenteller oder Tassen und gieße die heiße Suppe darüber. Bestreue sie mit frisch geschnittenem Schnittlauch und serviere sie sofort. Die Frittaten dürfen erst im Teller in die Suppe kommen, sonst weichen sie auf und verlieren ihre zarte Struktur. Die Suppe soll goldgelb, klar und aromatisch nach Rind und Wurzelgemüse duften, und die Streifen sollen weich und leicht elastisch sein.","dauer":0,"tipp":""}],"profitipps":["Suppe bei kleinster Hitze ziehen lassen, nie sprudelnd kochen – das hält sie klar.","Zwiebelhälfte schwarz rösten für Farbe und Aroma.","Frittaten dünn backen und erst im Teller mit Suppe übergießen.","Teig rasten lassen, damit die Frittaten zart werden.","Suppe durch ein Tuch passieren für klare Optik."],"varianten":["Grießnockerlsuppe","Leberknödelsuppe","Flädlesuppe (Schwaben)","Suppe mit Kräuterfrittaten"],"beilagen":["Frisches Brot","Salat"],"getraenk":"Ein Glas Grüner Veltliner oder Mineralwasser","koeche":[{"name":"Ewald Plachutta","bezug":"In einem Artikel zu Plachuttas Buch „Meine Wiener Küche“ werden Rezepte für Rindsuppe und Frittaten (Pfannkuchenstreifen für die Suppe) vorgestellt.","quelle":"https://www.news.at/a/rezepte-gourmetkochs-plachutta-die-wiener-kueche-223999"}],"quellen":[{"titel":"Frittatensuppe – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Frittatensuppe"},{"titel":"Plachutta: Meine Wiener Küche (Rindsuppe, Frittaten) – news.at","url":"https://www.news.at/a/rezepte-gourmetkochs-plachutta-die-wiener-kueche-223999"},{"titel":"Plachutta-Rezepte – news.at","url":"https://www.news.at/news/rezepte-plachutta"}],"bild":"suppe","farben":["#d9a840","#f0d487","#6b8f3a"],"schlagworte":["Wiener Küche","Suppe","Klassiker"],"vegetarisch_moeglich":false},{"id":"oesterreich-topfenknoedel-butterbroesel","name":"Topfenknödel mit Butterbröseln","kueche":"oesterreich","region":"Österreich, Ungarn, Böhmen","beliebtheit":72,"kurz":"Zarte Quarkklöße, in Butter geröstete Semmelbrösel und Zwetschgenröster – eine einfache Mehlspeise, die nach Kindheit schmeckt.","hintergrund":"Topfenknödel gehören in Österreich, Ungarn (Túrógombóc) und Tschechien zu den klassischen Süßspeisen. Der Teig aus Topfen (Quark), Grieß oder Weißbrotbröseln, Ei und Butter wird zu Knödeln geformt, im Wasser gegart und in Butterbröseln gewälzt. Sie werden meist mit Staubzucker und Obstkompott serviert und schmecken locker, leicht säuerlich und angenehm cremig. Anders als Marillenknödel sind sie ungefüllt.","portionen":4,"zeit":{"vorbereitung":25,"garen":15,"ruhen":45},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Knödel (ca. 12 Stück)","liste":[{"menge":500,"einheit":"g","name":"Topfen (Quark)","hinweis":"20 % Fett, gut abgetropft"},{"menge":80,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":2,"einheit":"Stück","name":"Eier (Größe M)","hinweis":""},{"menge":100,"einheit":"g","name":"Weißbrotbrösel","hinweis":"oder Semmelbrösel"},{"menge":50,"einheit":"g","name":"Weichweizengrieß","hinweis":""},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"abgeriebene Schale"},{"menge":1,"einheit":"Pck.","name":"Vanillezucker","hinweis":""}]},{"gruppe":"Für die Butterbrösel","liste":[{"menge":80,"einheit":"g","name":"Butter","hinweis":""},{"menge":100,"einheit":"g","name":"Semmelbrösel","hinweis":""},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":""},{"menge":2,"einheit":"EL","name":"Staubzucker","hinweis":"zum Bestäuben"}]},{"gruppe":"Zum Servieren","liste":[{"menge":300,"einheit":"g","name":"Zwetschgenröster oder Erdbeerkompott","hinweis":"selbst gekocht oder aus dem Glas"}]}],"ausruestung":["Großer Topf","Schaumlöffel","Pfanne","Küchentuch zum Abtropfen"],"schritte":[{"titel":"Topfen abtropfen","aktion":"vorbereiten","text":"Gib den Topfen auf ein sauberes Küchentuch oder in ein feines Sieb und lass ihn eine Viertelstunde abtropfen. Drücke leicht aus, damit überschüssige Molke entweicht, sonst wird der Teig zu weich und die Knödel zerfallen. Stelle Butter, Eier und Brösel bereit und reibe die Zitronenschale ab. Je trockener der Topfen, desto weniger Brösel braucht der Teig und desto zarter werden die Knödel am Ende.","dauer":15,"tipp":""},{"titel":"Teig rühren","aktion":"mischen","text":"Schlage die weiche Butter mit Salz und Vanillezucker in einer Schüssel schaumig, bis sie hell und cremig aussieht. Rühre nacheinander die Eier ein, dann den abgetropften Topfen und die Zitronenschale. Hebe zum Schluss Brösel und Grieß unter. Der Teig soll feucht, aber formbar sein und nicht mehr an der Schüssel haften.","dauer":8,"tipp":""},{"titel":"Teig ruhen lassen","aktion":"kuehlen","text":"Decke die Schüssel ab und stelle sie 30 bis 45 Minuten in den Kühlschrank. Grieß und Brösel quellen in dieser Zeit, sodass der Teig fester wird und sich besser formen lässt. Danach hat die Masse eine feste, leicht klebrige Konsistenz. Bring währenddessen reichlich Salzwasser zum Sieden. Gut gekühlter Teig lässt sich später mit feuchten Händen viel sauberer zu glatten Kugeln rollen und klebt weniger an den Fingern.","dauer":40,"tipp":""},{"titel":"Knödel formen und probieren","aktion":"formen","text":"Befeuchte deine Hände mit kaltem Wasser und forme etwa 12 Knödel in Walnussgröße. Koche zuerst einen Probeknödel: Zerfällt er im Wasser, arbeite etwas mehr Brösel oder Grieß in den Teig ein. Bleibt er stabil, formst du alle weiteren Knödel auf diese Weise. Die Knödel sollen etwa die Größe einer Walnuss bis kleinen Mandarine haben, denn zu große Knödel garen innen nicht gleichmäßig durch und bleiben in der Mitte teigig.","dauer":10,"tipp":"Der Probeknödel erspart dir ein Küchendesaster."},{"titel":"Knödel garen","aktion":"kochen","text":"Lege die Knödel in das leicht siedende, nicht sprudelnde Salzwasser. Lass sie 12 bis 15 Minuten ziehen, bis sie nach oben steigen und sich fest anfühlen. Du erkennst den richtigen Gargrad, wenn sie beim Anstupsen elastisch zurückfedern und leicht aufgebläht wirken. Zu starkes Kochen lässt sie zerfallen.","dauer":15,"tipp":""},{"titel":"Butterbrösel rösten","aktion":"braten","text":"Zerlasse die Butter in der Pfanne bei mittlerer Hitze und röste die Semmelbrösel unter Rühren 4 bis 5 Minuten, bis sie hellbraun sind und nussig duften. Rühre den Zucker unter und nimm die Pfanne vom Herd. Die Brösel sollen knusprig bleiben, nicht matschig. Gib die Brösel erst in die Pfanne, wenn die Butter aufgehört hat zu schäumen, damit sie nicht fettig aufquellen, sondern knusprig bräunen.","dauer":6,"tipp":""},{"titel":"Wälzen und servieren","aktion":"anrichten","text":"Hebe die Knödel mit dem Schaumlöffel aus dem Wasser, lass sie kurz abtropfen und wälze sie in den Butterbröseln. Richte sie mit einem Klecks Zwetschgenröster an und bestäube sie mit Staubzucker. Serviere sofort, solange sie noch warm und zart sind. Ein Hauch Zimt im Zucker der Butterbrösel und ein Löffel Sauerrahm machen das Dessert noch runder und etwas weniger schwer.","dauer":3,"tipp":""}],"profitipps":["Topfen gut abtropfen lassen, dann braucht der Teig weniger Bindemittel.","Immer einen Probeknödel kochen.","Wasser nur leise sieden lassen.","Brösel erst kurz vor dem Servieren rösten, damit sie knusprig bleiben.","Mit etwas Vanillezucker im Teig schmecken sie runder."],"varianten":["Mit Marillen oder Zwetschgen gefüllt","Mit Mohn und Honig","Papanași (Rumänien) – frittiert","Mit Nuss-Bröseln statt Semmelbröseln"],"beilagen":["Zwetschgenröster","Erdbeerkompott","Vanillesoße"],"getraenk":"Milchkaffee oder Apfelsaftschorle","koeche":[],"quellen":[{"titel":"Topfenknödel – Wikipedia","url":"https://de.wikipedia.org/wiki/Topfenknödel"}],"bild":"knoedel","farben":["#f0e2c0","#c78b3b","#6a3a49"],"schlagworte":["Mehlspeise","Quark","Sonntagsessen"],"originalname":"","fleischsorte":"","hauptkategorie":"suess","gang":"dessert","vegetarisch_moeglich":true},{"id":"oesterreich-mohr-im-hemd","name":"Mohr im Hemd (Schoko-Nuss-Pudding)","originalname":"Mohr im Hemd","kueche":"oesterreich","region":"Wien, Kaffeehaus","beliebtheit":72,"kurz":"Lockerer Schokoladen-Nuss-Pudding aus dem Wasserbad, mit heißer Schokosoße übergossen und mit Schlagobers umhüllt – eine Wiener Kaffeehaus-Ikone.","hintergrund":"Der „Mohr im Hemd“ ist eine klassische Wiener Mehlspeise: Ein Schokoladenpudding aus Butter, Eidotter, Schokolade, geriebenen Nüssen und Bröseln wird im Wasserbad gegart, mit heißer Schokoladensoße übergossen und mit Schlagobers (Schlagsahne) umhüllt, dem „Hemd“. Er findet sich in Kaffeehäusern und Gaststätten und ist eng mit der bürgerlichen Wiener Küche verwandt, die viele Dunstköche und Puddings kannte. Der traditionelle Name wird seit den 2000er-Jahren als rassistisch kritisiert; viele Betriebe nennen die Speise inzwischen Schoko-Nuss-Kuchen oder Schokopudding mit Schlag.","portionen":6,"zeit":{"vorbereitung":30,"garen":30,"ruhen":10},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Pudding (6 Förmchen à ca. 150 ml)","liste":[{"menge":100,"einheit":"g","name":"Zartbitterschokolade","hinweis":"mindestens 60 % Kakao"},{"menge":100,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":80,"einheit":"g","name":"Zucker","hinweis":""},{"menge":4,"einheit":"Stück","name":"Eier","hinweis":"getrennt, Größe M"},{"menge":100,"einheit":"g","name":"gemahlene Walnüsse oder Mandeln","hinweis":"fein gemahlen"},{"menge":30,"einheit":"g","name":"Semmelbrösel","hinweis":"oder geriebene Semmeln"},{"menge":1,"einheit":"Prise","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Butter","hinweis":"zum Ausfetten"},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":"zum Ausstreuen der Förmchen"}]},{"gruppe":"Für die Schokosoße und das Hemd","liste":[{"menge":120,"einheit":"g","name":"Zartbitterschokolade","hinweis":""},{"menge":120,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":200,"einheit":"ml","name":"Schlagobers (Schlagsahne)","hinweis":"kalt"},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":"zum Aufschlagen der Sahne"}]}],"ausruestung":["6 Förmchen (Dariolen) oder Tassen","tiefes Backblech für das Wasserbad","Handrührgerät","Topf für die Soße"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor und stelle ein tiefes Blech mit heißem Wasser (etwa 2 cm hoch) auf die untere Schiene. Fette die Förmchen großzügig mit Butter und streue sie mit Zucker aus; überschüssigen Zucker klopfst du aus. Hacke die Schokolade fein und lass sie über einem Wasserbad schmelzen, bis sie glänzend und glatt ist. Nimm sie vom Herd und lass sie leicht abkühlen, sonst gerinnt später die Eiermasse.","dauer":15,"tipp":""},{"titel":"Butter und Eigelb schaumig rühren","aktion":"aufschlagen","text":"Rühre die weiche Butter mit der Hälfte des Zuckers in einer Schüssel etwa fünf Minuten, bis die Masse hell und cremig ist. Gib die Eigelbe einzeln dazu und rühre jedes erst gründlich unter. Die Masse soll aufgehen und heller werden; sie darf nicht gerinnen. Erst danach rührst du die lauwarme, geschmolzene Schokolade ein. Sie muss gleichmäßig dunkel aussehen.","dauer":8,"tipp":""},{"titel":"Nüsse und Brösel unterheben","aktion":"mischen","text":"Mische die gemahlenen Nüsse mit den Semmelbröseln und hebe sie mit einem Teigschaber unter die Schokomasse. Die Masse wird dabei dicker und etwas bröselig. Hebe nur so lange, bis alles verbunden ist, damit die Nüsse nicht überarbeitet werden und die Luftigkeit erhalten bleibt. Sie darf sich nicht schmierig anfühlen.","dauer":3,"tipp":""},{"titel":"Eischnee schlagen und unterheben","aktion":"aufschlagen","text":"Schlage die Eiweiße mit einer Prise Salz steif, lass den restlichen Zucker einrieseln und schlage weiter, bis der Eischnee glänzt und sich Spitzen formen. Hebe zuerst ein Drittel mit dem Schneebesen kräftig unter die Schokomasse, damit sie lockerer wird, dann den Rest vorsichtig in Schleifen mit dem Teigschaber. Der Eischnee darf nicht zusammenfallen, denn er ist das einzige Treibmittel.","dauer":6,"tipp":"Kein Fett an der Schüssel – sonst wird der Eischnee nicht steif."},{"titel":"Füllen und im Wasserbad backen","aktion":"backen","text":"Fülle die Masse bis etwa zwei Drittel der Höhe in die vorbereiteten Förmchen und stelle sie in das heiße Wasserbad im Ofen. Backe die Puddings 25 bis 30 Minuten; sie sind fertig, wenn sie aufgegangen sind und sich leicht federnd anfühlen. Ein Holzstäbchen sollte noch feucht, aber nicht flüssig herauskommen. Das Wasserbad sorgt für sanfte, gleichmäßige Hitze, sodass der Pudding saftig bleibt.","dauer":30,"tipp":""},{"titel":"Schokosoße kochen","aktion":"kochen","text":"Erhitze die Sahne in einem kleinen Topf bis kurz vor dem Kochen, nimm sie vom Herd und rühre die gehackte Schokolade ein, bis sie sich vollständig aufgelöst hat und die Soße glänzend und seidig ist. Halte die Soße warm. Wenn sie zu dick ist, verdünne sie mit einem Löffel Milch oder warmem Wasser; sie soll dickflüssig vom Löffel laufen.","dauer":8,"tipp":""},{"titel":"Stürzen, übergießen und anrichten","aktion":"anrichten","text":"Löse die Puddings mit einem dünnen Messer vom Rand, lasse sie kurz abkühlen und stürze sie vorsichtig auf Teller. Übergieße sie großzügig mit der heißen Schokosoße. Schlage die kalte Sahne mit dem Zucker steif und setze sie als weiche Haube auf die Puddings, sodass sie wie in einem Hemd stecken. Serviere sofort: Die Wärme des Puddings und die kühle Sahne sind der Reiz dieser Speise.","dauer":8,"tipp":""}],"profitipps":["Mit einem Wasserbad im Ofen gart der Pudding gleichmäßig und bleibt saftig.","Förmchen sehr gut buttern und zuckern, sonst haftet der Pudding.","Eischnee zuerst kräftig, dann vorsichtig unterheben.","Schokolade vor dem Einrühren abkühlen lassen.","Die Soße erst kurz vor dem Servieren erhitzen."],"varianten":["Mit Rotwein in der Masse (traditionell)","Mit Mandeln statt Walnüssen","Eismohr im Hemd mit Vanilleeis","Mit Orangenschale oder Rum in der Soße"],"beilagen":["Schlagobers","Schokosoße","Preiselbeeren"],"getraenk":"Wiener Melange, Einspänner oder ein Glas Rotwein","koeche":[],"quellen":[{"titel":"Mohr im Hemd – Wikipedia","url":"https://de.wikipedia.org/wiki/Mohr_im_Hemd"},{"titel":"Pudding – Wikipedia","url":"https://de.wikipedia.org/wiki/Pudding"},{"titel":"Dessert „Mohr im Hemd“ – Für Sie","url":"https://www.fuersie.de/kochen/rezeptideen/artikel/rezept-fuer-dessert-mohr-im-hemd"}],"bild":"dessert","farben":["#3f2216","#6b3a24","#f6efe2"],"schlagworte":["Wien","Kaffeehaus","Schokolade","Mehlspeise"],"vegetarisch_moeglich":true,"fleischsorte":"","hauptkategorie":"suess","gang":"dessert"},{"id":"oesterreich-topfenpalatschinken-witzigmann","name":"Überbackene Topfenpalatschinken nach Art von Eckart Witzigmann","originalname":"Topfenpalatschinken","kueche":"oesterreich","region":"Wien","beliebtheit":72,"hauptkategorie":"suess","gang":"dessert","kurz":"Hauchdünne Palatschinken mit luftiger Topfen-Rosinen-Füllung, im Rahmguss goldbraun überbacken.","hintergrund":"Eckart Witzigmann hat gemeinsam mit Ewald Plachutta die „Kochschule“ (2007; „Die Bibel der guten Küche“, 496 Seiten) und 2009 deren zweiten Teil geschrieben – eine Sammlung klassischer österreichischer Alltagsküche. Welche Rezepte darin stehen, habe ich nicht gesehen; Topfenpalatschinken gehören aber zu den Standards der Wiener Küche und sind deshalb eine naheliegende Wahl. Dies ist eine Heimküchen-Fassung nach klassischer Technik, nicht sein Rezept. Topfen ist österreichisch für Quark; hier am besten fein passiert.","portionen":4,"zeit":{"vorbereitung":40,"garen":35,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Palatschinken","liste":[{"menge":150,"einheit":"g","name":"Mehl","hinweis":"Type 405"},{"menge":300,"einheit":"ml","name":"Milch"},{"menge":2,"einheit":"Stück","name":"Eier"},{"menge":1,"einheit":"EL","name":"Zucker"},{"menge":1,"einheit":"Prise","name":"Salz"},{"menge":1,"einheit":"TL","name":"Vanillezucker"},{"menge":20,"einheit":"g","name":"Butter","hinweis":"zerlassen und leicht abgekühlt"},{"menge":2,"einheit":"EL","name":"Butterschmalz","hinweis":"zum Ausbacken"}]},{"gruppe":"Für die Topfenfüllung","liste":[{"menge":400,"einheit":"g","name":"Topfen (Quark) 20 % Fett","hinweis":"gut abgetropft"},{"menge":2,"einheit":"Stück","name":"Eigelb"},{"menge":2,"einheit":"Stück","name":"Eiweiß"},{"menge":60,"einheit":"g","name":"Zucker"},{"menge":1,"einheit":"TL","name":"Vanillezucker"},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"nur Schale, fein abgerieben"},{"menge":50,"einheit":"g","name":"Rosinen"},{"menge":3,"einheit":"EL","name":"Rum","hinweis":"zum Einlegen; alternativ Apfelsaft"},{"menge":1,"einheit":"EL","name":"Grieß"}]},{"gruppe":"Für den Guss und zum Backen","liste":[{"menge":150,"einheit":"g","name":"Sauerrahm"},{"menge":100,"einheit":"ml","name":"Milch"},{"menge":1,"einheit":"Stück","name":"Ei"},{"menge":25,"einheit":"g","name":"Zucker"},{"menge":15,"einheit":"g","name":"Butter","hinweis":"für die Form"},{"menge":null,"einheit":"","name":"Staubzucker","hinweis":"zum Bestäuben"}]}],"ausruestung":["beschichtete Pfanne (ca. 22 cm)","Schneebesen","Sieb","Auflaufform (ca. 24 × 30 cm)","Küchentuch zum Abtropfen"],"schritte":[{"titel":"Rosinen einlegen und Quark abtropfen","aktion":"vorbereiten","text":"Lege die Rosinen mit dem Rum in eine kleine Schüssel und lasse sie mindestens 20 Minuten ziehen, bis sie aufgequollen sind und süßlich nach Rum duften. Gib den Topfen in ein sauberes Tuch oder ein feines Sieb und lasse ihn abtropfen; ist er sehr feucht, presse ihn leicht aus. Streiche ihn dann durch ein Sieb, damit er seidig glatt wird. Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor und fette die Form mit Butter ein.","dauer":25,"tipp":"Trockener Topfen macht die Füllung stabil statt wässrig."},{"titel":"Palatschinkenteig","aktion":"mischen","text":"Verrühre Mehl, Zucker, Salz und Vanillezucker in einer Schüssel. Verquirle Eier und Milch, gieße die Mischung nach und nach zum Mehl und rühre mit dem Schneebesen glatt; der Teig soll dünnflüssig wie Sahne sein und keine Klümpchen enthalten. Rühre die zerlassene Butter unter. Lasse den Teig 20 Minuten quellen, damit die Palatschinken zart werden und beim Wenden nicht reißen. Wenn er zu dick ist, gib einen Schuss Milch dazu.","dauer":20,"tipp":"Ruhezeit macht den Teig geschmeidig."},{"titel":"Palatschinken backen","aktion":"braten","text":"Erhitze eine beschichtete Pfanne und fette sie mit wenig Butterschmalz. Gieße eine kleine Kelle Teig hinein und schwenke die Pfanne, bis er den Boden hauchdünn bedeckt. Backe 1 Minute bei mittlerer Hitze, bis der Rand goldbraun ist und sich löst, wende dann und backe die andere Seite 30 Sekunden. Lege die fertigen Palatschinken übereinander auf einen Teller. Du erhältst etwa 8 Stück; wenn sie reißen, war die Pfanne zu heiß oder der Teig zu dick.","dauer":20,"tipp":"Die erste Palatschinke ist oft Probe – nicht ärgern."},{"titel":"Topfenfüllung zubereiten","aktion":"mischen","text":"Verrühre Topfen, Eigelb, Zucker, Vanillezucker, Zitronenschale und Grieß zu einer glatten Creme. Rühre die abgetropften Rosinen unter. Schlage die Eiweiße mit einer Prise Salz zu steifem Schnee und hebe ihn vorsichtig mit einem Spatel unter die Topfenmasse, damit sie luftig bleibt. Die Füllung soll cremig, aber formbar sein. Probiere sie: Sie darf deutlich süß-zitronig schmecken.","dauer":8,"tipp":"Eischnee vorsichtig unterheben – sonst fällt die Luftigkeit zusammen."},{"titel":"Füllen und aufrollen","aktion":"fuellen","text":"Lege die Palatschinken einzeln aus, streiche etwa 2 Esslöffel Füllung auf die untere Hälfte und schlage die Seiten ein; rolle sie dann zu einer Zigarre. Alternativ faltest du sie zu Dreiecken. Schichte sie mit der Naht nach unten dicht an dicht in die Form. Das Füllen geht leichter, wenn die Palatschinken noch leicht warm sind; kalte brechen. Sie sollten die Form gut füllen.","dauer":10,"tipp":""},{"titel":"Guss anrühren und backen","aktion":"backen","text":"Verrühre Sauerrahm, Milch, Ei und Zucker glatt und gieße den Guss gleichmäßig über die Palatschinken. Schiebe die Form in die Mitte des Ofens und backe 20 bis 25 Minuten, bis der Guss gestockt und die Oberfläche goldbraun ist und die Füllung aufgegangen schimmert. Die Füllung soll beim Anstechen heiß sein, aber nicht trocken. Wenn die Oberfläche zu schnell bräunt, decke sie locker mit Folie ab.","dauer":25,"tipp":"Guss nicht zu hoch einfüllen – sonst weichen die Palatschinken auf."},{"titel":"Anrichten","aktion":"anrichten","text":"Lasse die Form 5 Minuten stehen, damit der Guss fest wird, und hebe die Palatschinken mit einem breiten Spatel auf die Teller. Bestäube sie großzügig mit Staubzucker und serviere sie warm. Dazu passt ein Fruchtmus aus Marillen oder Beeren oder eine Vanillesauce. Reste schmecken auch kalt oder noch einmal kurz aufgewärmt. Nicht lange stehen lassen, denn der Guss zieht sonst in die Palatschinken.","dauer":5,"tipp":""}],"profitipps":["Teig ruhen lassen – Palatschinken werden zarter.","Topfen gut abtropfen und passieren.","Eischnee vorsichtig unterheben.","Die Pfanne nur hauchdünn fetten.","Rosinen in Rum einlegen, für Kinder in Apfelsaft."],"varianten":["Mit Marillenmarmelade bestrichen.","Mit Beeren in der Füllung.","Ohne Guss gebraten, nur mit Staubzucker.","Mit Mohn in der Füllung."],"beilagen":["Marillen- oder Beerenkompott","Vanillesauce","Schlagobers"],"getraenk":"Edelsüßer Wein (Beerenauslese) oder Kaffee","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann und Ewald Plachutta sind Autoren der „Kochschule“ (2007; laut Verlagstext „Die Bibel der guten Küche“) und von deren Fortsetzung (2009). Ob ein Topfenpalatschinken-Rezept darin steht, habe ich nicht geprüft; dies ist eine klassische Wiener Heimküchen-Fassung, nicht sein Rezept.","quelle":"https://www.ebay.de/p/4240127"}],"quellen":[{"titel":"Witzigmann – Plachutta Kochschule (2007) – Buchbeschreibung","url":"https://www.ebay.de/p/4240127"},{"titel":"Topfenpalatschinken – Wien.info (klassische Wiener Fassung)","url":"https://www.wien.info/de/einkaufen-essen-trinken/wiener-kueche/rezepte/topfenpalatschinken-361692"},{"titel":"Ewald Plachutta – Wikipedia (Kochschule, Witzigmann als Co-Autor)","url":"https://de.wikipedia.org/wiki/Ewald_Plachutta"}],"bild":"pfannkuchen","farben":["#e8c36a","#f6e7b8","#d9944a"],"schlagworte":["Wiener Küche","Topfen","Dessert"],"vegetarisch_moeglich":true},{"id":"oesterreich-kaerntner-kasnudeln","name":"Kärntner Kasnudeln","originalname":"Kärntner Kasnudeln","kueche":"oesterreich","region":"Kärnten","beliebtheit":68,"hauptkategorie":"vegetarisch","gang":"hauptgericht","kurz":"Handgemachte Teigtaschen mit Topfen-Kartoffel-Minze-Füllung, mit dem typischen Zopfrand verschlossen und in brauner Butter geschwenkt.","hintergrund":"Kärntner Kasnudeln sind eine Spezialität Kärntens und ein Gericht mit hohem Festtagscharakter. Der dünn ausgerollte Nudelteig wird mit einer Füllung aus Topfen (Quark), Kartoffeln, Minze und Kerbel gefüllt und am Rand mit einem kunstvollen Zopfmuster, dem „Krendeln“, verschlossen. Dann werden sie gekocht und mit brauner Butter und Schnittlauch serviert, dazu gibt es meist grünen Salat. In Kärnten wird das Krendeln von Generation zu Generation weitergegeben. Die frische Minze ist das typische Aroma der Füllung.","portionen":4,"zeit":{"vorbereitung":60,"garen":15,"ruhen":30},"schwierigkeit":3,"zutaten":[{"gruppe":"Für den Nudelteig","liste":[{"menge":300,"einheit":"g","name":"Mehl (glatt, Type 405)","hinweis":"plus Mehl zum Arbeiten"},{"menge":1,"einheit":"Stück","name":"Ei (Größe M)","hinweis":""},{"menge":100,"einheit":"ml","name":"lauwarmes Wasser","hinweis":""},{"menge":2,"einheit":"EL","name":"Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Für die Füllung","liste":[{"menge":250,"einheit":"g","name":"trockener Topfen (Magerquark)","hinweis":"gut ausgepresst; ersatzweise körniger Frischkäse abgetropft"},{"menge":250,"einheit":"g","name":"mehlige Kartoffeln","hinweis":"gekocht und heiß gepresst"},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel","hinweis":"fein gewürfelt"},{"menge":20,"einheit":"g","name":"Butter","hinweis":""},{"menge":0.5,"einheit":"Bund","name":"frische Minze","hinweis":"fein gehackt; Nanaminze oder Pfefferminze"},{"menge":2,"einheit":"EL","name":"Kerbel oder Petersilie","hinweis":"gehackt"},{"menge":null,"einheit":"","name":"Salz, Pfeffer, Muskat","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":80,"einheit":"g","name":"Butter","hinweis":"zum Bräunen"},{"menge":1,"einheit":"EL","name":"Schnittlauch","hinweis":""},{"menge":null,"einheit":"","name":"Grüner Salat","hinweis":""}]}],"ausruestung":["Nudelholz oder Nudelmaschine","Runder Ausstecher (8 cm)","Großer Topf","Schaumkelle","Kartoffelpresse","Pfanne"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Koche die Kartoffeln für die Füllung in der Schale gar, pelle sie noch heiß und lasse sie abkühlen. Wiege Mehl und alle Zutaten ab und hacke Minze und Kerbel fein. Presse den Topfen in einem sauberen Tuch aus, bis er fast krümelig trocken ist, denn eine feuchte Füllung lässt die Teigtaschen beim Kochen platzen. Stelle einen großen Topf mit Wasser bereit und bestäube die Arbeitsfläche mit Mehl. Alles sollte griffbereit sein, denn das Formen der Nudeln braucht Ruhe.","dauer":15,"tipp":""},{"titel":"Nudelteig kneten","aktion":"kneten","text":"Verknete Mehl, Ei, Wasser, Öl und Salz in einer Schüssel zuerst mit den Händen, dann auf der Arbeitsfläche 8–10 Minuten, bis ein glatter, fester und geschmeidiger Teig entsteht, der nicht mehr klebt. Er soll sich anfühlen wie ein Ohrläppchen. Ist er zu trocken, gib einen Teelöffel Wasser dazu, ist er zu weich, etwas Mehl. Das Kneten entwickelt das Klebergerüst, das später das dünne Ausrollen ermöglicht.","dauer":10,"tipp":""},{"titel":"Teig rasten","aktion":"ruhen","text":"Wickle den Teig in Folie und lasse ihn mindestens 30 Minuten bei Zimmertemperatur ruhen. In dieser Zeit entspannt sich das Klebergerüst, und der Teig lässt sich später sehr dünn ausrollen, ohne zurückzuschnellen. Nach der Ruhe fühlt er sich glatter, weicher und geschmeidiger an. Du kannst ihn auch über Nacht im Kühlschrank rasten lassen, musst ihn dann aber 30 Minuten vor der Verarbeitung herausnehmen, damit er sich wieder ausrollen lässt.","dauer":30,"tipp":""},{"titel":"Füllung zubereiten","aktion":"mischen","text":"Röste die Zwiebelwürfel in der Butter bei mittlerer Hitze glasig, ohne Farbe zu nehmen. Presse die gekochten Kartoffeln durch die Presse in eine Schüssel, gib den ausgepressten Topfen, die Zwiebeln, Minze, Kerbel, Salz, Pfeffer und etwas Muskat dazu. Verknete alles zu einer glatten, formbaren Masse, die nicht klebt, und schmecke kräftig ab, denn der Nudelteig nimmt Geschmack weg. Die Füllung soll frisch nach Minze duften und sich zu Kugeln formen lassen.","dauer":10,"tipp":""},{"titel":"Teig ausrollen und ausstechen","aktion":"ausrollen","text":"Rolle den Teig portionsweise auf einer bemehlten Fläche so dünn wie möglich aus, etwa 1–2 mm, bis du die Arbeitsfläche durch ihn hindurch erahnen kannst. Steche mit einem runden Ausstecher Kreise von etwa 8 cm Durchmesser aus. Bedecke die Kreise und die restliche Teigmenge mit einem feuchten Tuch, damit sie nicht antrocknen. Die Teigreste kannst du kurz zusammenkneten und erneut ausrollen.","dauer":10,"tipp":""},{"titel":"Füllen","aktion":"fuellen","text":"Setze auf jeden Teigkreis etwa einen gehäuften Teelöffel Füllung genau in die Mitte und lasse den Rand frei. Befeuchte den Rand mit dem Finger und etwas Wasser, damit er später sicher klebt. Zu viel Füllung lässt die Teigtaschen beim Kochen aufreißen, zu wenig macht sie hohl und fade; die Füllung sollte nur den halben Kreis bedecken, wenn du ihn zusammenklappst. Arbeite mit wenigen Kreisen gleichzeitig und halte die übrigen abgedeckt, denn der dünne Teig trocknet schnell aus.","dauer":10,"tipp":""},{"titel":"Krendeln und verschließen","aktion":"formen","text":"Klappe den Teigkreis zu einem Halbmond zusammen und drücke die Ränder fest an, ohne Luft einzuschließen. Falte nun den Rand mit Daumen und Zeigefinger in kleinen Falten nach innen, sodass ein gezopftes Muster entsteht – das Krendeln. Beginne an einem Ende, drücke jede Falte leicht an und arbeite dich gleichmäßig bis zum anderen Ende vor. Der Verschluss muss rundum dicht sein, sonst quillt die Füllung beim Kochen aus.","dauer":15,"tipp":"Das Krendeln braucht Übung; die ersten Nudeln werden nicht perfekt, schmecken aber genauso."},{"titel":"Kochen","aktion":"kochen","text":"Bringe reichlich Salzwasser zum Sieden und reduziere die Hitze auf leises Köcheln. Gib die Kasnudeln portionsweise hinein und lasse sie 8–10 Minuten garen. Sie steigen nach einigen Minuten an die Oberfläche; sie sind fertig, wenn der Teig weich, glänzend und durchscheinend ist. Hebe sie mit der Schaumkelle heraus und lasse sie gut abtropfen. Zu starkes Kochen reißt die Ränder auf.","dauer":10,"tipp":""},{"titel":"Butter bräunen und anrichten","aktion":"braten","text":"Zerlasse die Butter in einer Pfanne bei mittlerer Hitze und lasse sie 3–4 Minuten bräunen, bis sie nussig duftet und goldbraun ist; rühre sie nicht, aber schwenke die Pfanne. Gib die abgetropften Kasnudeln hinein und schwenke sie kurz in der Butter. Verteile sie auf vorgewärmten Tellern, bestreue sie mit Schnittlauch und serviere sie mit grünem Salat. Die braune Butter verbindet sich mit der cremigen Füllung zu einem kräftig-nussigen Geschmack, der für Kärntner Kasnudeln typisch ist.","dauer":5,"tipp":""}],"profitipps":["Füllung nicht zu feucht – sonst platzen die Nudeln.","Teig sehr dünn ausrollen, damit er zart bleibt und gut durchgart.","Rand mit Wasser befeuchten, damit er sicher klebt.","Nur sanft sieden, nicht sprudelnd kochen.","Frische Minze ist das Aroma der Kasnudeln – nicht ersetzen."],"varianten":["Mit Kartoffel-Topfen-Füllung ohne Minze","Schlutzkrapfen (Südtirol) mit Spinat-Füllung","Süße Kasnudeln mit Zimtzucker","Mit Röstzwiebeln statt Schnittlauch"],"beilagen":["Grüner Salat","Röstzwiebeln","Braune Butter"],"getraenk":"Ein leichter Weißwein oder Bier","koeche":[],"quellen":[{"titel":"Austrian cuisine – Wikipedia (Kärntner Kasnudeln: Kärnten, Topfen und Minze)","url":"https://en.wikipedia.org/wiki/Austrian_cuisine"},{"titel":"TasteAtlas – Austrian dishes ranking (verwandte gefüllte Nudeln: Schlutzkrapfen, Kasnocken)","url":"https://www.tasteatlas.com/best-rated-dishes-in-austria"}],"bild":"dumplings","farben":["#e8d9b0","#b07b3a","#6b8f3a"],"schlagworte":["Kärnten","Festtagsgericht","Handwerk","Minze"],"vegetarisch_moeglich":true},{"id":"oesterreich-spinatknoedel-baerlauchbutter-witzigmann","name":"Spinatknödel mit Bärlauchbutter nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Vorarlberg / Tirol","beliebtheit":64,"hauptkategorie":"vegetarisch","gang":"hauptgericht","kurz":"Lockere grüne Semmelknödel mit Spinat und Bergkäse, übergossen mit flüssiger Bärlauchbutter.","hintergrund":"Spinatknödel sind ein alpines Klassiker-Gericht; sie gehören ebenso in die Küche von Vorarlberg, wo Eckart Witzigmann 1941 in Hohenems geboren wurde, wie nach Tirol und Südtirol. Laut Beschreibung enthält Witzigmanns Bärlauchbuch Knödel mit Spinat, die hier mit einer Bärlauchbutter verbunden werden. Dies ist eine Heimküchen-Fassung nach klassischer Knödeltechnik: nicht sein Originalrezept, sondern eine Verbindung zweier Elemente, die in der Beschreibung seines Buches genannt werden.","portionen":4,"zeit":{"vorbereitung":35,"garen":20,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Knödel","liste":[{"menge":250,"einheit":"g","name":"Knödelbrot oder altbackene Semmeln","hinweis":"in 1 cm Würfeln"},{"menge":200,"einheit":"ml","name":"Milch","hinweis":"lauwarm"},{"menge":3,"einheit":"Stück","name":"Eier","hinweis":"Größe M"},{"menge":300,"einheit":"g","name":"frischer Blattspinat","hinweis":"oder 250 g TK-Blattspinat, aufgetaut"},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel","hinweis":"fein gewürfelt"},{"menge":20,"einheit":"g","name":"Butter","hinweis":"zum Andünsten"},{"menge":40,"einheit":"g","name":"Bergkäse","hinweis":"fein gerieben"},{"menge":30,"einheit":"g","name":"Mehl","hinweis":"Type 405"},{"menge":1.5,"einheit":"TL","name":"Salz"},{"menge":null,"einheit":"","name":"frisch geriebene Muskatnuss und Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Für die Bärlauchbutter","liste":[{"menge":100,"einheit":"g","name":"Butter"},{"menge":30,"einheit":"g","name":"frischer Bärlauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"TL","name":"Zitronensaft"},{"menge":null,"einheit":"","name":"Salz","hinweis":"eine Prise"}]},{"gruppe":"Zum Servieren","liste":[{"menge":40,"einheit":"g","name":"Bergkäse oder Parmesan","hinweis":"gehobelt"}]}],"ausruestung":["großer breiter Topf","Schüssel","Schaumlöffel","Pfanne oder kleiner Topf","Passiersieb oder Tuch"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide die Semmeln in gleichmäßige, etwa 1 Zentimeter große Würfel und gib sie in eine große Schüssel. Verlese den Spinat, entferne grobe Stiele und wasche ihn zweimal in reichlich Wasser, damit kein Sand zurückbleibt. Hacke die Zwiebel fein, reibe den Käse und lege die Butter bereit. Nimm die Eier etwa 30 Minuten vor der Verarbeitung aus dem Kühlschrank, damit der Teig nicht auskühlt. Setze einen großen Topf mit Salzwasser auf, aber heize ihn erst später an.","dauer":12,"tipp":"Altbackene Semmeln saugen die Milch gleichmäßig auf – frisches Brot macht die Knödel matschig."},{"titel":"Spinat blanchieren und ausdrücken","aktion":"blanchieren","text":"Blanchiere den frischen Spinat 30 Sekunden in sprudelnd kochendem Salzwasser, bis er zusammenfällt und leuchtend dunkelgrün ist. Schrecke ihn sofort in Eiswasser ab, damit die Farbe erhalten bleibt, und presse ihn dann mit den Händen kräftig aus; er soll krümelig trocken sein. Aufgetauter TK-Spinat wird ebenfalls ausgedrückt, am besten in einem sauberen Küchentuch. Hacke den Spinat fein. Restwasser würde den Teig verwässern und die Knödel auseinanderfallen lassen.","dauer":6,"tipp":"Je trockener der Spinat, desto formstabiler die Knödel."},{"titel":"Zwiebeln andünsten","aktion":"anbraten","text":"Erhitze die Butter in einer kleinen Pfanne bei mittlerer Hitze und dünste die Zwiebelwürfel 3 bis 4 Minuten glasig, ohne Farbe zu nehmen. Sie sollen süßlich duften, nicht braun werden. Gib den gehackten Spinat dazu, rühre 1 Minute mit und würze mit Muskat. Nimm die Pfanne vom Herd und lasse die Mischung 5 Minuten abkühlen, damit sie später die Eier nicht stocken lässt.","dauer":8,"tipp":""},{"titel":"Teig ansetzen","aktion":"mischen","text":"Verquirle Milch, Eier und 1,5 Teelöffel Salz, gieße die Mischung über die Semmelwürfel und vermenge alles behutsam. Lasse die Masse 10 Minuten ziehen, bis die Würfel gleichmäßig durchfeuchtet sind, aber nicht zerfallen. Füge Spinat-Zwiebel-Mischung, Käse und Mehl hinzu und knete alles mit leicht angefeuchteten Händen zu einem formbaren, nicht klebrigen Teig. Er soll sich beim Drücken zu einer Kugel schließen lassen. Wenn er zu weich ist, gib 1 bis 2 Esslöffel Semmelbrösel dazu.","dauer":15,"tipp":"Zuviel Kneten macht die Knödel zäh – nur durchmischen."},{"titel":"Probeknödel und Formen","aktion":"formen","text":"Forme zuerst einen Probeknödel und lasse ihn 8 Minuten in leicht siedendem Wasser garen. Zerfällt er, arbeite 1 Esslöffel Mehl oder Semmelbrösel in den Teig; ist er fest und schmeckt gut, formst du die übrigen. Befeuchte deine Hände mit kaltem Wasser und forme aus dem Teig etwa 12 Knödel in der Größe eines Tischtennisballs (ca. 70 g). Presse sie fest zusammen und runde sie zwischen den Handflächen. Lege sie auf ein feuchtes Brett und lasse sie 10 Minuten ruhen.","dauer":15,"tipp":"Der Probeknödel spart dir die Überraschung im Topf."},{"titel":"Knödel garen","aktion":"koecheln","text":"Bringe das Salzwasser zum Kochen und reduziere dann die Hitze, bis es nur noch leicht siedet – sprudelndes Wasser zerreißt die Knödel. Lege die Knödel vorsichtig hinein und lasse sie 15 Minuten ohne Deckel ziehen. Sie steigen nach einigen Minuten nach oben; jetzt schwimmen sie, sind aber noch nicht fertig. Gegen Ende drehst du sie mit dem Schaumlöffel einmal um. Ein Knödel ist durch, wenn er sich elastisch anfühlt und beim Anstechen innen gleichmäßig grün und trocken ist.","dauer":15,"tipp":"Wasser nur ziehen, nie sprudeln lassen."},{"titel":"Bärlauchbutter","aktion":"schmoren","text":"Schmelze die Butter in einem kleinen Topf bei niedriger Hitze, ohne sie zu bräunen; sie soll nur flüssig werden und nach Nuss duften. Nimm den Topf vom Herd und rühre den gehackten Bärlauch, den Zitronensaft und eine Prise Salz ein. Die Restwärme genügt, um das Aroma freizusetzen. Würde der Bärlauch kochen, würde er bitter und graubraun. Die Butter soll hellgrün schimmern und intensiv nach Knoblauch und Frühling riechen.","dauer":5,"tipp":"Bärlauch nie in der heißen Butter braten – nur ziehen lassen."},{"titel":"Anrichten","aktion":"anrichten","text":"Hebe die Knödel mit dem Schaumlöffel aus dem Wasser und lasse sie kurz abtropfen. Lege je drei Knödel auf einen vorgewärmten tiefen Teller und gieße die Bärlauchbutter großzügig darüber. Hobele den Käse in dünnen Spänen darauf und gib frischen Pfeffer dazu. Serviere sofort, denn Knödel verlieren beim Stehen ihre Lockerheit. Ein knackiger Blattsalat mit Essig-Kürbiskernöl-Marinade ergänzt das Gericht.","dauer":2,"tipp":""}],"profitipps":["Altbackene Semmeln und ausgedrückter Spinat sind das Fundament eines stabilen Teigs.","Immer erst einen Probeknödel garen.","Das Wasser darf nur leise ziehen.","Bärlauchbutter vom Herd ziehen, bevor der Bärlauch dazukommt.","Reste lassen sich in Scheiben schneiden und in Butter anbraten."],"varianten":["Mit Topfen im Teig – etwas cremiger.","Mit Sauerkraut-Zwiebel-Schmelze (Südtiroler Art).","In klarer Gemüsebrühe als Knödelsuppe.","Mit Brunnenkresse oder Mangold statt Spinat."],"beilagen":["Gemischter Salat mit Kürbiskernöl","Gedünstete Tomaten","Pilzrahm"],"getraenk":"Weißburgunder oder ein Radler","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"knoedel","farben":["#5f8a3a","#e9d8a0","#f5ecc8"],"schlagworte":["Knödel","Bärlauch","Alpenküche"],"vegetarisch_moeglich":true},{"id":"oesterreich-baerlauch-pesto-bandnudeln-witzigmann","name":"Bärlauch-Pesto mit Bandnudeln nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Österreich / Bayern","beliebtheit":62,"hauptkategorie":"vegetarisch","gang":"hauptgericht","kurz":"Grünes, würziges Frühlings-Pesto aus frischem Bärlauch, das roh bleibt und nur mit heißen Bandnudeln cremig gerührt wird.","hintergrund":"Bärlauch ist das Frühlingsgewürz der Alpenküche, und Eckart Witzigmann hat ihm 2017 sogar ein eigenes Buch gewidmet („Meine besten Bärlauchrezepte“, 20 Rezepte); in der Beschreibung des Buches wird unter anderem ein Bärlauchpesto genannt. Das Pesto-Prinzip stammt aus Ligurien, wo Basilikum die Hauptrolle spielt – Bärlauch ersetzt ihn in dieser nördlichen Variante, wie auch Wikipedia für nicht-traditionelle Pestos festhält. Dies ist eine Heimküchen-Fassung im Geist seines Bärlauchbuchs, nicht sein Originalrezept; die Mengen sind eigene, bewährte Richtwerte.","portionen":4,"zeit":{"vorbereitung":25,"garen":12,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für das Pesto","liste":[{"menge":120,"einheit":"g","name":"frischer Bärlauch","hinweis":"März bis Mai auf dem Markt; alternativ 80 g Bärlauch + 40 g Basilikum oder Rucola"},{"menge":50,"einheit":"g","name":"Pinienkerne","hinweis":"alternativ Walnüsse oder Sonnenblumenkerne"},{"menge":60,"einheit":"g","name":"Parmesan oder Bergkäse","hinweis":"frisch und fein gerieben"},{"menge":120,"einheit":"ml","name":"kaltes Olivenöl, nativ extra"},{"menge":1,"einheit":"EL","name":"Zitronensaft"},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Für die Nudeln","liste":[{"menge":400,"einheit":"g","name":"Bandnudeln (Tagliatelle)","hinweis":"frisch oder getrocknet"},{"menge":3,"einheit":"l","name":"Wasser"},{"menge":2,"einheit":"EL","name":"grobes Salz"},{"menge":1,"einheit":"EL","name":"Pinienkerne","hinweis":"zum Bestreuen, geröstet"},{"menge":30,"einheit":"g","name":"Parmesan","hinweis":"zum Hobeln am Tisch"}]}],"ausruestung":["hohes Rührgefäß mit Stabmixer (oder Mörser)","große Pfanne ohne Fett","großer Topf","Schüssel zum Schwenken","Schraubglas"],"schritte":[{"titel":"Mise en place und Bärlauch prüfen","aktion":"vorbereiten","text":"Lies den Bärlauch Blatt für Blatt durch und entferne Welkes und Fremdes. Zerreibe ein Blatt zwischen den Fingern: Es muss deutlich nach Knoblauch riechen, denn Maiglöckchen und Herbstzeitlose, die tödlich giftig sind, sehen ähnlich aus. Wasche den Bärlauch in kaltem Wasser, schleudere ihn trocken oder tupfe ihn in einem Tuch gründlich ab – nasse Blätter machen das Pesto wässrig und kurzlebig. Reibe den Käse fein, lege Pinienkerne und Zitrone bereit und setze 3 Liter Wasser für die Nudeln auf. Stelle den Bärlauch noch einmal kurz in den Kühlschrank, denn kalte Zutaten erwärmen sich beim Mixen weniger und behalten ihre Farbe.","dauer":10,"tipp":"Wikipedia warnt ausdrücklich vor der Verwechslung: Bärlauch hat mattglänzende Blätter mit Parallelnerven und riecht beim Zerreiben nach Knoblauch."},{"titel":"Pinienkerne rösten","aktion":"anbraten","text":"Gib die Pinienkerne in eine kalte, trockene Pfanne und erhitze sie bei mittlerer Hitze. Schwenke sie ständig, denn sie färben sich plötzlich: Nach 3 bis 4 Minuten sind sie goldgelb und duften nussig-süßlich. Ein einziger Moment Unaufmerksamkeit lässt sie bitter werden, also nimm sie sofort aus der Pfanne, sobald die ersten braunen Stellen erscheinen, und lass sie auf einem Teller auskühlen. Heiße Kerne würden im Mixer das Öl erwärmen und den Bärlauch verfärben. Ein Esslöffel der Kerne bleibt zum Bestreuen übrig.","dauer":5,"tipp":"Kerne zuerst abkühlen lassen, bevor sie in den Mixer wandern."},{"titel":"Pesto mixen","aktion":"mischen","text":"Gib den Bärlauch grob geschnitten, die ausgekühlten Pinienkerne, den Käse, einen halben Teelöffel Salz und die Hälfte des Öls in ein hohes Gefäß. Püriere mit dem Stabmixer in kurzen Impulsen von je 2 bis 3 Sekunden und schiebe zwischendurch mit einem Löffel nach. Dauermixen erwärmt die Masse und macht das Pesto stumpf und bitter; deshalb arbeitest du lieber in Etappen. Das Ziel ist eine feine, aber noch leicht körnige Paste, in der du kleine Kernstücke siehst. Wer es klassisch mag, zerstößt alles im Mörser und arbeitet das Öl nach und nach ein.","dauer":5,"tipp":"Mixen in Impulsen statt Dauerlauf – so bleibt das Pesto hellgrün."},{"titel":"Öl einarbeiten und abschmecken","aktion":"abschmecken","text":"Gieße das restliche Öl dünn unter Rühren dazu, bis das Pesto glänzt und locker vom Löffel fällt. Gib den Zitronensaft hinzu, denn die Säure hält die Farbe frisch und rundet die Schärfe des Bärlauchs ab. Schmecke mit Pfeffer und Salz ab; Parmesan bringt schon viel Salz mit, also taste dich vorsichtig heran. Das Pesto soll kräftig sein, denn die Nudeln verdünnen es später deutlich. Fülle den größeren Teil in ein Schraubglas und bedecke die Oberfläche mit einem Finger breit Öl, damit keine Luft herankommt und es nicht braun wird.","dauer":3,"tipp":"Eine Ölschicht auf der Oberfläche schützt vor Oxidation."},{"titel":"Nudeln garen","aktion":"kochen","text":"Bringe das Wasser mit dem Salz zum kräftigen Sprudeln – das Wasser soll schmecken wie eine leichte Brühe. Gib die Tagliatelle hinein, rühre in den ersten 30 Sekunden um, damit nichts klebt, und koche sie bissfest: frische Nudeln brauchen 2 bis 3 Minuten, getrocknete 8 bis 9 Minuten oder so lange, wie die Packung sagt, minus eine Minute. Fische, bevor du abgießt, eine große Tasse Nudelwasser ab. Es enthält Stärke und ist der Schlüssel zu einer cremigen Sauce statt eines öligen Pestos.","dauer":10,"tipp":"Nudelwasser aufheben – ohne es wird das Pesto schwer und klebrig."},{"titel":"Pesto mit Nudelwasser aufschlagen","aktion":"mischen","text":"Gib 5 bis 6 Esslöffel Pesto in eine große, vorgewärmte Schüssel und rühre 4 Esslöffel heißes Nudelwasser darunter, bis eine glänzende, cremige Sauce entsteht. Das Pesto selbst wird nicht gekocht, denn Hitze zerstört das frische Bärlaucharoma und macht es braun und bitter. Gieße die Nudeln ab, lass sie nur kurz abtropfen und gib sie sofort in die Schüssel. Wende alles mit zwei Gabeln, bis jede Nudel einen grünen Mantel trägt, und gib bei Bedarf einen Schuss Nudelwasser nach. Die Sauce muss die Nudeln locker umhüllen, nicht auf dem Boden stehen.","dauer":3,"tipp":"Das Pesto-Nudelwasser-Gemisch ist wichtiger als jede zusätzliche Ölmenge."},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile die Nudeln mit einer Fleischgabel in Nestern auf vorgewärmten tiefen Tellern und streue die gerösteten Pinienkerne darüber. Hobele den Parmesan mit dem Sparschäler direkt am Tisch in dünnen Spänen darauf und gib noch einen Hauch Pfeffer aus der Mühle dazu. Serviere sofort, denn die Nudeln saugen die Sauce rasch auf. Ein Blatt frischer Bärlauch als Dekoration bringt Farbe und Duft. Dazu passen ein einfacher Blattsalat und ein trockener Weißwein.","dauer":2,"tipp":""},{"titel":"Reste lagern","aktion":"kuehlen","text":"Das übrige Pesto hält sich im Glas mit Ölschicht im Kühlschrank etwa 5 bis 7 Tage; schiebe nach jeder Entnahme das Öl wieder glatt. Zum Einfrieren eignen sich Eiswürfelformen: Gefrorene Würfel kannst du portionsweise in Soßen, Suppen oder Rührei einrühren. Gib vor dem Einfrieren keinen Käse hinein, sondern rühre ihn später frisch unter, dann bleibt der Geschmack klarer. Nutze das Pesto auch als Aufstrich auf Landbrot, als Marinade für Hähnchen oder als grüne Linie in Gemüsesuppen.","dauer":0,"tipp":"Käse erst nach dem Auftauen unterrühren."}],"profitipps":["Bärlauch immer trocken verarbeiten, sonst wird das Pesto wässrig.","Kalte Zutaten und kurzes Mixen halten die Farbe leuchtend.","Das Pesto nie in der Pfanne erhitzen, sondern mit heißem Nudelwasser aufschlagen.","Zitronensaft und eine Ölschicht verhindern das Braunwerden.","Außerhalb der Saison: Bärlauch aus dem Gefrierfach oder Bärlauch-Kapern ersetzen einen Teil."],"varianten":["Mit Walnüssen und Pecorino statt Pinienkernen und Parmesan.","Halb Bärlauch, halb Basilikum für ein milderes Pesto.","Mit Kürbiskernen und Kürbiskernöl steirisch abgewandelt.","Als Brotaufstrich mit Ricotta oder Frischkäse verrührt."],"beilagen":["Gemischter Blattsalat mit Zitronendressing","Gebackene Tomaten","Ofenbrot"],"getraenk":"Trockener Grüner Veltliner oder ein leichter Riesling","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Pesto – Wikipedia (Zubereitung, Varianten, Oxidation)","url":"https://de.wikipedia.org/wiki/Pesto"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"nudeln","farben":["#6b8e23","#d9e4a8","#f1e2b6"],"schlagworte":["Bärlauch","Frühling","Pesto"],"vegetarisch_moeglich":true},{"id":"oesterreich-krautfleckerl","name":"Krautfleckerl","originalname":"Krautfleckerl","kueche":"oesterreich","region":"Wien / Böhmen","beliebtheit":58,"hauptkategorie":"vegetarisch","gang":"hauptgericht","kurz":"In Zucker und Fett karamellisiertes Weißkraut mit Kümmel und kleinen Teigfleckerln – ein süß-würziges Wiener Hausmannskost-Gericht.","hintergrund":"Krautfleckerl sind ein klassisches Gericht der österreichischen, böhmischen und kroatischen Küche. Das fein gehobelte Weißkraut wird mit Zwiebeln in karamellisiertem Zucker geschmort, mit Kümmel gewürzt und zum Schluss mit gekochten Fleckerln, kleinen quadratischen Nudeln, vermengt. Der Zucker, der im Fett gebräunt wird, gibt dem Kraut seine charakteristische süße Röstnote und die goldbraune Farbe. Das Gericht ist ein einfaches Alltagsessen und schmeckt am nächsten Tag aufgewärmt noch besser.","portionen":4,"zeit":{"vorbereitung":25,"garen":50,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Krautfleckerl","liste":[{"menge":800,"einheit":"g","name":"Weißkraut (Spitzkraut)","hinweis":"fein gehobelt oder in dünne Streifen geschnitten"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"fein gewürfelt"},{"menge":2,"einheit":"EL","name":"Zucker","hinweis":"für den Karamell"},{"menge":60,"einheit":"g","name":"Butterschmalz oder Schweineschmalz","hinweis":""},{"menge":1,"einheit":"TL","name":"Kümmel","hinweis":"ganz oder gemahlen"},{"menge":1,"einheit":"EL","name":"Weinessig","hinweis":""},{"menge":100,"einheit":"ml","name":"Weißwein oder Rindsuppe","hinweis":""},{"menge":100,"einheit":"ml","name":"Rindsuppe","hinweis":""},{"menge":400,"einheit":"g","name":"Fleckerl (Nudelflecken)","hinweis":"ersatzweise Bandnudeln, in Quadrate gebrochen, oder Farfalline"},{"menge":100,"einheit":"g","name":"Speckwürfel","hinweis":"optional"},{"menge":null,"einheit":"","name":"Salz, schwarzer Pfeffer, gehackte Petersilie","hinweis":""}]}],"ausruestung":["Großer, weiter Topf oder Bratpfanne mit Deckel","Krauthobel oder scharfes Messer","Holzlöffel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Entferne vom Kraut die äußeren Blätter und den Strunk und hobele oder schneide es in feine, etwa 3–4 mm breite Streifen. Würfle die Zwiebeln fein und stelle Zucker, Fett und Gewürze bereit. Koche einen Topf mit Salzwasser für die Fleckerl erst später auf. Schneide den Speck, falls du ihn verwendest, in kleine Würfel. Alles sollte griffbereit sein, weil der Karamell schnell geht.","dauer":15,"tipp":""},{"titel":"Zucker karamellisieren","aktion":"anbraten","text":"Erhitze das Fett in einem weiten Topf bei mittlerer Hitze, streue den Zucker hinein und rühre ihn mit einem Holzlöffel, bis er schmilzt und eine goldbraune Farbe annimmt, die an hellen Karamell erinnert. Das dauert etwa 3–4 Minuten, und es duftet nach Karamell. Wird er zu dunkel, schmeckt das ganze Gericht bitter, also nimm den Topf sofort vom Herd, sobald der Zucker die Farbe von Honig bis Kupfer hat, und lösche rasch mit dem nächsten Schritt.","dauer":5,"tipp":"Zu heiß gerösteter Zucker wird bitter – lieber früh löschen."},{"titel":"Zwiebeln und Speck anrösten","aktion":"anbraten","text":"Gib die Zwiebelwürfel – und den Speck, falls du ihn verwendest – in den Karamell und röste sie unter ständigem Rühren 4–5 Minuten, bis sie weich und goldbraun sind. Sie nehmen die Farbe des Karamells an und duften süßlich und würzig. Achte darauf, dass nichts anbrennt, und rühre häufig, damit der Karamell nicht am Boden festklebt. Der Speck gibt sein Fett ab und wird leicht knusprig, was dem Gericht eine herzhafte Note gibt.","dauer":5,"tipp":""},{"titel":"Kraut zugeben und schmoren","aktion":"schmoren","text":"Gib das Kraut hinzu, rühre gut um, sodass es mit dem Karamell überzogen ist, und würze mit Kümmel, Salz und Pfeffer. Brate es unter Rühren 5 Minuten an, bis es leicht zusammenfällt und Farbe annimmt. Gieße den Essig, Wein und Suppe an, decke den Topf zu und lasse das Kraut bei kleiner bis mittlerer Hitze 25–30 Minuten schmoren, bis es weich und goldbraun ist. Rühre gelegentlich um.","dauer":30,"tipp":""},{"titel":"Fleckerl kochen","aktion":"kochen","text":"Koche die Fleckerl in reichlich Salzwasser 8–10 Minuten, bis sie bissfest, aber nicht mehr hart sind, gieße sie ab und lasse sie gut abtropfen, ohne sie mit kaltem Wasser abzuschrecken. Sie dürfen nicht zu weich sein, denn sie garen in der Wärme des Krauts noch nach und saugen Saft auf. Falls du gekaufte Fleckerl verwendest, richte dich nach der Packungsangabe. Schwenke sie sofort mit etwas Fett, damit sie nicht zusammenkleben.","dauer":10,"tipp":""},{"titel":"Vermischen","aktion":"mischen","text":"Gib die abgetropften Fleckerl in den Topf zum Kraut und vermische alles gründlich, indem du es 2–3 Minuten bei mittlerer Hitze schwenkst und wendest. Die Nudeln nehmen dabei etwas Aroma und Saft auf und färben sich leicht golden. Schmecke kräftig mit Salz, Pfeffer, Kümmel und eventuell einem Schuss Essig ab; das Gericht soll süß-säuerlich-würzig schmecken. Ist es zu trocken, gib einen Schluck Suppe dazu, ist es zu feucht, lasse es offen kurz einziehen.","dauer":5,"tipp":""},{"titel":"Abschmecken und rasten","aktion":"abschmecken","text":"Lasse die Krautfleckerl zugedeckt 5 Minuten bei ausgeschalteter Hitze ruhen, damit sich die Aromen verbinden und die Nudeln noch etwas Saft aufnehmen. Probiere noch einmal und gleiche Süße und Säure aus: Fehlt Frische, hilft ein Spritzer Essig, fehlt Würze, etwas Salz oder Kümmel. Es sollte ein leicht karamellisierter Duft mit Kümmelnote aufsteigen. Streue zum Schluss frisch gehackte Petersilie darüber, die dem schweren Gericht Frische verleiht.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Richte die Krautfleckerl auf vorgewärmten tiefen Tellern an und streue Petersilie darüber. Serviere sie heiß mit einem einfachen Blattsalat und frischem Brot; als Beilage passen gebratene Würstchen oder ein Spiegelei. Am nächsten Tag lassen sie sich in der Pfanne mit etwas Fett kross aufbraten und schmecken dann noch kräftiger, weil das Kraut durchgezogen ist. Reste halten sich zugedeckt im Kühlschrank bis zu drei Tage.","dauer":0,"tipp":""}],"profitipps":["Zucker nur bis zur Farbe von hellem Karamell rösten, sonst wird das Kraut bitter.","Kraut fein hobeln, damit es gleichmäßig weich wird.","Fleckerl bissfest kochen und sofort mit dem Kraut vermischen.","Am nächsten Tag aufgebraten schmecken sie noch besser.","Kümmel gibt dem Kraut Würze und macht es bekömmlicher."],"varianten":["Mit Speckwürfeln","Mit Wurst oder Schinken","Mit Sauerkraut statt Weißkraut","Vegane Variante mit Öl statt Schmalz"],"beilagen":["Grüner Salat","Bratwurst","Spiegelei"],"getraenk":"Bier oder ein Glas trockener Weißwein","koeche":[],"quellen":[{"titel":"Krautfleckerl – Wikipedia (de)","url":"https://de.wikipedia.org/wiki/Krautfleckerl"}],"bild":"nudeln","farben":["#b9873a","#dcc37e","#7a8a4a"],"schlagworte":["Hausmannskost","Wiener Küche","Weißkraut","Kümmel"],"vegetarisch_moeglich":true},{"id":"oesterreich-gebackener-karpfen","name":"Gebackener Karpfen mit Erdäpfel-Vogerlsalat","originalname":"","kueche":"oesterreich","region":"Waldviertel, Weihnachten und Silvester","beliebtheit":56,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Geschröpfte Karpfenstücke in knuspriger Brösel-Panade, mit Zitrone und lauwarmem Erdäpfel-Vogerlsalat – das österreichische Weihnachtsessen schlechthin.","hintergrund":"In Österreich und Deutschland ist der Karpfen vor allem an Weihnachten und Silvester beliebt; im Waldviertel und in Böhmen wird der „Weihnachtskarpfen“ lebend verkauft, zu Hause geschlachtet und meist paniert mit Zitrone serviert. Traditionell isst man ihn von September bis April, in den Monaten mit „r“. Um die vielen Zwischengräten unschädlich zu machen, wird das Fleisch geschröpft: Man ritzt es engmaschig bis auf die Haut ein, sodass die Gräten beim Backen zerfallen. Der Waldviertler Teichkarpfen gilt als besonders aromatisch, weil er langsam in sauberen Teichen wächst.","portionen":4,"zeit":{"vorbereitung":45,"garen":20,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Karpfen","liste":[{"menge":1.2,"einheit":"kg","name":"Karpfen, küchenfertig (ausgenommen, geschuppt), in Portionsstücke geteilt","hinweis":"ca. 8 Stücke à 150 g; vom Fischhändler schröpfen lassen oder selbst"},{"menge":2,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gerieben"},{"menge":null,"einheit":"","name":"weißer Pfeffer aus der Mühle","hinweis":"nach Geschmack"},{"menge":120,"einheit":"g","name":"glattes Mehl (Type W480)","hinweis":"zum Wenden"},{"menge":3,"einheit":"","name":"Eier","hinweis":""},{"menge":200,"einheit":"g","name":"feine Semmelbrösel","hinweis":""},{"menge":1,"einheit":"kg","name":"Butterschmalz oder Frittieröl","hinweis":"zum Ausbacken"},{"menge":2,"einheit":"","name":"Zitronen","hinweis":"in Spalten"}]},{"gruppe":"Für den Erdäpfel-Vogerlsalat","liste":[{"menge":700,"einheit":"g","name":"festkochende Erdäpfel (Kartoffeln)","hinweis":""},{"menge":1,"einheit":"","name":"kleine Zwiebel","hinweis":"fein gewürfelt"},{"menge":150,"einheit":"ml","name":"heiße Rindsuppe oder Gemüsebrühe","hinweis":""},{"menge":3,"einheit":"EL","name":"Weißweinessig","hinweis":""},{"menge":3,"einheit":"EL","name":"Sonnenblumenöl","hinweis":"ersatzweise Kürbiskernöl"},{"menge":1,"einheit":"TL","name":"Senf","hinweis":""},{"menge":150,"einheit":"g","name":"Vogerlsalat (Feldsalat)","hinweis":"gewaschen und gut abgetropft"},{"menge":null,"einheit":"","name":"Salz und Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["Großes Messer und Brett","Gusseisen- oder schwere Pfanne, mind. 28 cm","Küchenthermometer","3 flache Teller","Gitter und Backblech"],"schritte":[{"titel":"Mise en place und Karpfen prüfen","aktion":"vorbereiten","text":"Frischer Karpfen hat klare, gewölbte Augen, rote Kiemen und riecht neutral nach Wasser, nicht modrig; wenn das Fleisch beim Eindrücken zurückfedert, ist er frisch. Ein leicht erdiger Geschmack lässt sich vermeiden, indem der Fischhändler den Karpfen vor dem Schlachten einige Tage in klarem Frischwasser hältert. Lass den Karpfen dort ausnehmen, entschuppen und in Stücke teilen. Heize den Backofen auf 80 °C vor, um fertige Stücke warm zu halten. Stelle alle Zutaten für Panade und Salat bereit.","dauer":10,"tipp":""},{"titel":"Karpfen schröpfen","aktion":"schneiden","text":"Schröpfen bedeutet, das Fleisch mit einem scharfen, dünnen Messer in engen Abständen von etwa 3–5 mm senkrecht bis fast zur Haut einzuschneiden, ohne sie zu durchtrennen. So werden die feinen Zwischengräten durchtrennt, die sonst beim Essen stören; sie werden beim Backen weich. Arbeite ruhig und gleichmäßig von der Mitte aus. Wenn du unsicher bist, lasse den Fischhändler schröpfen – das ist ein Handgriff, den er in Sekunden beherrscht.","dauer":15,"tipp":"Ein Filetiermesser mit schmaler Klinge macht das Schröpfen deutlich leichter."},{"titel":"Beizen","aktion":"marinieren","text":"Vermische Zitronensaft, Salz, geriebenen Knoblauch und weißen Pfeffer und reibe die Karpfenstücke von allen Seiten damit ein; achte darauf, dass die Würze auch in die Einschnitte gelangt. Lege die Stücke zugedeckt für 30 Minuten in den Kühlschrank. Das Salz festigt das Fleisch, die Säure bindet Erdgeruch und der Knoblauch gibt Aroma. Danach trocknest du die Stücke mit Küchenpapier gründlich ab.","dauer":30,"tipp":"Nicht länger als 45 Minuten, sonst wird das Fleisch durch die Säure fest."},{"titel":"Erdäpfelsalat vorbereiten","aktion":"kochen","text":"Koche die Kartoffeln in der Schale 20–25 Minuten gar, pelle sie noch warm und schneide sie in dünne Scheiben. Übergieße die warmen Scheiben mit heißer Suppe, Essig, Zwiebel, Senf, Salz und Pfeffer, mische vorsichtig und lasse sie 20 Minuten ziehen, damit sie die Marinade aufsaugen. Zum Schluss rührst du das Öl unter. Der Salat soll saftig, leicht säuerlich und nicht trocken sein. Hebe kurz vor dem Servieren den Vogerlsalat darunter.","dauer":35,"tipp":"Die Kartoffeln warm marinieren: Sie nehmen die Brühe auf und der Salat wird saftig."},{"titel":"Panieren","aktion":"panieren","text":"Stelle drei Teller bereit: Mehl, verquirlte Eier mit einer Prise Salz, Semmelbrösel. Wende die Karpfenstücke zuerst im Mehl und klopfe den Überschuss ab, ziehe sie dann durch das Ei und drücke sie schließlich in den Bröseln fest, ohne zu pressen. Die Panade soll später „soufflieren“, also luftig vom Fisch abstehen – deshalb nicht festdrücken. Lege die panierten Stücke 10 Minuten auf ein Gitter.","dauer":10,"tipp":"Das typische Wiener Soufflieren gelingt, wenn du die Panade locker lässt und das Fett heiß genug ist."},{"titel":"Fett erhitzen","aktion":"vorbereiten","text":"Erhitze das Butterschmalz in einer weiten Pfanne auf 170 °C, es soll mindestens 2 cm hoch stehen. Teste mit einem Holzlöffelstiel: Steigen sofort kleine Bläschen auf, ist das Fett bereit. Das Fett darf nicht rauchen. Butterschmalz verleiht den typischen, leicht nussigen Geschmack und verbrennt nicht so schnell wie Butter.","dauer":5,"tipp":""},{"titel":"Karpfen ausbacken","aktion":"frittieren","text":"Lege die Stücke vorsichtig mit der Hautseite nach oben ins heiße Fett, höchstens vier Stücke gleichzeitig. Schwenke die Pfanne leicht, damit sich die Panade bauscht, und backe sie 3–4 Minuten, bis die Unterseite goldbraun ist. Wende die Stücke einmal und backe sie weitere 3 Minuten. Der Karpfen ist gar, wenn die Kruste goldbraun ist und das Fleisch am Kern etwa 62–65 °C erreicht hat. Hebe sie auf Küchenpapier und halte sie im Ofen warm.","dauer":10,"tipp":"Karpfen verträgt etwas mehr Garzeit als zarter Fisch – das Fleisch ist fest und fetter."},{"titel":"Anrichten","aktion":"anrichten","text":"Richte den gebackenen Karpfen mit Zitronenspalten und dem lauwarmen Erdäpfel-Vogerlsalat an. Streue eine Prise Salz über die Kruste und garniere mit Petersilie. Serviere sofort, solange die Panade knusprig und leicht gebläht ist, denn nach wenigen Minuten verliert sie ihren Biss. Wer mag, reicht dazu eine kleine Schüssel Remoulade oder Preiselbeeren; das Fruchtige harmoniert mit dem milden, leicht süßlichen Karpfenfleisch.","dauer":0,"tipp":""}],"profitipps":["Karpfen nur in den Monaten September bis April essen, dann ist er am fettesten und aromatischsten.","Der Fisch muss vor dem Schlachten gewässert sein, damit er keinen Modergeschmack hat.","Schröpfen entschärft die Gräten – das lohnt sich auch beim Backen im Ofen.","Lass die Panade locker, dann bauscht sie sich schön auf.","Butterschmalz verbrennt nicht so schnell und gibt Geschmack."],"varianten":["Karpfenfilet im Bierteig.","Karpfen „blau“ gekocht mit Essig und Lorbeer.","Karpfen mit Kartoffel-Gurken-Salat.","Karpfen aus dem Ofen mit Wurzelgemüse."],"beilagen":["Erdäpfel-Vogerlsalat","Petersilienkartoffeln","Zitronenspalten","Preiselbeeren"],"getraenk":"Grüner Veltliner oder ein Weißburgunder aus der Wachau; alternativ ein kühles Märzenbier.","koeche":[],"quellen":[{"titel":"Karpfen – Wikipedia","url":"https://de.wikipedia.org/wiki/Karpfen"}],"bild":"fisch","farben":["#d29c3f","#f2dfa5","#8f6f3a"],"schlagworte":["Weihnachten","Silvester","Süßwasserfisch","paniert"],"themen":["fest"],"vegetarisch_moeglich":false,"hinweis":"Karpfen gibt es von September bis April beim Fischhändler, auf dem Wochenmarkt oder direkt beim Teichwirt; frage nach Bio- oder Teichwirtschaft aus der Region. Alternativ geht auch Wels- oder Zanderfilet."},{"id":"oesterreich-kraeuter-baerlauch-salat-witzigmann","name":"Kräuter-Bärlauch-Salat mit lauwarmen Erdäpfeln und weichem Ei nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Österreich","beliebtheit":55,"hauptkategorie":"vegetarisch","gang":"salat","kurz":"Zarte Frühlingsblätter, frische Kräuter und feine Bärlauchstreifen auf lauwarmen Erdäpfeln – mit weich gekochtem Ei als Krönung.","hintergrund":"Ein Kräuter-Bärlauch-Salat gehört laut Beschreibung zu den Rezepten in Eckart Witzigmanns Buch „Meine besten Bärlauchrezepte“ (2017). Wie genau seine Fassung aussieht, habe ich nicht gesehen; diese Heimküchen-Version folgt der österreichischen Salattradition: Erdäpfel werden lauwarm in einer Essig-Öl-Marinade mit warmer Brühe getränkt, damit sie den Geschmack aufsaugen. Der rohe Bärlauch kommt erst ganz zum Schluss in den Salat, weil Säure und Zeit sein Aroma und seine Farbe angreifen.","portionen":4,"zeit":{"vorbereitung":25,"garen":30,"ruhen":10},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Salat","liste":[{"menge":400,"einheit":"g","name":"festkochende Kartoffeln","hinweis":"möglichst gleich groß"},{"menge":4,"einheit":"Stück","name":"Eier","hinweis":"Größe M, Zimmertemperatur"},{"menge":100,"einheit":"g","name":"Feldsalat oder junge Salatblätter","hinweis":"gewaschen und trocken"},{"menge":1,"einheit":"Bund","name":"gemischte Kräuter","hinweis":"Kerbel, Petersilie, Schnittlauch, evtl. Sauerampfer"},{"menge":40,"einheit":"g","name":"frischer Bärlauch"},{"menge":6,"einheit":"Stück","name":"Radieschen"}]},{"gruppe":"Für die Marinade","liste":[{"menge":1,"einheit":"Stück","name":"Schalotte","hinweis":"sehr fein gewürfelt"},{"menge":3,"einheit":"EL","name":"Weißweinessig"},{"menge":1,"einheit":"TL","name":"mittelscharfer Senf"},{"menge":4,"einheit":"EL","name":"warme Gemüsebrühe"},{"menge":4,"einheit":"EL","name":"Rapsöl oder Kürbiskernöl"},{"menge":1,"einheit":"Prise","name":"Zucker"},{"menge":null,"einheit":"","name":"Salz und Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["Topf mit Dämpfeinsatz oder Kochtopf","Schüssel","kleine Schüssel für das Dressing","scharfes Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche die Kartoffeln unter fließendem Wasser mit einer Bürste. Salat und Kräuter in kaltem Wasser waschen, trocken schleudern und kühl stellen, damit sie knackig bleiben. Schneide die Radieschen in feine Scheiben und den Schnittlauch in Röllchen. Die Schalotte hackst du so fein wie möglich, denn sie soll im Dressing kaum auffallen. Den Bärlauch schneidest du erst am Ende, denn Schnittflächen oxidieren rasch.","dauer":8,"tipp":"Salat im Kühlschrank lassen – kalt bleibt er kross."},{"titel":"Erdäpfel garen","aktion":"kochen","text":"Lege die Kartoffeln mit Schale in kaltes Salzwasser und bringe sie langsam zum Kochen. Reduziere dann die Hitze und gare sie 20 bis 25 Minuten, je nach Größe, bis ein Holzspieß ohne Widerstand hineingleitet. Die Schale schützt vor dem Auslaugen von Geschmack und Stärke. Gieße ab und lass sie 3 Minuten ausdampfen. Pelle sie noch warm mit einem kleinen Messer, denn kalt bricht die Schale schwerer ab.","dauer":25,"tipp":"Immer in kaltem Wasser aufsetzen, damit sie gleichmäßig garen."},{"titel":"Marinade anrühren","aktion":"mischen","text":"Rühre in einer Schüssel Essig, Senf, Salz, Pfeffer und eine Prise Zucker glatt. Gib die Schalotte und die heiße Brühe dazu und verrühre alles, bis sich das Salz gelöst hat. Gieße zuletzt das Öl in dünnem Strahl hinein und schlage die Marinade kräftig auf, damit sie sich leicht bindet. Schmecke sie ruhig zu kräftig ab, denn Kartoffeln und Salat schlucken später viel Würze. Die Brühe macht das Dressing mild und hilft den Erdäpfeln, sich vollzusaugen.","dauer":3,"tipp":"Warme Brühe löst Salz und Senf und lässt die Kartoffeln die Marinade aufsaugen."},{"titel":"Erdäpfel marinieren","aktion":"marinieren","text":"Schneide die noch warmen Kartoffeln in 3 Millimeter dicke Scheiben und gib sie sofort in die Marinade. Wende sie mit zwei Löffeln vorsichtig, damit sie nicht zerbrechen, und lass sie 10 Minuten durchziehen. Sie sollen glänzen und schmatzend feucht sein, aber nicht schwimmen; bei Bedarf gibst du noch einen Löffel Brühe zu. Lauwarm schmecken sie am besten. Während sie ziehen, kochst du die Eier.","dauer":10,"tipp":"Warm marinieren – kalte Kartoffeln nehmen kaum Geschmack an."},{"titel":"Eier weich kochen","aktion":"kochen","text":"Stich die Eier am stumpfen Ende mit einer Nadel an, damit sie nicht platzen. Lasse sie in sprudelnd kochendem Wasser genau 6 Minuten garen – das Weiße ist dann fest, der Dotter flüssig bis cremig. Schrecke sie sofort in Eiswasser ab, damit der Garprozess stoppt, und pelle sie vorsichtig unter fließendem Wasser. Halbiere die Eier erst kurz vor dem Anrichten, damit der Dotter nicht antrocknet. Wer es fester mag, kocht 7 Minuten.","dauer":8,"tipp":"Eier mit Raumtemperatur platzen seltener."},{"titel":"Salat anrichten","aktion":"anrichten","text":"Schneide den Bärlauch jetzt in feine Streifen und hacke die Kräuter grob. Vermische Feldsalat, Kräuter und Radieschen locker mit einem Esslöffel des überschüssigen Dressings aus der Kartoffelschüssel. Verteile die Erdäpfel auf Tellern, lege den Salat in einer Haube darauf und setze die Eierhälften obenauf. Streue den Bärlauch ganz zum Schluss darüber, damit er duftet und grün bleibt. Mit grobem Salz und Pfeffer aus der Mühle würzen.","dauer":3,"tipp":"Bärlauch erst zuletzt – Essig bleicht die Blätter."}],"profitipps":["Die Kartoffeln warm pellen und marinieren – so saugen sie das Dressing auf.","Bärlauch zuletzt schneiden und streuen.","Eier nie lange vor dem Servieren halbieren.","Kürbiskernöl gibt dem Salat eine steirische Note.","Gut gewaschene, trockene Blätter verhindern ein wässriges Dressing."],"varianten":["Mit gebratenen Speckwürfeln statt Ei.","Mit Räucherforelle als Salat-Hauptgang.","Ohne Kartoffeln als leichter Vorspeisensalat.","Mit gehackten Walnüssen und Ziegenkäse."],"beilagen":["Roggenbrot mit Butter","Gebratener Spargel","Kräuter-Topfen"],"getraenk":"Frischer Gelber Muskateller oder Grüner Veltliner","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"salat","farben":["#7ca04a","#f2e3a1","#d4b46a"],"schlagworte":["Bärlauch","Frühling","Salat"],"vegetarisch_moeglich":true},{"id":"oesterreich-baerlauchbutter-baerlauchoel-witzigmann","name":"Bärlauchbutter und Bärlauchöl nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Österreich","beliebtheit":55,"hauptkategorie":"vegetarisch","gang":"sauce","kurz":"Zwei Frühlings-Grundrezepte: aromatische Bärlauchbutter für Brot und Fleisch und leuchtend grünes Bärlauchöl für Salate und Suppen.","hintergrund":"Bärlauchbutter und Bärlauchöl gehören laut Beschreibung zu den Zubereitungen in Eckart Witzigmanns Buch „Meine besten Bärlauchrezepte“ (2017); der Klappentext berichtet, er habe den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt. Seine Rezepte kenne ich nicht, deshalb ist dies eine Heimküchen-Fassung nach klassischer Technik. Das Öl wird blanchiert und püriert, damit es seine Farbe behält.","portionen":8,"zeit":{"vorbereitung":30,"garen":3,"ruhen":120},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Bärlauchbutter","liste":[{"menge":250,"einheit":"g","name":"weiche Butter"},{"menge":60,"einheit":"g","name":"frischer Bärlauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"Zitronensaft"},{"menge":1,"einheit":"TL","name":"Fleur de Sel"},{"menge":null,"einheit":"","name":"weißer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Für das Bärlauchöl","liste":[{"menge":80,"einheit":"g","name":"frischer Bärlauch"},{"menge":200,"einheit":"ml","name":"mildes Olivenöl oder Rapsöl"},{"menge":0.5,"einheit":"TL","name":"Salz"},{"menge":1,"einheit":"l","name":"Wasser","hinweis":"zum Blanchieren"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":"für das Blanchierwasser"}]}],"ausruestung":["Schüssel","Pürierstab oder Mixer","feines Sieb oder Kaffeefilter","Frischhaltefolie","Schraubglas oder Flasche"],"schritte":[{"titel":"Mise en place und Bärlauch prüfen","aktion":"vorbereiten","text":"Lies den Bärlauch sorgfältig durch, entferne gelbe oder welke Blätter und wasche ihn in kaltem Wasser. Schleudere ihn trocken oder tupfe ihn in einem Tuch gründlich ab; Restwasser lässt die Butter später ranzig werden und das Öl trübe. Zerreibe ein Blatt: Es muss nach Knoblauch riechen, sonst besteht Verwechslungsgefahr mit giftigen Pflanzen wie Maiglöckchen. Teile den Bärlauch in zwei Portionen für Butter und Öl.","dauer":10,"tipp":"Immer am Geruch prüfen – Verwechslung mit Maiglöckchen ist lebensgefährlich."},{"titel":"Bärlauchbutter ansetzen","aktion":"mischen","text":"Lasse die Butter 30 Minuten bei Zimmertemperatur weich werden, sie soll sich leicht eindrücken lassen, aber nicht schmelzen. Hacke 60 g Bärlauch sehr fein und gib ihn mit Zitronensaft, Fleur de Sel und Pfeffer zur Butter. Vermenge alles mit einem Gummispatel oder den Händen gründlich, bis die Butter gleichmäßig grün gesprenkelt ist. Probiere: Sie soll kräftig nach Bärlauch schmecken, mit einer leichten Zitronenfrische.","dauer":8,"tipp":"Butter nicht zu warm werden lassen."},{"titel":"Rolle formen und kühlen","aktion":"rollen","text":"Gib die Butter auf ein Stück Frischhaltefolie und forme mit Hilfe der Folie eine gleichmäßige Rolle von etwa 4 Zentimeter Durchmesser. Drehe die Enden fest ein wie bei einem Bonbon und streiche Luftblasen heraus. Lege die Rolle für mindestens 2 Stunden in den Kühlschrank, bis sie schnittfest ist. Im Kühlschrank hält sie 5 bis 7 Tage, eingefroren 3 Monate. Schneide später Scheiben ab, wie du sie brauchst.","dauer":5,"tipp":"Luftfrei einrollen – so hält sie länger."},{"titel":"Bärlauch blanchieren","aktion":"blanchieren","text":"Bringe das Wasser mit dem Salz zum Kochen. Tauche die 80 g Bärlauch für nur 10 bis 15 Sekunden hinein; er fällt zusammen und wird leuchtend grün. Schrecke ihn sofort in Eiswasser ab, damit die Farbe erhalten bleibt, und drücke ihn dann fest mit den Händen aus. Wickle ihn in ein Küchentuch und presse ihn nochmals aus. Er soll sich trocken anfühlen, sonst wird das Öl trüb.","dauer":5,"tipp":"Nur Sekunden blanchieren – sonst verliert er Aroma."},{"titel":"Öl pürieren","aktion":"puerieren","text":"Gib den ausgedrückten Bärlauch mit Öl und Salz in einen hohen Becher und püriere ihn 1 bis 2 Minuten auf hoher Stufe, bis eine sattgrüne, glatte Flüssigkeit entsteht. Durch das Rühren erwärmt sich das Öl leicht, was die Aromen löst. Lass es in einem Glas 1 bis 2 Stunden im Kühlschrank ruhen, damit sich die Schwebstoffe setzen. Es duftet intensiv nach Bärlauch, ohne scharf zu sein.","dauer":5,"tipp":"Je kälter die Zutaten, desto grüner das Öl."},{"titel":"Öl filtern und abfüllen","aktion":"abseihen","text":"Gieße das Öl durch ein feines Sieb oder einen Kaffeefilter in ein Glas; das dauert einige Minuten, da es nur langsam durchläuft. Drücke nicht, denn dadurch trübt es sich. Das gefilterte Öl ist klar und leuchtend grün. Fülle es in eine Flasche oder ein Schraubglas und bewahre es dunkel und kühl auf. Es hält 5 bis 7 Tage im Kühlschrank; wegen des Bärlauchs nicht länger lagern, da frisches Pflanzenmaterial in Öl verderben kann.","dauer":10,"tipp":"Nicht durchdrücken, sonst wird das Öl trüb."},{"titel":"Verwenden","aktion":"anrichten","text":"Serviere die Bärlauchbutter auf Landbrot mit Radieschen, auf gegrilltem Fleisch, Fisch oder gekochten Kartoffeln; sie schmilzt in der Wärme und bringt Duft. Das Bärlauchöl tropfst du über Suppen, Spargel, Carpaccio oder Salate, es eignet sich auch für Vinaigrettes. Erhitze es nicht, sonst verliert es seine Farbe. Rühre Butter und Öl erst zum Schluss unter heiße Speisen, damit das Aroma erhalten bleibt.","dauer":2,"tipp":""}],"profitipps":["Bärlauch immer gut trocknen.","Butter nach Wunsch mit etwas Knoblauch verstärken.","Öl nur kurz blanchiert und eiskalt pürieren.","Nicht erhitzen.","Gefroren hält die Butter 3 Monate."],"varianten":["Kräuterbutter mit Petersilie und Schnittlauch gemischt.","Bärlauchsalz durch Trocknen mit grobem Salz.","Bärlauchbutter als Würfel eingefroren.","Mit Parmesan und Pinienkernen zur Pesto-Butter."],"beilagen":["Landbrot","Gegrilltes Fleisch","Kartoffeln"],"getraenk":"Weißwein oder Bier","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"dip","farben":["#6b9a3a","#e8e0a0","#f2e8b0"],"schlagworte":["Bärlauch","Butter","Grundrezept"],"vegetarisch_moeglich":true},{"id":"oesterreich-baerlauch-erdaepfel-auflauf-witzigmann","name":"Bärlauch-Erdäpfel-Auflauf nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Österreich","beliebtheit":52,"hauptkategorie":"vegetarisch","gang":"hauptgericht","kurz":"Hauchdünne Kartoffelscheiben in einem grünen Bärlauch-Guss, mit Bergkäse überbacken – cremig, aromatisch, knusprig.","hintergrund":"Aufläufe gehören laut Beschreibung zu den Gerichten in Eckart Witzigmanns Bärlauchbuch von 2017. Dies ist eine Heimküchen-Fassung nach der klassischen Gratin-Technik: Rohe Kartoffelscheiben garen im Rahmguss, nehmen dabei die Stärke auf und binden ihn zu einer cremigen Masse. Der Bärlauch wird fein püriert, so färbt sich der Guss grün. Nicht sein Originalrezept.","portionen":4,"zeit":{"vorbereitung":25,"garen":55,"ruhen":10},"schwierigkeit":1,"zutaten":[{"gruppe":"Für den Auflauf","liste":[{"menge":800,"einheit":"g","name":"festkochende Kartoffeln"},{"menge":120,"einheit":"g","name":"Bergkäse","hinweis":"grob gerieben"},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":"halbiert, zum Einreiben"},{"menge":15,"einheit":"g","name":"Butter","hinweis":"für die Form"}]},{"gruppe":"Für den Bärlauch-Guss","liste":[{"menge":250,"einheit":"ml","name":"Sahne"},{"menge":150,"einheit":"ml","name":"Milch"},{"menge":2,"einheit":"Stück","name":"Eier"},{"menge":60,"einheit":"g","name":"frischer Bärlauch"},{"menge":1.5,"einheit":"TL","name":"Salz"},{"menge":null,"einheit":"","name":"Pfeffer und frisch geriebene Muskatnuss","hinweis":"nach Geschmack"}]}],"ausruestung":["Auflaufform (ca. 24 × 30 cm)","Gemüsehobel","Pürierstab","Alufolie"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schäle die Kartoffeln und halte sie in kaltem Wasser, bis du sie hobelst. Wasche und trockne den Bärlauch gründlich und schneide die Stiele ab. Reibe den Käse grob und reibe die Auflaufform mit der halbierten Knoblauchzehe aus. Fette die Form anschließend mit Butter ein. Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor, denn der Auflauf wandert sofort hinein.","dauer":10,"tipp":""},{"titel":"Kartoffeln hobeln","aktion":"schneiden","text":"Hobele die Kartoffeln mit dem Gemüsehobel oder einem scharfen Messer in gleichmäßige, 3 Millimeter dicke Scheiben. Gleiche Dicke ist wichtig, weil dünne Scheiben schneller garen als dicke. Trockne die Scheiben nicht und wasche sie nicht ab: Die Stärke an der Oberfläche bindet später den Guss und sorgt für Cremigkeit. Salze sie leicht. Lege die Scheiben in eine Schüssel und vermenge sie mit den Händen.","dauer":8,"tipp":"Stärke nicht abwaschen – sie bindet den Guss."},{"titel":"Bärlauch-Guss pürieren","aktion":"puerieren","text":"Gib Sahne, Milch, Eier, Bärlauch, Salz, Pfeffer und Muskat in ein hohes Gefäß und püriere alles fein, bis der Guss gleichmäßig hellgrün ist und keine Blattstücke mehr sichtbar sind. Probiere ihn; er soll deutlich würzig sein, weil die Kartoffeln viel Salz aufnehmen. Roher Bärlauch gibt dem Guss ein kräftiges Aroma; beim Backen wird er etwas milder und olivgrün. Rühre kurz um, bevor du ihn verwendest.","dauer":4,"tipp":"Guss zu kräftig würzen – Kartoffeln schlucken viel Salz."},{"titel":"Schichten","aktion":"schichten","text":"Schichte die Kartoffelscheiben dachziegelartig in die Form, jede Lage mit etwas Käse bestreut. Wiederhole das bis zur letzten Lage; 2 Esslöffel Käse bleiben für die Kruste. Gieße den Guss gleichmäßig über die Kartoffeln; er soll sie fast, aber nicht ganz bedecken. Drücke die Schichten mit einem Löffel leicht an, damit der Guss überall hinfließt. Streue den restlichen Käse darüber.","dauer":8,"tipp":""},{"titel":"Ofen und Form bereit machen","aktion":"vorbereiten","text":"Stelle die Auflaufform auf ein Backblech, das etwaiges Überkochen auffängt, und schiebe den Rost auf die mittlere Schiene. Der Ofen muss tatsächlich 180 °C erreicht haben, bevor der Auflauf hineinkommt; die Aufheizzeit beträgt je nach Gerät 10 bis 15 Minuten, und ein Backofenthermometer verrät dir, ob die Anzeige stimmt. Prüfe, ob die Alufolie groß genug ist, um die Form dicht zu verschließen, und lege sie bereit. Bestreiche die Unterseite der Folie dünn mit Butter, damit der Käse später nicht klebt.","dauer":3,"tipp":"Die Folie vorher einfetten, dann bleibt kein Käse hängen."},{"titel":"Backen","aktion":"backen","text":"Decke die Form mit Alufolie ab und backe den Auflauf 30 Minuten, damit die Kartoffeln im Dampf weich werden. Entferne dann die Folie und backe weitere 20 bis 25 Minuten, bis die Oberfläche goldbraun ist und der Guss am Rand leise blubbert. Ein Messer muss ohne Widerstand durch die Kartoffeln gleiten. Wenn die Kruste zu schnell bräunt, lege die Folie locker wieder auf. Nimm die Form heraus, wenn der Rand leicht knusprig ist.","dauer":55,"tipp":"Zuerst abdecken, dann bräunen – so gart er gleichmäßig."},{"titel":"Garprobe und Kruste","aktion":"backen","text":"Prüfe nach den ersten 30 Minuten, ob sich der Guss gleichmäßig verteilt hat, und stich mit einem spitzen Messer in die Mitte: Die Kartoffeln müssen weich sein, aber noch etwas Biss haben. Wenn der Guss noch flüssig ist, backe 5 Minuten länger. Für eine knusprigere Kruste schaltest du in den letzten 3 Minuten den Grill an; bleib aber daneben, denn der Käse kann schnell verbrennen. Die Oberfläche soll goldbraun und leicht blasig sein, der Rand duftet nach geröstetem Käse.","dauer":5,"tipp":"Grill nur kurz und unter Aufsicht."},{"titel":"Ruhen und Anrichten","aktion":"ruhen","text":"Lasse den Auflauf 10 Minuten ruhen, damit sich der Guss setzt und sich die Stücke sauber schneiden lassen. Schneide ihn in Quadrate und hebe sie mit einem breiten Spatel auf die Teller. Streue frisch gehackten Bärlauch oder Schnittlauch darüber. Serviere ihn mit einem knackigen Salat, dessen Säure den Rahm schön ausgleicht. Reste lassen sich am nächsten Tag in der Pfanne knusprig braten.","dauer":10,"tipp":""}],"profitipps":["Gleichmäßig dünne Kartoffelscheiben garen gleichzeitig.","Stärke nicht abspülen – sie macht den Guss cremig.","Erst abgedeckt, dann offen backen.","Der Guss darf kräftig schmecken, sonst wird der Auflauf fad.","Nach dem Backen 10 Minuten ruhen lassen."],"varianten":["Mit Kochschinken-Streifen für Fleischliebhaber.","Mit Räucherlachs-Lagen.","Mit Süßkartoffeln gemischt.","Mit Ziegenkäse statt Bergkäse."],"beilagen":["Grüner Salat mit Vinaigrette","Gebratene Pilze","Tomatensalat"],"getraenk":"Grüner Veltliner oder leichter Weißburgunder","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"auflauf","farben":["#9bb36a","#e6d79a","#f4ead0"],"schlagworte":["Bärlauch","Auflauf","Frühling"],"vegetarisch_moeglich":true},{"id":"oesterreich-spinat-knoepfle-baerlauchrahm-witzigmann","name":"Spinat-Knöpfle mit Bärlauchrahm und Bergkäse nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Vorarlberg","beliebtheit":50,"hauptkategorie":"vegetarisch","gang":"hauptgericht","kurz":"Grüne Teigknöpfle in einer sämigen Bärlauch-Rahmsauce mit würzigem Bergkäse – vorarlbergisch-alemannisch gedacht.","hintergrund":"Knöpfle sind die kleinen Verwandten der Spätzle und zählen in Vorarlberg und dem Allgäu zur Alltagsküche; Eckart Witzigmann wurde 1941 in Hohenems in Vorarlberg geboren. In der Beschreibung seines Bärlauchbuchs werden „Knödel und Knöpfle mit Spinat“ genannt – mehr als diese Stichworte kenne ich nicht, deshalb ist dies eine Heimküchen-Fassung nach klassischer Teigtechnik, die Spinat und Bärlauch zu einer Rahmsauce verbindet. Nicht sein Originalrezept.","portionen":4,"zeit":{"vorbereitung":35,"garen":20,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Knöpfle","liste":[{"menge":300,"einheit":"g","name":"Mehl","hinweis":"Type 405 oder Spätzlemehl"},{"menge":3,"einheit":"Stück","name":"Eier"},{"menge":150,"einheit":"g","name":"frischer Blattspinat","hinweis":"oder 120 g TK-Spinat"},{"menge":60,"einheit":"ml","name":"Wasser"},{"menge":1,"einheit":"TL","name":"Salz"},{"menge":null,"einheit":"","name":"frisch geriebene Muskatnuss","hinweis":"nach Geschmack"},{"menge":3,"einheit":"l","name":"Salzwasser","hinweis":"zum Garen"}]},{"gruppe":"Für den Bärlauchrahm","liste":[{"menge":20,"einheit":"g","name":"Butter"},{"menge":1,"einheit":"Stück","name":"Schalotte","hinweis":"fein gewürfelt"},{"menge":100,"einheit":"ml","name":"Gemüsebrühe"},{"menge":250,"einheit":"ml","name":"Sahne"},{"menge":40,"einheit":"g","name":"frischer Bärlauch","hinweis":"fein geschnitten"},{"menge":80,"einheit":"g","name":"Bergkäse","hinweis":"grob gerieben"},{"menge":1,"einheit":"TL","name":"Zitronensaft"},{"menge":null,"einheit":"","name":"Salz und Pfeffer","hinweis":"nach Geschmack"}]}],"ausruestung":["Spätzlebrett oder Spätzlepresse (alternativ Grobreibe/Sieb)","großer Topf","Pürierstab","Schaumlöffel","Pfanne"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Verlese den Spinat, wasche ihn gründlich und lasse ihn abtropfen. Schneide den Bärlauch in feine Streifen, würfle die Schalotte und reibe den Käse. Wiege Mehl, Eier und Wasser bereit und setze den großen Topf mit Salzwasser auf, damit es später sprudelt. Stelle Sieb oder Spätzlebrett, Schaumlöffel und eine Schüssel mit warmem Wasser bereit, in die du Brett und Messer immer wieder tauchst.","dauer":10,"tipp":""},{"titel":"Spinat pürieren","aktion":"puerieren","text":"Blanchiere den Spinat 30 Sekunden in kochendem Salzwasser, schrecke ihn in Eiswasser ab und drücke ihn gründlich aus. Püriere ihn mit 3 Esslöffeln des Wassers fein; du erhältst einen glatten, sattgrünen Brei. Je glatter, desto gleichmäßiger die Farbe der Knöpfle. Lasse das Püree kurz abkühlen, damit die Eier nicht stocken. Wiege 100 g davon ab; der Rest passt in eine Suppe.","dauer":6,"tipp":"Nach dem Blanchieren sofort abschrecken – so bleibt das Grün leuchtend."},{"titel":"Teig schlagen","aktion":"kneten","text":"Gib Mehl, Salz und Muskat in eine Schüssel, mache eine Mulde und füge Eier, Spinatpüree und Wasser hinein. Schlage den Teig mit einem Kochlöffel kräftig, bis er glänzt und Blasen wirft; er soll zäh und zähflüssig sein und in Bändern vom Löffel reißen. Durch das Schlagen entwickelt sich Gluten, und die Knöpfle werden elastisch, nicht mehlig. Lasse den Teig zugedeckt 20 Minuten ruhen. Er ist richtig, wenn er langsam vom Löffel fließt.","dauer":25,"tipp":"Teig muss Blasen werfen und in Bändern vom Löffel reißen."},{"titel":"Rahmsauce ansetzen","aktion":"reduzieren","text":"Erhitze die Butter in einer breiten Pfanne und dünste die Schalotte bei mittlerer Hitze glasig. Gieße die Brühe zu und koche sie auf die Hälfte ein, damit sie konzentriert schmeckt. Füge die Sahne hinzu und lasse alles 5 bis 6 Minuten sanft köcheln, bis die Sauce einen Löffelrücken überzieht. Würze mit Salz, Pfeffer und Zitrone; der Bärlauch kommt erst am Ende hinein. Nimm die Pfanne beiseite und halte sie warm.","dauer":8,"tipp":"Sahne nur köcheln, nicht sprudelnd kochen."},{"titel":"Knöpfle formen und garen","aktion":"formen","text":"Bringe das Salzwasser zum kräftigen Sprudeln. Gib einen Teil des Teigs auf ein nasses Brett, streiche ihn mit einem Messer zu kleinen Knöpfchen ab und lasse sie direkt ins Wasser gleiten, oder drücke ihn portionsweise durch die Presse. Sie sind fertig, sobald sie an die Oberfläche steigen, nach weiteren 30 Sekunden. Fische sie mit dem Schaumlöffel heraus und lasse sie abtropfen. Arbeite in Portionen, damit die Wassertemperatur nicht sinkt.","dauer":12,"tipp":"Brett und Messer immer wieder in Wasser tauchen, dann klebt nichts."},{"titel":"Knöpfle in Butter schwenken","aktion":"anbraten","text":"Erhitze einen Teelöffel Butter in einer zweiten, breiten Pfanne bei mittlerer Hitze und schwenke die abgetropften Knöpfle 1 bis 2 Minuten darin. Sie sollen an den Rändern leicht Farbe nehmen und nussig duften; das gibt ihnen einen zarten Biss und verhindert, dass sie in der Sauce aufweichen. Schüttle die Pfanne ab und zu, damit nichts ansetzt. Gib einen Schuss Kochwasser dazu, falls sie zu trocken wirken. Dieser Schritt ist optional, macht den Unterschied zwischen bloß gekochten und richtig veredelten Knöpfle.","dauer":3,"tipp":"Kurz anbraten gibt Röstaromen und festeren Biss."},{"titel":"Fertigstellen","aktion":"mischen","text":"Gib die Knöpfle in die warme Rahmsauce, schwenke sie vorsichtig und rühre den Käse unter, bis er schmilzt und die Sauce bindet. Nimm die Pfanne vom Herd und mische den Bärlauch ein; die Restwärme genügt, damit er duftet, ohne grau zu werden. Wenn die Sauce zu dick ist, gib einen Löffel Nudelwasser dazu. Schmecke ab: Sie soll kräftig, cremig und leicht zitronig sein.","dauer":4,"tipp":"Bärlauch immer erst nach dem Herd zugeben."},{"titel":"Anrichten","aktion":"anrichten","text":"Fülle die Knöpfle in vorgewärmte tiefe Teller und träufle etwas Sauce darüber. Streue noch etwas gehobelten Bergkäse und frische Bärlauchstreifen obenauf. Serviere sofort, denn die Knöpfle ziehen die Sauce rasch auf. Dazu passt ein grüner Salat. Reste kannst du am nächsten Tag in Butter knusprig anbraten.","dauer":2,"tipp":""}],"profitipps":["Teig gut schlagen, bis er Blasen wirft.","Salzwasser kräftig sprudeln lassen, aber nicht überfüllen.","Brett und Messer immer wieder anfeuchten.","Rahmsauce vor dem Bärlauch einkochen.","Bergkäse erst in der warmen, nicht heißen Sauce schmelzen."],"varianten":["Mit Räucherlachs-Streifen.","Mit gerösteten Zwiebeln statt Rahmsauce (Kässpätzle-Art).","Mit Pilzen und Thymian.","Als gebackener Auflauf mit Käsekruste."],"beilagen":["Grüner Salat mit Kürbiskernöl","Apfelmus","Gerösteter Spargel"],"getraenk":"Weißburgunder oder Vorarlberger Riesling","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"nudeln","farben":["#7aa05a","#efe3b0","#f6eed2"],"schlagworte":["Knöpfle","Bärlauch","Vorarlberg"],"vegetarisch_moeglich":true},{"id":"oesterreich-lammkeule-baerlauchkruste-witzigmann","name":"Lammkeule (oder Zicklein) mit Bärlauchkruste nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Österreich","beliebtheit":50,"hauptkategorie":"fleisch","fleischsorte":"lamm","gang":"hauptgericht","kurz":"Rosa gebratene Lammkeule unter einer grünen Kruste aus Bärlauch, Butter und Semmelbröseln – ein Ostergericht.","hintergrund":"Zicklein und Lamm sind die klassischen Osterbraten der Alpenregion. In der Beschreibung von Eckart Witzigmanns Bärlauchbuch (2017) wird ein Gericht mit Zicklein erwähnt; Details zu seinem Rezept kenne ich nicht. Diese Heimküchen-Fassung nimmt die leichter erhältliche Lammkeule und verbindet sie mit einer Kruste aus Bärlauchbutter und Bröseln, die das Fleisch aromatisiert und vor dem Austrocknen schützt. Wer Zicklein bekommt, kann es genauso zubereiten. Nicht sein Originalrezept.","portionen":6,"zeit":{"vorbereitung":40,"garen":100,"ruhen":20},"schwierigkeit":2,"themen":["fest"],"zutaten":[{"gruppe":"Für das Fleisch","liste":[{"menge":1.5,"einheit":"kg","name":"Lammkeule ohne Knochen","hinweis":"aufgerollt und gebunden; alternativ Zickleinkeule"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"in Scheiben"},{"menge":2,"einheit":"Zweig","name":"Rosmarin"},{"menge":4,"einheit":"Zweig","name":"Thymian"},{"menge":3,"einheit":"EL","name":"Olivenöl"},{"menge":null,"einheit":"","name":"Salz und schwarzer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Für den Bratensatz","liste":[{"menge":2,"einheit":"Stück","name":"Karotten","hinweis":"grob gewürfelt"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"geviertelt"},{"menge":150,"einheit":"g","name":"Knollensellerie","hinweis":"grob gewürfelt"},{"menge":200,"einheit":"ml","name":"trockener Rotwein oder Weißwein"},{"menge":400,"einheit":"ml","name":"Lamm- oder Kalbsfond"}]},{"gruppe":"Für die Bärlauchkruste","liste":[{"menge":80,"einheit":"g","name":"weiche Butter"},{"menge":70,"einheit":"g","name":"Semmelbrösel","hinweis":"frisch gerieben"},{"menge":50,"einheit":"g","name":"frischer Bärlauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"EL","name":"mittelscharfer Senf"},{"menge":1,"einheit":"Stück","name":"Eigelb"},{"menge":null,"einheit":"","name":"Salz","hinweis":"eine Prise"}]}],"ausruestung":["Bräter oder tiefes Blech","Fleischthermometer","Küchengarn","Pürierstab oder Messer","Sieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Nimm die Lammkeule 1 Stunde vor dem Braten aus dem Kühlschrank, damit sie nicht eiskalt in den Ofen kommt und gleichmäßiger gart. Tupfe sie trocken und entferne überschüssiges Fett und Sehnen; eine dünne Fettschicht darf bleiben. Schneide Karotten, Zwiebeln und Sellerie grob, zupfe die Kräuter ab und hacke den Bärlauch. Heize den Ofen auf 160 °C Ober-/Unterhitze (140 °C Umluft) vor. Prüfe, ob die Keule fest gebunden ist, damit sie ihre Form behält.","dauer":15,"tipp":""},{"titel":"Würzen und spicken","aktion":"marinieren","text":"Reibe die Keule mit Olivenöl, Salz und Pfeffer rundum kräftig ein. Steche mit einem spitzen Messer in kleinen Abständen Taschen und stecke Knoblauchscheiben und Kräuterspitzen hinein. So aromatisiert sich das Fleisch von innen. Lege die Keule dann zurück auf den Teller und lasse sie 10 Minuten ruhen. Salz zieht in dieser Zeit etwas ein.","dauer":10,"tipp":""},{"titel":"Anbraten","aktion":"anbraten","text":"Erhitze das restliche Öl im Bräter bei hoher Hitze, bis es leicht raucht. Brate die Keule rundum 6 bis 8 Minuten an, bis sie tiefbraun ist; dabei entstehen die Röstaromen für Bratensatz und Sauce. Wende sie mit zwei Löffeln, nicht mit der Gabel, damit kein Saft entweicht. Gib dann Gemüse und Kräuterreste in den Bräter und röste sie 3 Minuten mit. Der Boden darf braun, aber nicht schwarz sein.","dauer":10,"tipp":"Nicht einstechen – sonst läuft der Saft aus."},{"titel":"Im Ofen garen","aktion":"schmoren","text":"Schiebe den Bräter in die Mitte des Ofens. Gieße 100 ml Fond zu und stecke das Fleischthermometer in die dickste Stelle. Brate die Keule 60 bis 80 Minuten, bis die Kerntemperatur 52 °C erreicht, also noch nicht ganz rosa. Begieße sie dabei alle 20 Minuten mit dem Bratensaft. Wenn der Boden trocken wird, gib etwas Fond nach. Die Zeit ist nur ein Richtwert; entscheidend ist das Thermometer.","dauer":75,"tipp":"Kerntemperatur zählt, nicht die Uhr."},{"titel":"Kruste zubereiten","aktion":"mischen","text":"Verrühre während des Garens die Butter mit Bröseln, Bärlauch, Senf, Eigelb und einer Prise Salz zu einer streichfähigen Paste. Sie soll duften und grün glänzen. Wenn die Masse zu fest ist, hilft ein Teelöffel Wasser; wenn sie zu weich ist, mehr Brösel. Stelle sie bis zur Verwendung kühl, damit die Butter nicht ausläuft.","dauer":5,"tipp":"Kühl halten, sonst wird sie zu weich."},{"titel":"Kruste aufbringen","aktion":"backen","text":"Nimm die Keule bei einer Kerntemperatur von 52 °C aus dem Ofen. Streiche die Kruste gleichmäßig 5 Millimeter dick auf die Oberseite und drücke sie leicht an. Stelle die Keule wieder in den Ofen und schalte den Grill dazu (oder erhöhe auf 220 °C). Überbacke sie 5 bis 8 Minuten, bis die Kruste goldbraun und leicht knusprig ist; beobachte sie genau, denn Bärlauch und Brösel verbrennen schnell. Die Kerntemperatur steigt dabei auf etwa 56 bis 58 °C.","dauer":8,"tipp":"Grill nie unbeaufsichtigt lassen."},{"titel":"Ruhen lassen","aktion":"ruhen","text":"Nimm den Braten aus dem Ofen und lasse ihn auf einem Brett, locker mit Alufolie bedeckt, 15 Minuten ruhen. In dieser Zeit verteilen sich die Fleischsäfte; die Kerntemperatur steigt auf etwa 60 °C, das Fleisch wird zart rosa. Würdest du sofort anschneiden, würde der Saft auslaufen. Die Ruhezeit nutzt du für die Sauce.","dauer":15,"tipp":"Nicht verkürzen – der Saft sammelt sich wieder."},{"titel":"Sauce aus dem Bratensatz","aktion":"reduzieren","text":"Stelle den Bräter auf die Herdplatte, gieße den Wein hinein und löse den Bratensatz mit einem Holzlöffel. Koche die Flüssigkeit um die Hälfte ein, gib den restlichen Fond zu und lasse alles 10 Minuten kochen. Streiche die Sauce durch ein Sieb und drücke das Gemüse aus. Schmecke mit Salz, Pfeffer und einem Spritzer Zitrone ab. Sie soll glänzend, dunkel und leicht sämig sein; bei Bedarf bindest du sie mit einem Stückchen kalter Butter.","dauer":15,"tipp":""},{"titel":"Aufschneiden und Anrichten","aktion":"anrichten","text":"Schneide das Küchengarn durch und zerlege die Keule mit einem scharfen Messer in 1 Zentimeter dicke Scheiben. Lege je zwei bis drei Scheiben auf warme Teller und gieße etwas Sauce darüber. Streue Fleur de Sel auf das Fleisch und garniere mit Bärlauchblättern. Serviere dazu Kartoffelgratin oder Bohnen. Reste schmecken kalt mit Senf hervorragend.","dauer":5,"tipp":""}],"profitipps":["Kerntemperatur: 52 °C vor der Kruste, 56–58 °C danach, rosa.","Fleisch unbedingt ruhen lassen.","Kruste im Kühlschrank zwischenlagern, damit sie nicht schmilzt.","Das Fleisch rundum kräftig anbraten.","Beim Zicklein die Garzeit um ca. 10 Minuten verkürzen."],"varianten":["Mit Kräuterkruste aus Petersilie, Kerbel und Thymian.","Lammrücken statt Keule (kürzere Garzeit).","Mit Senfkruste ohne Bärlauch.","Mit Haselnüssen in der Kruste."],"beilagen":["Kartoffelgratin","Grüne Bohnen im Speckmantel","Rosmarinkartoffeln"],"getraenk":"Kräftiger Zweigelt oder Blaufränkisch","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"braten-scheiben","farben":["#7a4a2b","#8fae5a","#e8c9a0"],"schlagworte":["Ostern","Lamm","Bärlauch"],"vegetarisch_moeglich":false},{"id":"oesterreich-reisauflauf-marillen-witzigmann","name":"Süßer Reisauflauf mit Marillen nach Art von Eckart Witzigmann","originalname":"Marillen-Reisauflauf","kueche":"oesterreich","region":"Österreich","beliebtheit":50,"hauptkategorie":"suess","gang":"dessert","kurz":"Luftiger Milchreis-Auflauf mit Eischnee und saftigen Marillenhälften, goldbraun überbacken.","hintergrund":"Eckart Witzigmann hat 1989 „Das große Buch vom Reis“ (Teubner Edition) mitverfasst und dafür laut Wikipedia die „Goldene Feder“ der Gastronomischen Akademie Deutschlands erhalten. Was im Buch steht, habe ich nicht gesehen; diese Heimküchen-Fassung nutzt Reis auf österreichische Art als Süßspeise: Reis wird in Milch gegart, mit Eigelb gebunden und mit Eischnee aufgelockert, dazu Marillen (Aprikosen) aus der Wachau. Ein Klassiker, der so aus der Alpenküche vertraut ist. Nicht sein Rezept.","portionen":4,"zeit":{"vorbereitung":25,"garen":60,"ruhen":10},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Reis","liste":[{"menge":150,"einheit":"g","name":"Milchreis (Rundkornreis)"},{"menge":700,"einheit":"ml","name":"Vollmilch"},{"menge":0.5,"einheit":"Stück","name":"Vanilleschote","hinweis":"Mark ausgekratzt"},{"menge":60,"einheit":"g","name":"Zucker"},{"menge":1,"einheit":"Prise","name":"Salz"},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone","hinweis":"nur Schale, fein abgerieben"}]},{"gruppe":"Für den Auflauf","liste":[{"menge":3,"einheit":"Stück","name":"Eier","hinweis":"getrennt"},{"menge":40,"einheit":"g","name":"weiche Butter"},{"menge":400,"einheit":"g","name":"reife Marillen","hinweis":"halbiert und entsteint; ersatzweise Aprikosen aus dem Glas"},{"menge":1,"einheit":"EL","name":"Zucker","hinweis":"für den Eischnee"},{"menge":15,"einheit":"g","name":"Butter","hinweis":"für die Form"},{"menge":2,"einheit":"EL","name":"Semmelbrösel","hinweis":"für die Form"},{"menge":null,"einheit":"","name":"Staubzucker","hinweis":"zum Bestäuben"}]}],"ausruestung":["Topf mit dickem Boden","Auflaufform (ca. 24 cm)","Handrührgerät","Gummispatel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Halbiere die Marillen und entferne die Steine. Wenn sie sehr sauer sind, bestreue sie mit einem Esslöffel Zucker. Trenne die Eier, die Eiweiße dürfen kein Eigelb enthalten, sonst werden sie nicht steif. Fette die Auflaufform mit Butter ein und bestreue sie mit Bröseln. Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor.","dauer":10,"tipp":""},{"titel":"Milchreis kochen","aktion":"koecheln","text":"Bringe die Milch mit Vanillemark, Zucker, Salz und Zitronenschale in einem Topf mit dickem Boden zum Kochen. Rühre den Reis ein, reduziere die Hitze auf kleinste Stufe und lasse ihn zugedeckt 25 bis 30 Minuten quellen, bis er weich ist und die Milch fast aufgesogen hat. Rühre dabei öfter um, damit nichts anbrennt. Der Reis soll cremig, aber nicht trocken sein. Nimm den Topf vom Herd und lasse ihn 10 Minuten abkühlen.","dauer":35,"tipp":"Rundkornreis ist wichtig – er gibt Stärke ab und bindet."},{"titel":"Eigelb und Butter einrühren","aktion":"mischen","text":"Rühre die weiche Butter und die Eigelbe nacheinander in den lauwarmen Reis, bis eine cremige, glänzende Masse entsteht. Der Reis darf nicht mehr heiß sein, sonst stocken die Eigelbe. Schmecke ab: Er soll süß, zitronig und nach Vanille duften. Wenn die Masse zu fest ist, gib einen Schuss Milch dazu; ist sie zu flüssig, lass sie noch einige Minuten abkühlen.","dauer":5,"tipp":"Eigelb nur in den lauwarmen Reis geben."},{"titel":"Eischnee unterheben","aktion":"aufschlagen","text":"Schlage die Eiweiße mit einer Prise Salz auf mittlerer Stufe schaumig, gib dann den Zucker nach und nach dazu und schlage sie zu steifem, glänzendem Schnee. Der Schnee ist fertig, wenn er in Spitzen steht und beim Umdrehen der Schüssel nicht herausfällt. Hebe ihn in zwei Portionen mit einem Spatel vorsichtig unter die Reismasse, ohne zu rühren. So bleibt der Auflauf luftig.","dauer":8,"tipp":"Heben, nicht rühren – sonst fällt die Luft heraus."},{"titel":"Schichten","aktion":"schichten","text":"Gib die Hälfte der Reismasse in die Form und streiche sie glatt. Lege die Marillenhälften mit der Schnittfläche nach unten dicht darauf und bedecke sie mit der restlichen Reismasse. Streiche die Oberfläche glatt und setze einige Marillen zur Dekoration obenauf. Streue einen Teelöffel Zucker darüber, damit er karamellisiert. Die Form soll zu etwa drei Vierteln gefüllt sein, damit der Auflauf Platz zum Aufgehen hat.","dauer":8,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Backe den Auflauf in der Mitte des Ofens 35 bis 40 Minuten, bis die Oberfläche goldbraun ist und die Masse beim leichten Rütteln der Form nicht mehr wackelt. Mit einem Holzspieß prüfst du die Garprobe: Er muss feucht, aber ohne flüssigen Teig herauskommen. Die Marillen sind weich und geben Saft ab. Wenn die Oberfläche zu schnell bräunt, lege Alufolie locker darüber.","dauer":40,"tipp":"Ofentür in den ersten 25 Minuten geschlossen halten."},{"titel":"Anrichten","aktion":"anrichten","text":"Lasse den Auflauf 10 Minuten ruhen, damit er sich setzt, und bestäube ihn mit Staubzucker. Serviere ihn warm direkt aus der Form oder in Stücken, dazu Vanillesauce oder ein Marillenmus. Er schmeckt lauwarm am besten; ausgekühlt wird er fester, bleibt aber köstlich. Reste kannst du am nächsten Tag in Scheiben schneiden und kurz in Butter anbraten.","dauer":10,"tipp":""}],"profitipps":["Rundkornreis (Milchreis) verwenden, nicht Langkorn.","Eigelb nur in lauwarmen Reis rühren.","Eischnee sehr vorsichtig unterheben.","Marillen mit der Schnittfläche nach unten legen.","Ofentür möglichst nicht öffnen."],"varianten":["Mit Pflaumen oder Kirschen statt Marillen.","Mit Rosinen und etwas Rum.","Mit Mandelblättchen bestreut.","Als Individualförmchen im Wasserbad."],"beilagen":["Vanillesauce","Beerenmus","Schlagobers"],"getraenk":"Süßer Muskateller oder Tee","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann war Mitautor von „Das große Buch vom Reis“ (1989), für das er laut Wikipedia die „Goldene Feder“ der Gastronomischen Akademie Deutschlands erhielt. Ob ein Reisauflauf im Buch steht, habe ich nicht geprüft; dies ist eine klassische österreichische Heimküchen-Fassung im Geist des Reisbuchs, nicht sein Rezept.","quelle":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"quellen":[{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"},{"titel":"Risotto – Wikipedia (Reissorten, Stärke, Technik)","url":"https://de.wikipedia.org/wiki/Risotto"}],"bild":"auflauf","farben":["#f0c06a","#f7e6b8","#e08a4a"],"schlagworte":["Reis","Marillen","Süßspeise"],"vegetarisch_moeglich":true},{"id":"oesterreich-hechtfilet-baerlauchrahm-witzigmann","name":"Hechtfilet auf Bärlauchrahm mit Petersilienkartoffeln nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Österreich / Bayern","beliebtheit":48,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Kurz gebratener Hecht auf einer grünen Bärlauch-Rahmsauce – mit Petersilienkartoffeln ein frühlingshaftes Fischgericht.","hintergrund":"Laut Beschreibung enthält Eckart Witzigmanns Buch „Meine besten Bärlauchrezepte“ (2017) auch Gerichte mit Hecht; wie sein Rezept aussieht, habe ich nicht gesehen. Dies ist deshalb eine Heimküchen-Fassung: Hecht ist ein magerer Raubfisch mit festem Fleisch, das laut Wikipedia relativ trocken ist, weshalb er kurz gebraten und mit einer cremigen Sauce serviert wird. Wer keinen Hecht findet, nimmt Zander. Nicht sein Originalrezept.","portionen":4,"zeit":{"vorbereitung":30,"garen":30,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Fisch","liste":[{"menge":4,"einheit":"Stück","name":"Hechtfilets","hinweis":"je ca. 160 g, ohne Haut und Gräten; alternativ Zander"},{"menge":2,"einheit":"EL","name":"Mehl","hinweis":"zum Wenden"},{"menge":2,"einheit":"EL","name":"Butterschmalz"},{"menge":20,"einheit":"g","name":"Butter","hinweis":"zum Aromatisieren"},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Für den Bärlauchrahm","liste":[{"menge":2,"einheit":"Stück","name":"Schalotten","hinweis":"fein gewürfelt"},{"menge":100,"einheit":"ml","name":"trockener Weißwein"},{"menge":150,"einheit":"ml","name":"Fischfond","hinweis":"aus dem Glas oder selbst gekocht"},{"menge":150,"einheit":"ml","name":"Sahne"},{"menge":40,"einheit":"g","name":"frischer Bärlauch"},{"menge":1,"einheit":"EL","name":"Zitronensaft"},{"menge":30,"einheit":"g","name":"kalte Butter","hinweis":"in Würfeln"}]},{"gruppe":"Für die Petersilienkartoffeln","liste":[{"menge":600,"einheit":"g","name":"festkochende Kartoffeln"},{"menge":30,"einheit":"g","name":"Butter"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"fein gehackt"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["große beschichtete Pfanne","Topf für die Kartoffeln","kleiner Topf für die Sauce","Pürierstab","Fischpinzette"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schäle die Kartoffeln und schneide sie in gleichmäßige Stücke oder tourniere sie oval. Würfle die Schalotten fein, wasche den Bärlauch und lasse ihn abtropfen. Tupfe die Hechtfilets mit Küchenpapier trocken und fahre mit den Fingern über das Fleisch: Verbliebene Gräten, vor allem die Y-Gräten in der Rückenpartie, ziehst du mit einer Pinzette. Trockene Oberfläche braucht der Fisch, damit er bräunt, statt zu dämpfen. Lege das Mehl auf einen Teller.","dauer":12,"tipp":"Gräten mit den Fingerspitzen ertasten und mit der Pinzette ziehen."},{"titel":"Kartoffeln garen","aktion":"kochen","text":"Setze die Kartoffeln in kaltem Salzwasser auf, bringe sie zum Kochen und gare sie bei schwacher Hitze 15 bis 18 Minuten, bis ein Messer ohne Widerstand eindringt. Gieße ab und lasse sie ausdampfen. Halte sie im geschlossenen Topf warm, bis der Fisch fertig ist. Die Butter schmilzt du erst später, damit die Petersilie frisch bleibt.","dauer":18,"tipp":"In kaltem Wasser aufsetzen, damit sie gleichmäßig garen."},{"titel":"Saucenbasis einkochen","aktion":"reduzieren","text":"Schwitze die Schalotten in einem kleinen Topf mit einem Stück Butter glasig, ohne Farbe. Gieße den Wein dazu und koche ihn fast vollständig ein; er soll nur noch einen Löffel sirupartiger Flüssigkeit zurücklassen und mild-säuerlich duften. Gieße den Fischfond zu und lasse alles auf etwa die Hälfte reduzieren. Das dauert 8 bis 10 Minuten und bringt Tiefe. Gib die Sahne dazu und lasse die Sauce 5 Minuten leicht sämig einkochen.","dauer":15,"tipp":"Erst Wein reduzieren, dann Fond – so wird die Basis kräftig."},{"titel":"Fisch vorbereiten","aktion":"vorbereiten","text":"Salze die Filets erst jetzt, kurz vor dem Braten, damit sie nicht Wasser ziehen. Wende sie in Mehl und klopfe das Überschüssige ab; die dünne Schicht hilft beim Bräunen und schützt das magere Fleisch. Erhitze das Butterschmalz in der Pfanne bei mittlerer bis hoher Hitze, bis es leicht schimmert. Die Pfanne ist bereit, wenn ein Tropfen Wasser sofort zischt. Lege die Filets mit der schönen Seite zuerst hinein.","dauer":5,"tipp":""},{"titel":"Hecht braten","aktion":"braten","text":"Brate die Filets 2 bis 3 Minuten, ohne sie zu bewegen, bis sich ein goldbrauner Rand bildet. Wende sie vorsichtig mit einem Fischheber, gib die Butter dazu und brate sie weitere 2 Minuten; ihre Mitte soll gerade eben nicht mehr glasig sein, Kerntemperatur etwa 58 bis 60 °C. Hecht ist mager und wird bei zu langem Braten trocken und fasrig, also lieber eine Minute weniger. Nimm die Pfanne vom Herd und lasse die Filets 2 Minuten ruhen.","dauer":6,"tipp":"Lieber kurz braten – Hecht verzeiht Übergaren nicht."},{"titel":"Bärlauch in die Sauce","aktion":"puerieren","text":"Gib den Bärlauch grob geschnitten in die heiße Sauce und püriere sie mit dem Pürierstab kurz und fein, bis sie hellgrün und glatt ist. Der Bärlauch soll nur ziehen, nicht kochen, denn Hitze macht ihn bitter und graugrün. Rühre die kalte Butter in Würfeln ein und schwenke den Topf, bis die Sauce glänzt (Montieren). Schmecke mit Zitronensaft, Salz und Pfeffer ab. Wenn sie zu dick ist, verdünne sie mit einem Löffel Fond.","dauer":4,"tipp":"Pürieren, nicht mehr aufkochen – sonst verliert sie Farbe."},{"titel":"Kartoffeln schwenken","aktion":"anbraten","text":"Schmelze die Butter in dem Kartoffeltopf, gib die gehackte Petersilie dazu und schwenke die Kartoffeln so lange, bis sie rundum glänzen und grün betupft sind. Salze leicht nach. Die Petersilie darf nur kurz mit der Butter in Kontakt kommen, damit sie frisch grün bleibt. Halte die Kartoffeln bis zum Anrichten zugedeckt.","dauer":3,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Gib einen Spiegel der Bärlauchsauce auf vorgewärmte Teller und setze das Hechtfilet darauf. Lege die Petersilienkartoffeln daneben und streue Bärlauchstreifen oder Schnittlauchröllchen darüber. Serviere sofort, denn die Sauce verliert beim Stehen Farbe und der Fisch Saftigkeit. Ein Salat aus jungen Blättern mit Zitronendressing ergänzt das Gericht.","dauer":2,"tipp":""}],"profitipps":["Hecht trocken tupfen und Gräten gründlich ziehen.","Fisch erst kurz vor dem Braten salzen.","Kerntemperatur 58–60 °C ist ideal.","Bärlauch nur pürieren, nicht kochen.","Alternativen: Zander oder Seelachs."],"varianten":["Mit gebratenem Spargel statt Kartoffeln.","Als Hechtklößchen (Klassiker mit Hecht).","Mit gedämpftem Wirsing.","Mit Weißweinsauce und Kapern."],"beilagen":["Petersilienkartoffeln","Gedünsteter Spinat","Karotten-Kohlrabi-Gemüse"],"getraenk":"Trockener Riesling oder Weißburgunder","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Hecht – Wikipedia (Küche, Gräten, mageres Fleisch)","url":"https://de.wikipedia.org/wiki/Hecht"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"fisch","farben":["#8fae5a","#efe5c0","#d8c88a"],"schlagworte":["Bärlauch","Hecht","Frühling"],"vegetarisch_moeglich":false},{"id":"oesterreich-spargel-baerlauchmayonnaise-witzigmann","name":"Weißer Spargel mit Bärlauchmayonnaise nach Art von Eckart Witzigmann","originalname":"","kueche":"oesterreich","region":"Österreich","beliebtheit":48,"hauptkategorie":"vegetarisch","gang":"vorspeise","kurz":"Zarter weißer Spargel, lauwarm serviert mit einer sämigen, grünen Bärlauchmayonnaise.","hintergrund":"Eine Bärlauchmayonnaise gehört laut Beschreibung zu den Zubereitungen in Eckart Witzigmanns Bärlauchbuch (2017); wie sein Rezept lautet, habe ich nicht gesehen. Die Saisons von weißem Spargel und Bärlauch überschneiden sich im April, und beide passen deshalb wunderbar zusammen. Dies ist eine Heimküchen-Fassung mit selbst gerührter Mayonnaise – der Trick liegt in der Emulsion aus Eigelb und Öl. Nicht sein Rezept.","portionen":4,"zeit":{"vorbereitung":30,"garen":15,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Spargel","liste":[{"menge":1,"einheit":"kg","name":"weißer Spargel","hinweis":"dicke Stangen"},{"menge":1,"einheit":"TL","name":"Zucker"},{"menge":1,"einheit":"TL","name":"Salz"},{"menge":20,"einheit":"g","name":"Butter"},{"menge":2,"einheit":"Scheibe","name":"Zitrone"},{"menge":2,"einheit":"l","name":"Wasser"}]},{"gruppe":"Für die Bärlauchmayonnaise","liste":[{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":"Zimmertemperatur"},{"menge":1,"einheit":"TL","name":"mittelscharfer Senf"},{"menge":1,"einheit":"EL","name":"Zitronensaft"},{"menge":200,"einheit":"ml","name":"neutrales Öl","hinweis":"Raps- oder Sonnenblumenöl"},{"menge":30,"einheit":"g","name":"frischer Bärlauch"},{"menge":null,"einheit":"","name":"Salz und weißer Pfeffer","hinweis":"nach Geschmack"}]},{"gruppe":"Zum Servieren","liste":[{"menge":4,"einheit":"Scheibe","name":"gekochter Schinken","hinweis":"optional"},{"menge":300,"einheit":"g","name":"kleine Kartoffeln","hinweis":"optional, gedämpft"}]}],"ausruestung":["großer breiter Topf","Sparschäler","Pürierstab mit hohem Becher","Küchenpapier"],"schritte":[{"titel":"Spargel schälen","aktion":"vorbereiten","text":"Schäle den Spargel von knapp unter dem Kopf nach unten gleichmäßig mit dem Sparschäler und schneide das trockene untere Ende etwa 2 Zentimeter ab. Hebe Schalen und Enden auf, denn sie geben dem Kochwasser Geschmack. Lege die geschälten Stangen in ein feuchtes Küchentuch, damit sie nicht austrocknen. Prüfe sie: Sie sollen glatt und cremeweiß sein, ohne holzige Fäden.","dauer":12,"tipp":"Schalen und Enden ins Kochwasser – sie liefern Aroma."},{"titel":"Spargel garen","aktion":"kochen","text":"Bringe das Wasser mit Salz, Zucker, Butter, Zitronenscheiben und den Spargelschalen zum Kochen und lasse es 10 Minuten ziehen; dann siebst du die Schalen ab. Lege den Spargel in das siedende Wasser und gare ihn 8 bis 12 Minuten, je nach Dicke, bis er sich zart biegen lässt, aber noch Biss hat. Das Wasser soll nur leicht köcheln. Hebe die Stangen vorsichtig heraus und lasse sie auf Küchenpapier abtropfen.","dauer":15,"tipp":"Spargel soll sich biegen, aber nicht abknicken."},{"titel":"Kartoffeln dämpfen","aktion":"daempfen","text":"Wasche die kleinen Kartoffeln und dämpfe sie 18 bis 20 Minuten im Dämpfeinsatz über kochendem Wasser, bis ein Messer ohne Widerstand hineingleitet. Sie behalten im Dampf mehr Aroma als im Wasser und werden nicht wässrig. Pelle sie noch warm, wenn du magst, und halte sie zugedeckt warm. Salz und eine Spur Butter genügen; die Mayonnaise liefert den Rest. Das kann parallel zum Spargel laufen, damit alles gleichzeitig fertig wird.","dauer":18,"tipp":"Dämpfen statt Kochen – die Kartoffeln bleiben aromatischer."},{"titel":"Mayonnaise-Basis rühren","aktion":"aufschlagen","text":"Gib Eigelb, Senf, Zitronensaft und eine Prise Salz in einen hohen Becher und lasse alles auf Zimmertemperatur kommen – kalte Zutaten lassen die Emulsion leicht reißen. Gib das Öl nach und nach in dünnem Strahl dazu und püriere bei niedriger Stufe, bis die Masse eindickt und cremig wird. Wenn sie zu dick wird, gib einen Teelöffel Wasser dazu. Sie soll so fest sein, dass der Löffel steht.","dauer":8,"tipp":"Öl nur tropfenweise zugeben, bis die Emulsion steht."},{"titel":"Mayonnaise retten","aktion":"abschmecken","text":"Gerinnt die Mayonnaise – sie sieht dann körnig oder ölig aus –, ist das kein Beinbruch: Gib ein frisches Eigelb in eine saubere Schüssel und rühre die geronnene Masse tropfenweise darunter, bis sie wieder bindet. Meist liegt es daran, dass das Öl zu schnell oder die Zutaten zu kalt waren. Ist sie zu dick, verdünne sie mit einem Teelöffel lauwarmem Wasser, ist sie zu dünn, rühre noch etwas Öl ein. Die richtige Konsistenz ist cremig und glänzend, sie soll auf dem Löffel stehen bleiben.","dauer":3,"tipp":"Ein zusätzliches Eigelb rettet fast jede geronnene Mayonnaise."},{"titel":"Bärlauch einarbeiten","aktion":"puerieren","text":"Hacke den Bärlauch fein oder püriere ihn in einem hohen Becher mit zwei Esslöffeln der Mayonnaise glatt. Rühre das grüne Püree in die restliche Mayonnaise, bis sie gleichmäßig hellgrün ist. Schmecke mit Salz, weißem Pfeffer und einigen Tropfen Zitronensaft ab. Wegen des rohen Eis in der Mayonnaise bewahre sie kühl auf und serviere sie am selben Tag.","dauer":5,"tipp":"Mayonnaise mit rohem Ei nur frisch zubereiten und kühl halten."},{"titel":"Spargel abtropfen und warm halten","aktion":"ruhen","text":"Lege die gegarten Stangen auf ein Küchentuch und lasse sie 2 bis 3 Minuten abtropfen, damit sich kein Wasser auf dem Teller sammelt und die Mayonnaise nicht verdünnt. Lege sie dann auf einen vorgewärmten Teller und decke sie locker mit Folie ab; in der Restwärme bleiben sie lauwarm und aromatisch. Spargel schmeckt am besten bei Zimmer- bis Körpertemperatur, nicht heiß. Wenn du den Schinken dazu servierst, rolle ihn in dieser Zeit locker auf.","dauer":3,"tipp":"Lauwarmer Spargel schmeckt intensiver als heißer."},{"titel":"Anrichten","aktion":"anrichten","text":"Richte den lauwarmen Spargel fächerförmig auf vorgewärmten Tellern an. Gib einen Löffel Mayonnaise daneben oder darüber und lege nach Wunsch Schinken oder Kartoffeln dazu. Streue Bärlauchstreifen und etwas grobes Salz darüber. Serviere sofort, denn Spargel schmeckt frisch am besten. Dazu passt ein trockener Weißwein.","dauer":3,"tipp":"Lauwarm schmeckt Spargel am aromatischsten."}],"profitipps":["Spargel gleichmäßig und gründlich schälen.","Mayonnaise-Zutaten Zimmertemperatur.","Öl langsam zugeben.","Bärlauch separat pürieren, dann einrühren.","Mayonnaise am selben Tag verzehren."],"varianten":["Mit Sauce Hollandaise und Bärlauch.","Mit Rührei und Lachsschinken.","Mit grünem Spargel gebraten.","Mit Joghurt-Bärlauch-Dip statt Mayonnaise."],"beilagen":["Neue Kartoffeln","Gekochter Schinken","Räucherlachs"],"getraenk":"Grüner Veltliner oder Silvaner","koeche":[{"name":"Eckart Witzigmann","bezug":"Witzigmann hat 2017 das Buch „Meine besten Bärlauchrezepte“ veröffentlicht (20 Rezepte; laut Produktseite hat er den Bärlauch vor rund 40 Jahren für die Küche wiederentdeckt). Die Beschreibung nennt u. a. Bärlauchbutter, -creme, -öl, -pesto, -mayonnaise, einen Kräuter-Bärlauch-Salat, Knödel und Knöpfle mit Spinat, Aufläufe sowie Gerichte mit Hecht und Zicklein. Diese Fassung ist eine freie Heimküchen-Version in diesem Geist; sein konkretes Rezept habe ich nicht eingesehen.","quelle":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"}],"quellen":[{"titel":"Eckart Witzigmann: Meine besten Bärlauchrezepte (2017) – Buchbeschreibung","url":"https://www.hugendubel.de/de/buch_gebunden/eckart_witzigmann-meine_besten_baerlauchrezepte-28196029-produkt-details.html"},{"titel":"Bärlauch – Wikipedia (Verwendung, Erntezeit, Verwechslungsgefahr)","url":"https://de.wikipedia.org/wiki/B%C3%A4rlauch"},{"titel":"Eckart Witzigmann – Wikipedia (Biografie, Stationen, Bücher, Auszeichnungen)","url":"https://de.wikipedia.org/wiki/Eckart_Witzigmann"}],"bild":"teller","farben":["#e8dfb0","#9bb36a","#f4ecd0"],"schlagworte":["Spargel","Bärlauch","Frühling"],"vegetarisch_moeglich":true},{"id":"oesterreich-powidltascherl-zwetschenkompott-lafer","name":"Powidltascherl mit Zwetschenkompott nach Art von Johann Lafer","originalname":"","kueche":"oesterreich","region":"Böhmen / Österreich","beliebtheit":46,"hauptkategorie":"suess","gang":"dessert","kurz":"Zarte Kartoffelteigtaschen mit würzigem Powidl-Zwetschgenmus, in Butterbröseln mit Orange, Zitrone und Zimt gewälzt und mit Rotwein-Zwetschgenkompott serviert.","hintergrund":"Powidltascherl gehören zu den klassischen Mehlspeisen der österreichisch-böhmischen Küche: Teigtaschen aus Kartoffelteig, gefüllt mit eingekochtem Zwetschgenmus (Powidl) und in gerösteten Bröseln gewälzt. Der Steirer Johann Lafer hat eine Version mit Orangen- und Zitronenabrieb in den Bröseln und Rotwein-Johannisbeersaft-Kompott für die Zeitschrift „tina“ veröffentlicht. Dass Mehlspeisen in Österreich auch als Hauptgericht oder als süße Nachspeise gegessen werden, gehört zur Kultur; die Powidltascherl sind besonders im Herbst zur Zwetschgenzeit beliebt. Diese Fassung ist eine Heimküchen-Version nach den veröffentlichten Zutaten und dem Aufbau, nicht das exakte Originalrezept.","portionen":4,"zeit":{"vorbereitung":60,"garen":90,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Teig","liste":[{"menge":250,"einheit":"g","name":"mehligkochende Kartoffeln"},{"menge":30,"einheit":"g","name":"Kartoffelstärke"},{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":"Größe M, 1 für den Teig, 1 zum Bestreichen"},{"menge":25,"einheit":"g","name":"weiche Butter"},{"menge":null,"einheit":"","name":"Salz"},{"menge":null,"einheit":"","name":"Mehl","hinweis":"für die Arbeitsfläche"}]},{"gruppe":"Für die Füllung","liste":[{"menge":150,"einheit":"g","name":"Powidl (Zwetschgenmus)","hinweis":"aus dem Glas, möglichst ohne Zusatz von viel Zucker"},{"menge":10,"einheit":"ml","name":"Rum","hinweis":"1 cl"},{"menge":1,"einheit":"Stück","name":"unbehandelte Orange","hinweis":"Schale"}]},{"gruppe":"Für das Zwetschgenkompott","liste":[{"menge":300,"einheit":"g","name":"Zwetschgen"},{"menge":40,"einheit":"g","name":"Zucker"},{"menge":1,"einheit":"EL","name":"Vanillezucker"},{"menge":150,"einheit":"ml","name":"Rotwein"},{"menge":100,"einheit":"ml","name":"schwarzer Johannisbeersaft"},{"menge":2,"einheit":"TL","name":"Kartoffelstärke"}]},{"gruppe":"Für die Brösel","liste":[{"menge":50,"einheit":"g","name":"Butter"},{"menge":1,"einheit":"Stück","name":"unbehandelte Orange","hinweis":"Schale"},{"menge":1,"einheit":"Stück","name":"unbehandelte Zitrone","hinweis":"Schale"},{"menge":0.5,"einheit":"TL","name":"gemahlener Zimt"},{"menge":50,"einheit":"g","name":"Paniermehl"},{"menge":null,"einheit":"","name":"Puderzucker","hinweis":"zum Bestäuben"}]}],"ausruestung":["Kartoffelpresse","runder Ausstecher (8 cm)","weiter Topf","große Pfanne"],"schritte":[{"titel":"Kartoffeln backen","aktion":"backen","text":"Wasche die Kartoffeln, reibe sie trocken, wickle sie in Alufolie und backe sie im auf 175 °C Ober-/Unterhitze (150 °C Umluft) vorgeheizten Ofen eine bis eineinhalb Stunden. Sie sind fertig, wenn ein Holzstäbchen ohne Widerstand hineingleitet und sie innen mehlig weich sind. Gebackene Kartoffeln enthalten weniger Wasser als gekochte, und genau das braucht der Teig, damit er nicht klebrig wird.","dauer":75,"tipp":"Nicht kochen! Gekochte Kartoffeln haben zu viel Wasser und der Teig wird klebrig."},{"titel":"Zwetschgen und Kompottsud","aktion":"reduzieren","text":"Wasche die Zwetschgen, halbiere sie, entferne die Steine und schneide sie in Spalten. Karamellisiere Zucker und Vanillezucker in einer Pfanne bei mittlerer Hitze, bis er goldbraun ist, und lösche mit Rotwein und Johannisbeersaft ab. Lass alles etwa fünf Minuten einkochen. Rühre die Stärke mit etwas kaltem Wasser glatt, binde den Sud und koche ihn kurz auf, bis er glänzt und leicht dicklich ist.","dauer":8,"tipp":""},{"titel":"Kompott fertigstellen","aktion":"abseihen","text":"Gib die Zwetschgenspalten in den heißen Sud und lasse sie darin abkühlen. Sie garen durch die Restwärme gerade so weit, dass sie weich, aber noch formstabil sind. Das Kompott wird später lauwarm oder kalt serviert; es schmeckt nach Rotwein, Beeren und Vanille. Er schmeckt nach Wein, Beeren und Vanille und passt später ideal zu den warmen, buttrigen Tascherl; du kannst ihn gut schon am Vortag zubereiten.","dauer":20,"tipp":""},{"titel":"Kartoffelteig bereiten","aktion":"puerieren","text":"Schäle die noch heißen Kartoffeln vorsichtig (Topflappen oder Tuch) und presse sie zweimal durch die Kartoffelpresse in eine Schüssel. Rühre ein Eigelb unter, arbeite die Kartoffelstärke nach und nach ein, bis sie vollständig aufgenommen ist, und knete 25 g weiche Butter unter. Würze mit einer Prise Salz. Der Teig sollte geschmeidig und leicht formbar sein und nicht mehr an den Händen kleben.","dauer":5,"tipp":"Kartoffeln heiß verarbeiten, sonst wird der Teig zäh."},{"titel":"Füllung abschmecken","aktion":"mischen","text":"Verrühre den Powidl mit dem Rum und der abgeriebenen Orangenschale, bis alles gleichmäßig verteilt ist. Die Füllung sollte kräftig nach Pflaume, Zitrus und einem Hauch Alkohol duften. Wenn sie sehr fest ist, kannst du sie leicht erwärmen, damit sie sich besser in den Teig geben lässt. Probiere die Mischung vor dem Füllen und gib bei Bedarf einen Hauch Zimt oder etwas Zitronenschale dazu.","dauer":0,"tipp":""},{"titel":"Tascherl formen","aktion":"fuellen","text":"Rolle den Teig auf einer bemehlten Fläche dünn aus und steche Kreise mit 8 cm Durchmesser aus. Gib auf eine Hälfte jedes Kreises einen Klecks Powidl, bestreiche den Rand mit verquirltem Eigelb, klappe die andere Hälfte darüber und drücke den Rand mit einer Gabel fest an. So können die Tascherl beim Kochen nicht aufgehen. Die Reste knetest du kurz zusammen und rollst sie noch einmal aus.","dauer":15,"tipp":""},{"titel":"Tascherl garen","aktion":"kochen","text":"Bringe in einem weiten Topf reichlich Wasser mit etwas Salz zum Kochen, gib die Tascherl vorsichtig hinein und reduziere die Hitze, sodass das Wasser nur noch leise siedet. Lass sie 5 bis 8 Minuten ziehen; sie steigen nach oben, wenn sie gar sind. Zu heftiges Kochen würde sie aufplatzen lassen. Hebe sie mit einer Schaumkelle heraus und lasse sie gut abtropfen.","dauer":8,"tipp":""},{"titel":"Brösel rösten","aktion":"anbraten","text":"Zerlasse 50 g Butter in einer Pfanne, rühre Orangen- und Zitronenschale und Zimt ein und gib das Paniermehl dazu. Rühre bei mittlerer Hitze, bis die Brösel das Fett aufgesogen haben und wieder trocken und goldbraun sind; es duftet nach Zitrus und Zimt. Achte darauf, dass sie nicht zu dunkel werden. Gib die Brösel erst unmittelbar vor dem Anrichten über die Tascherl, damit sie nicht durchfeuchten und knusprig bleiben.","dauer":5,"tipp":""},{"titel":"Wälzen und anrichten","aktion":"anrichten","text":"Wende die abgetropften Tascherl in den warmen Bröseln, bis sie rundum bedeckt sind. Richte sie mit dem Zwetschgenkompott auf Tellern an und bestäube alles mit Puderzucker. Serviere sofort, solange die Tascherl warm sind; innen ist der Powidl heiß, also warne deine Gäste. Wer es üppiger mag, serviert zusätzlich einen Klecks Schlagsahne oder Vanilleeis, das den Zimt-Zitrus-Geschmack schön ausgleicht.","dauer":0,"tipp":""}],"profitipps":["Backofenkartoffeln statt gekochter verwenden – der Teig bleibt trockener und lässt sich besser verarbeiten.","Ränder gründlich festdrücken, damit nichts ausläuft.","Wasser nur leise sieden lassen, nicht sprudelnd kochen.","Brösel nicht zu dunkel rösten, sonst werden sie bitter.","Reste des Teigs kannst du zu Schupfnudeln formen."],"varianten":["Mit Marillenmarmelade statt Powidl","Mit Topfenteig statt Kartoffelteig","Mit Mohnbröseln","Mit Vanillesauce statt Kompott"],"beilagen":["Vanillesauce","Schlagobers"],"getraenk":"Süßer Riesling oder ein Glas Zwetschgenbrand","koeche":[{"name":"Johann Lafer","bezug":"Das Gericht ist als Rezept von Johann Lafer für die Zeitschrift „tina“ bei LECKER veröffentlicht; die Fassung hier folgt Zutaten und Aufbau, ist aber nicht sein Wortlaut.","quelle":"https://www.lecker.de/powidltascherl-mit-zwetschenkompott-johann-lafer-fuer-tina-35201.html"}],"quellen":[{"titel":"Powidltascherl mit Zwetschenkompott (Johann Lafer für tina) – LECKER","url":"https://www.lecker.de/powidltascherl-mit-zwetschenkompott-johann-lafer-fuer-tina-35201.html"}],"bild":"knoedel","farben":["#6b3a5a","#e8c39e","#f5e6c8"],"schlagworte":["Mehlspeise","Zwetschgen","Herbst"],"vegetarisch_moeglich":true},{"id":"oesterreich-tassenbuchteln-apfelspalten-lafer","name":"Tassenbuchteln mit karamellisierten Apfelspalten nach Art von Johann Lafer","originalname":"","kueche":"oesterreich","region":"Böhmen / Österreich","beliebtheit":43,"hauptkategorie":"suess","gang":"dessert","kurz":"Fluffige Hefebuchteln, in Espressotassen gebacken, dazu Apfelspalten in Vanille, Sternanis und Weißwein.","hintergrund":"Buchteln sind ein böhmisch-österreichischer Klassiker aus Hefeteig, traditionell in der Auflaufform gebacken und mit Vanillesauce oder Zwetschgenröster gegessen. Johann Lafer hat für die Zeitschrift „tina“ eine Einzelportions-Version veröffentlicht, bei der der Teig in Espressotassen aufgeht und backt – das sieht hübsch aus und portioniert sich von selbst. Die Äpfel werden in karamellisiertem Zucker angedünstet und mit Sternanis, Zimt und Weißwein aromatisiert. Diese Fassung ist eine Heimküchen-Version nach den veröffentlichten Zutaten und dem Aufbau, nicht das exakte Originalrezept.","portionen":6,"zeit":{"vorbereitung":45,"garen":20,"ruhen":90},"schwierigkeit":2,"zutaten":[{"gruppe":"Für die Buchteln","liste":[{"menge":60,"einheit":"ml","name":"lauwarme Milch"},{"menge":50,"einheit":"g","name":"Zucker"},{"menge":21,"einheit":"g","name":"frische Hefe","hinweis":"½ Würfel"},{"menge":220,"einheit":"g","name":"Mehl","hinweis":"plus etwas für Hände und Arbeitsfläche"},{"menge":2,"einheit":"Stück","name":"Eigelb","hinweis":"Größe M"},{"menge":2,"einheit":"Stück","name":"Eier","hinweis":"Größe M"},{"menge":1,"einheit":"Prise","name":"Salz"},{"menge":90,"einheit":"g","name":"weiche Butter","hinweis":"60 g für den Teig, 30 g zum Bestreichen"},{"menge":null,"einheit":"","name":"Fett für die 12 Espressotassen"}]},{"gruppe":"Für die Apfelspalten","liste":[{"menge":1,"einheit":"Stück","name":"Zitrone"},{"menge":4,"einheit":"Stück","name":"Äpfel","hinweis":"säuerlich, z. B. Boskoop"},{"menge":80,"einheit":"g","name":"Zucker"},{"menge":1,"einheit":"Stück","name":"Vanilleschote","hinweis":"Mark davon"},{"menge":2,"einheit":"Stück","name":"Sternanis"},{"menge":1,"einheit":"Stange","name":"Zimt"},{"menge":150,"einheit":"ml","name":"trockener Weißwein"}]},{"gruppe":"Zum Servieren","liste":[{"menge":null,"einheit":"","name":"Puderzucker"}]}],"ausruestung":["12 ofenfeste Espressotassen","große Schüssel","Pfanne","Pinsel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab; Eier, Butter und Milch sollten Zimmertemperatur haben, damit die Hefe gut arbeitet. Fette die zwölf Espressotassen sorgfältig mit Butter aus, auch an den Rändern. Schäle die Äpfel, viertle sie, entkerne sie und schneide sie in Spalten; presse die Zitrone aus und mische die Äpfel gleich mit dem Saft, damit sie nicht braun werden.","dauer":0,"tipp":""},{"titel":"Vorteig ansetzen","aktion":"gehen","text":"Erwärme die Milch leicht, sie sollte nur lauwarm sein, und löse darin 50 g Zucker und die Hefe auf. Gib das Mehl in eine große Schüssel, mache in der Mitte eine Mulde, gieße die Hefemilch hinein und verrühre sie mit etwas Mehl vom Rand zu einem dickflüssigen Brei. Decke die Schüssel ab und stelle sie an einen warmen Ort, bis sich das Volumen verdoppelt hat und die Oberfläche Bläschen wirft.","dauer":30,"tipp":"Zu heiße Milch tötet die Hefe – lauwarm heißt Handwärme."},{"titel":"Hefeteig kneten","aktion":"kneten","text":"Gib Eigelbe, Eier, Salz und 60 g weiche Butter zum Vorteig und knete alles kräftig zu einem glatten, geschmeidigen Teig, bis er sich vom Schüsselrand löst. Er sollte weich, aber nicht klebrig sein, und leicht glänzen. Decke ihn ab und lasse ihn etwa 30 Minuten an einem warmen Ort gehen, bis er sichtbar aufgegangen ist.","dauer":35,"tipp":""},{"titel":"Buchteln formen","aktion":"formen","text":"Forme den Teig mit bemehlten Händen zu einer langen Rolle und teile sie in zwölf gleich große Stücke. Rolle jedes Stück zu einer glatten Kugel und setze sie in die gefetteten Tassen. Decke sie ab und lasse sie noch 10 bis 15 Minuten gehen, sie sollten dann die Tasse etwas füllen und weich aussehen. Wenn du die Tassen mit einem Tuch abdeckst, bleibt die Oberfläche geschmeidig und bekommt keine trockene Haut.","dauer":15,"tipp":""},{"titel":"Buchteln backen","aktion":"backen","text":"Heize den Ofen auf 175 °C Ober-/Unterhitze (150 °C Umluft) vor. Schmelze 30 g Butter und bestreiche die Buchteln damit. Backe sie auf der mittleren Schiene 15 bis 20 Minuten, bis sie goldbraun sind und beim Klopfen auf den Boden hohl klingen. Werden sie zu dunkel, decke sie zum Schluss locker mit Alufolie ab.","dauer":18,"tipp":"Tassen vorher fetten, sonst lassen sich die Buchteln nicht lösen."},{"titel":"Apfelspalten karamellisieren","aktion":"braten","text":"Karamellisiere 80 g Zucker in einer Pfanne bei mittlerer Hitze, bis er goldbraun ist und nussig duftet. Gib die Apfelspalten hinein und dünste sie kurz an. Füge Vanillemark, Sternanis und Zimtstange hinzu, lösche mit dem Weißwein ab und lasse alles etwa fünf Minuten köcheln, bis die Äpfel weich, aber noch formstabil sind.","dauer":8,"tipp":""},{"titel":"Abkühlen lassen","aktion":"kuehlen","text":"Fülle die Apfelspalten mit dem Sud in eine Schüssel und lasse sie abkühlen. Dabei ziehen die Gewürze noch nach; entferne Sternanis und Zimtstange vor dem Servieren. Auch die Buchteln lässt du in den Tassen etwa fünf Minuten abkühlen, dann lösen sie sich besser. Du erkennst die richtige Konsistenz daran, dass die Sauce dickflüssig geworden ist und die Äpfel glänzend und weich aussehen. Wer es leichter mag, kann den Sud etwas weiter einkochen.","dauer":15,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Löse die Buchteln vorsichtig mit einem kleinen Messer aus den Tassen. Bestäube sie mit Puderzucker und richte sie mit den Apfelspalten auf Tellern an. Serviere sie noch leicht warm, dann sind sie innen am flauschigsten. Dazu passt eine Kugel Vanilleeis oder Vanillesauce. Probiere dazu einen kleinen Löffel Apfelspalten mit Sud, er soll süßlich, leicht säuerlich und nach Vanille und Anis schmecken.","dauer":0,"tipp":""}],"profitipps":["Hefeteig braucht Wärme und Ruhe – ein Backofen mit angeschalteter Lampe ist ein guter Platz zum Gehen.","Buchteln nicht zu dunkel backen, sonst werden sie trocken.","Tassen großzügig fetten, auch am Rand.","Äpfel nicht zu lange kochen, sie sollen Biss behalten.","Der Teig lässt sich über Nacht im Kühlschrank gehen."],"varianten":["Mit Powidl-Füllung","Mit Vanillesauce","Im Blech gebacken","Mit Zwetschgenröster statt Äpfeln"],"beilagen":["Vanillesauce","Vanilleeis"],"getraenk":"Milchkaffee oder süßer Riesling","koeche":[{"name":"Johann Lafer","bezug":"Das Gericht ist als Rezept von Johann Lafer für die Zeitschrift „tina“ bei LECKER veröffentlicht; die Fassung hier folgt Zutaten und Aufbau, ist aber nicht sein Wortlaut.","quelle":"https://www.lecker.de/tassenbuchteln-mit-karamellisierten-apfelspalten-johann-lafer-fuer-tina-43877.html"}],"quellen":[{"titel":"Tassenbuchteln mit karamellisierten Apfelspalten (Johann Lafer für tina) – LECKER","url":"https://www.lecker.de/tassenbuchteln-mit-karamellisierten-apfelspalten-johann-lafer-fuer-tina-43877.html"}],"bild":"dessert","farben":["#d9a25a","#f5e0b0","#8a5a2a"],"schlagworte":["Hefeteig","Äpfel","Mehlspeise"],"vegetarisch_moeglich":true}]);
